WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[2] = { title = "Sharptalon's Claw", description = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.\n\nSenani Thunderheart at the Silverwind Refuge will no doubt be interested in seeing this trophy as proof of your deeds.", objectives = "" }
WordHunterWoW_QuestEN[11] = { title = "Riverpaw Gnoll Bounty", description = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east.\n\nThe Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.", objectives = "" }
WordHunterWoW_QuestEN[23] = { title = "Ursangous' Paw", description = "The mighty bear Ursangous is no more!\n\nThe small quarter-crescent emblem on its paw indicates that this beast was trained by the night elves to prowl the forest in search of their enemies. There is no telling how many of your Horde allies fell to this creature.\n\nThe paw should be brought to Tarkan at Silverwind Refuge. He will be pleased that such a weapon has been removed from the enemy's arsenal.", objectives = "" }
WordHunterWoW_QuestEN[24] = { title = "Shadumbra's Head", description = "The once swift Shadumbra now lies still as you claim victory over it.\n\nThis legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale.\n\nCaptain Goggath at Hellscream's Watch will no doubt be delighted to receive the head of the slain nightsaber.", objectives = "" }
WordHunterWoW_QuestEN[25] = { title = "Simmer Down Now", description = "You should've seen it, {class}!\n\nThe elves thought Silverwind to be impenetrable. With its heavy defenses and their army of water elementals, they were almost right.\n\nAlmost.\n\nOne of our mages was able to summon a twisted elemental designed to send the others into a chaotic rage.\n\nAhh, the looks on their faces!\n\n<Tarkan laughs.>\n\nUnfortunately, the mage who summoned it fell in battle. Now I need someone to bring down our creation.", objectives = "" }
WordHunterWoW_QuestEN[35] = { title = "Further Concerns", description = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nI have here a Stormwind charger that will take you to Guard Thomas. Let me know if you wish to make use of the horse.", objectives = "" }
WordHunterWoW_QuestEN[37] = { title = "Find the Lost Guards", description = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.", objectives = "" }
WordHunterWoW_QuestEN[40] = { title = "A Fishy Peril", description = "{name}, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, {name}, speak to Dughan and persuade him to send more troops to the east!", objectives = "" }
WordHunterWoW_QuestEN[45] = { title = "Discover Rolf's Fate", description = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...", objectives = "" }
WordHunterWoW_QuestEN[46] = { title = "Bounty on Murlocs", description = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring Guard Thomas their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.", objectives = "" }
WordHunterWoW_QuestEN[47] = { title = "Gold Dust Exchange", description = "The kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[52] = { title = "Protect the Frontier", description = "Hail, {name}.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.", objectives = "" }
WordHunterWoW_QuestEN[54] = { title = "Report to Goldshire", description = "{name}, you are a {class} with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire. Goldshire lies along the southern road, past the border gates.", objectives = "" }
WordHunterWoW_QuestEN[59] = { title = "Cloth and Leather Armor", description = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, {name}, use it in the defense of Elwynn.\n\nEastvale is just east of this post across the bridge.", objectives = "" }
WordHunterWoW_QuestEN[60] = { title = "Kobold Candles", description = "Hello, good sir!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines... the Fargodeep Mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.", objectives = "" }
WordHunterWoW_QuestEN[62] = { title = "The Fargodeep Mine", description = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.", objectives = "" }
WordHunterWoW_QuestEN[71] = { title = "Report to Thomas", description = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.", objectives = "" }
WordHunterWoW_QuestEN[76] = { title = "The Jasperlode Mine", description = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.", objectives = "" }
WordHunterWoW_QuestEN[83] = { title = "Fine Linen Goods", description = "The thugs in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me linen scraps and I'll use them to fashion something for you.\n\nYou'll find those lawless criminals in pockets across Elwynn Forest.", objectives = "" }
WordHunterWoW_QuestEN[84] = { title = "Back to Billy", description = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!", objectives = "" }
WordHunterWoW_QuestEN[85] = { title = "Lost Necklace", description = "I lost my necklace and I think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure Vineyards east of here. \n\nGet my necklace back for me and you'll warm an old widow's heart.", objectives = "" }
WordHunterWoW_QuestEN[86] = { title = "Pie for Billy", description = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some tender boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.", objectives = "" }
WordHunterWoW_QuestEN[87] = { title = "Goldtooth", description = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run back to his den above the mine.  Go find that kobold and you'll find the necklace, I swear!", objectives = "" }
WordHunterWoW_QuestEN[88] = { title = "Princess Must Die!", description = "The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nIt just so happens that she's here now! Princess must die! Bring me her collar as proof of the deed and I'll give you something for your time!\n\nYou'll find Princess smack dab in the middle of our watermelon patch. Get her!", objectives = "" }
WordHunterWoW_QuestEN[106] = { title = "Young Lovers", description = "Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face!\n\nPlease, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.", objectives = "" }
WordHunterWoW_QuestEN[107] = { title = "Note to William", description = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.", objectives = "" }
WordHunterWoW_QuestEN[111] = { title = "Speak with Gramma", description = "Please, {name}, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.", objectives = "" }
WordHunterWoW_QuestEN[112] = { title = "Collecting Kelp", description = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.", objectives = "" }
WordHunterWoW_QuestEN[114] = { title = "The Escape", description = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.", objectives = "" }
WordHunterWoW_QuestEN[123] = { title = "The Collector", description = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Patterson at Eastvale Logging Camp.", objectives = "" }
WordHunterWoW_QuestEN[147] = { title = "Manhunt", description = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.", objectives = "" }
WordHunterWoW_QuestEN[171] = { title = "A Warden of the Alliance", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to do the stuff we did. Do you think we could find Craggle Wobbletop again and get a foam sword rack from him? I think he's still pushing that cart in the Canals outside the Trade District. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", objectives = "" }
WordHunterWoW_QuestEN[172] = { title = "Children's Week", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", objectives = "" }
WordHunterWoW_QuestEN[176] = { title = "WANTED:  \"Hogger\"", description = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should venture into the woods and deal with the beast.", objectives = "" }
WordHunterWoW_QuestEN[182] = { title = "The Troll Menace", description = "The trolls're acting up.  More than usual, I'd say.  We've seen them put together war parties before, but this time it's... different.\n\nWhat matters most, however, is the continued protection of Anvilmar.  I've no intention to let these trolls flank Anvilmar while its attention is turned towards troggs.  Go thin their ranks a bit.  They need to know that we're still not without defenses.", objectives = "" }
WordHunterWoW_QuestEN[184] = { title = "Furlbrow's Deed", description = "This is an old deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...", objectives = "" }
WordHunterWoW_QuestEN[185] = { title = "Tiger Hunting", description = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.  Start your hunt near our camp, to the south.", objectives = "" }
WordHunterWoW_QuestEN[186] = { title = "Tiger Stalking", description = "Young tigers are one thing.  Fully-grown cats are another.  Hunting the grown Stranglethorn tigers will prove an even greater challenge.\n\nThe adult cats normally spend their days south of Kurzen's Compound, east of the river.", objectives = "" }
WordHunterWoW_QuestEN[187] = { title = "Tiger Prowess", description = "Elder Stranglethorn tigers are the strongest of the bunch.  More than one {race} {class} has seen his own demise at the tip of those razor-sharp teeth and heavy claws.\n\nAjeck will be thrilled to know that you have bested them.  The largest pack of these elders can be found to the south, near the Sundering, on the border of the Cape of Stranglethorn.", objectives = "" }
WordHunterWoW_QuestEN[188] = { title = "Tiger Mastery", description = "Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males.  The hunters at Nesingwary's Expedition have hunted for her without success.  Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom'gol.\n\nThey call the beast Sin'Dall.\n\nYou resolve to do what no {race} has done before: hunt, kill, and claim the paw of Sin'Dall.", objectives = "" }
WordHunterWoW_QuestEN[190] = { title = "Panther Hunting", description = "If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter.  You should start out easy: just focus on the young panthers for now.  As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry.\n\nStart by heading east.  Return to me when you are a master panther hunter.", objectives = "" }
WordHunterWoW_QuestEN[191] = { title = "Panther Stalking", description = "The youngest panthers fell easily before you.  Panthers that have come of age will naturally be stronger, and quicker, and more difficult to defeat.\n\nLarger panther tracks lead to the west.", objectives = "" }
WordHunterWoW_QuestEN[192] = { title = "Panther Prowess", description = "Now the hard part.  As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot.  These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth.\n\nIf you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so.  They prowl to the southeast, across the river.", objectives = "" }
WordHunterWoW_QuestEN[193] = { title = "Panther Mastery", description = "You've almost proven yourself to be a master hunter of panthers.  Yet there is one panther which has eluded your grasp.\n\nSongs are sung about a mighty panther by the name of Bhag'thera.  You will see if you can use your skills to kill the great beast.\n\nBringing the Fang of Bhag'thera to Erlgadin should be proof enough that you are a master panther hunter.", objectives = "" }
WordHunterWoW_QuestEN[194] = { title = "Raptor Hunting", description = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill ten Stranglethorn raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.\n\nOkay, go west.", objectives = "" }
WordHunterWoW_QuestEN[195] = { title = "Raptor Stalking", description = "It is time to step up the challenge.  Venturing into the jungle and bagging 10 lashtail raptors should be sufficient.  They will certainly be stronger than the raptors you have already disposed of.\n\nThe lashtail raptors mainly stay southeast of here, near the Kal'ai Ruins.", objectives = "" }
WordHunterWoW_QuestEN[196] = { title = "Raptor Prowess", description = "A particularly cagey brand of raptor, known by locals as the \"Jungle Stalker\", prowls the forests to the south, across the river.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.\n\nKilling these Jungle Stalkers will undoubtedly make for a good tale around the fire.", objectives = "" }
WordHunterWoW_QuestEN[197] = { title = "Raptor Mastery", description = "Before returning to Nesingwary's Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture.  That beast goes by the name of Tethis, and he's been known to terrorize the southeastern corner of Northern Stranglethorn.\n\nBringing Tethis' talon back to that dwarf hunter should be proof that you are no ordinary {race}.", objectives = "" }
WordHunterWoW_QuestEN[208] = { title = "Big Game Hunter", description = "{name}, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bhag'thera, and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here... yet still, he taunts me from his roost to the south.  Kill King Bangalash and your hunting prowess is proven to be second to none.", objectives = "" }
WordHunterWoW_QuestEN[216] = { title = "Between a Rock and a Thistlefur", description = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our west blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n{name}, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[218] = { title = "Ice and Fire", description = "Soren did well to send you out on recon.  That's some good information you have right there.\n\nTrouble is, this just adds more work for us to do.  The trolls, confused as they are right now, still would like to kick the dwarves right out of Coldridge.  And I'm certainly not going to let some fiery demon turn our snowy valley into a mountain lake.\n\nThe troll leader, his servants, and the fire creature should all be in the cave to the southeast.  Take 'em all out.", objectives = "" }
WordHunterWoW_QuestEN[236] = { title = "Fueling the Demolishers", description = "{name}! About time you showed up. While the battle may be over, we still need to prepare for the next battle. Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We can't let them have the advantage in the next battle.", objectives = "" }
WordHunterWoW_QuestEN[239] = { title = "Westbrook Garrison Needs Help!", description = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.", objectives = "" }
WordHunterWoW_QuestEN[264] = { title = "Until Death Do Us Part", description = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, {name}! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!", objectives = "" }
WordHunterWoW_QuestEN[301] = { title = "Report to Ironforge", description = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.", objectives = "" }
WordHunterWoW_QuestEN[309] = { title = "Protecting the Shipment", description = "We need to get this powder to Ironband, but this cart isn't going anywhere now. It'll be a lot for us to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for us now that Saean is with them.\n\nI'll feel a lot better if you helped me watch over things. Miran can offload the powder kegs at camp while you and I protect the cart.", objectives = "" }
WordHunterWoW_QuestEN[313] = { title = "Forced to Watch from Afar", description = "The cataclysm drove the troggs to the surface in hordes, forcing the Frostmane trolls to flee for their lives. Unfortunately, they've decided to settle right on our doorstep and make trouble for us.\n\nI deployed Mountaineer Dunstan and his squad to the Grizzled Den just southwest of town to keep an eye on the wendigos that live there, but now I need to recall them to Kharanos. Find them and tell them to deploy those remote observation bots the gnomes provided, then return to Kharanos.", objectives = "" }
WordHunterWoW_QuestEN[314] = { title = "Protecting the Herd", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With Ironforge's troops already spread thin, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", objectives = "" }
WordHunterWoW_QuestEN[315] = { title = "The Perfect Stout", description = "I'm on a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, up on Shimmer Ridge to the northwest.  They use it in their strange, tribal rituals. We haven't found much use for it, but it has a unique taste... and I want to experiment with it in my brews!\n\nObtaining the shimmerweed will be dangerous, but I'll pay well for any you can \"borrow\" from the baskets in the troll village.", objectives = "" }
WordHunterWoW_QuestEN[332] = { title = "Wine Shop Advert", description = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of the famous Dalaran Noir.  You won't regret it!", objectives = "" }
WordHunterWoW_QuestEN[333] = { title = "Harlan Needs a Resupply", description = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.", objectives = "" }
WordHunterWoW_QuestEN[334] = { title = "Package for Thurman", description = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great {class} like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, {name}.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.", objectives = "" }
WordHunterWoW_QuestEN[351] = { title = "Find OOX-17/TN!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"", objectives = "" }
WordHunterWoW_QuestEN[353] = { title = "Stormpike's Delivery", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", objectives = "" }
WordHunterWoW_QuestEN[384] = { title = "Beer Basted Boar Ribs", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me some boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", objectives = "" }
WordHunterWoW_QuestEN[412] = { title = "Operation Recombobulation", description = "I should go back to Gnomeregan and continue researching a cure for irradiated gnomes.\n\nBut, I stayed behind in Kharanos because the town is my home and I wanted to help defend it from the Frostmane attacks. I've been working on maintaining and repairing the steam tanks.\n\nFor some reason, Frostmane scavengers have taken a liking to the gyromechanic gears I need to complete the repairs. They're all over the Frostmane Front to the southeast of town. Will you help me get those gears back?", objectives = "" }
WordHunterWoW_QuestEN[432] = { title = "Those Blasted Troggs!", description = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!", objectives = "" }
WordHunterWoW_QuestEN[433] = { title = "The Public Servant", description = "As a member of the Senate and the Explorers' League, I've taken it upon myself to investigate conditions at the quarry. The troggs have run wild!\n\nThey've made a mess of the Gol'Bolar quarry. As we dug deep into the earth, they poured out, destroying our equipment and trapping many of the miners below ground.\n\nWe have to get them out of there. I've had mages working overtime to enchant these runes of return. If you can get them to the trapped miners, they can return to the surface in safety.", objectives = "" }
WordHunterWoW_QuestEN[475] = { title = "A Troubling Breeze", description = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.", objectives = "" }
WordHunterWoW_QuestEN[476] = { title = "Gnarlpine Corruption", description = "The Gnarlpine tribe's corruption has returned!\n\nThey ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village. Something in the forest has corrupted Ursal the Mauler, their chieftain, and he is using the evil powers of the fel moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young {class}.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!", objectives = "" }
WordHunterWoW_QuestEN[483] = { title = "The Relics of Wakening", description = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den, tucked in the hill to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.", objectives = "" }
WordHunterWoW_QuestEN[485] = { title = "Find OOX-09/HL!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"", objectives = "" }
WordHunterWoW_QuestEN[486] = { title = "Ursal the Mauler", description = "Now the time has come to save the Druids of the Talon. If we fail now, {name}, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed. Travel northwest on the road and find the path north into The Cleft. Ursal's den will be there.", objectives = "" }
WordHunterWoW_QuestEN[487] = { title = "The Road to Darnassus", description = "The road to Darnassus must be kept safe. Corrupted furbolgs from the Gnarlpine tribe have been attacking travelers relentlessly.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily. We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, {class}. Their den lies up this northern path. Slay these Gnarlpine ambushers and report back to me.\n", objectives = "" }
WordHunterWoW_QuestEN[488] = { title = "Zenn's Bidding", description = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling {class} to perform my bidding.\n\nYou see, {name}, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain... reagents.  Fetch for me nightsaber fangs, strigid owl feathers and swatches of webwood spider silk.\n\nLet's keep this our little secret, {race}.", objectives = "" }
WordHunterWoW_QuestEN[489] = { title = "Seek Redemption!", description = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a {race}, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snack.", objectives = "" }
WordHunterWoW_QuestEN[543] = { title = "The Perenolde Tiara", description = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.", objectives = "" }
WordHunterWoW_QuestEN[583] = { title = "Welcome to the Jungle", description = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, {class}.\n\nGo and speak with him.  He's a chip off the old block, so perhaps he can give you some hunting pointers.", objectives = "" }
WordHunterWoW_QuestEN[648] = { title = "Rescue OOX-17/TN!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, near the Caverns of Time!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "" }
WordHunterWoW_QuestEN[743] = { title = "Dangers of the Windfury", description = "Thank you for taking the time to speak to me, {name}. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.", objectives = "" }
WordHunterWoW_QuestEN[744] = { title = "Preparation for Ceremony", description = "{name}, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", objectives = "" }
WordHunterWoW_QuestEN[746] = { title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", objectives = "" }
WordHunterWoW_QuestEN[749] = { title = "The Ravaged Caravan", description = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.", objectives = "" }
WordHunterWoW_QuestEN[751] = { title = "The Ravaged Caravan", description = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.", objectives = "" }
WordHunterWoW_QuestEN[761] = { title = "Swoop Hunting", description = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.", objectives = "" }
WordHunterWoW_QuestEN[764] = { title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", objectives = "" }
WordHunterWoW_QuestEN[765] = { title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", objectives = "" }
WordHunterWoW_QuestEN[768] = { title = "Gathering Leather", description = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.", objectives = "" }
WordHunterWoW_QuestEN[769] = { title = "Kodo Hide Bag", description = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.", objectives = "" }
WordHunterWoW_QuestEN[770] = { title = "The Demon Scarred Cloak", description = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Camp Sungraze should know of Ghost Howl's demise....", objectives = "" }
WordHunterWoW_QuestEN[773] = { title = "Rite of Wisdom", description = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, {name}.", objectives = "" }
WordHunterWoW_QuestEN[824] = { title = "Je'neu of the Earthen Ring", description = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.", objectives = "" }
WordHunterWoW_QuestEN[833] = { title = "A Sacred Burial", description = "Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\n\nBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.\n\nThey must be driven off with force, {name}.", objectives = "" }
WordHunterWoW_QuestEN[834] = { title = "Winds in the Desert", description = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment, which they PROMISED would get through, was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.", objectives = "" }
WordHunterWoW_QuestEN[835] = { title = "Securing the Lines", description = "Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"\n\nI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Harpies plague our supply routes.  If we kill the harpies, the caravans are safe.\n\nOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" You in, {name}?  Good... I recommend starting in the canyon to the east.", objectives = "" }
WordHunterWoW_QuestEN[836] = { title = "Rescue OOX-09/HL!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "" }
WordHunterWoW_QuestEN[840] = { title = "Conscript of the Horde", description = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.", objectives = "" }
WordHunterWoW_QuestEN[844] = { title = "Plainstrider Menace", description = "Are you familiar with plainstriders? Useless animals. Can't fly. Gamey. Brain the size of my knuckle. Too dim to get out of the way of a moving cart. I've broken more axles thanks to their thick skulls... Sometimes I think the quilboar intentionally frighten flocks of them into the path of our caravans just prior to an ambush.\n\nMake me proud, {class}. Cut a swath through those filthy birds to keep the roads free, and bring me their beaks as proof. ", objectives = "" }
WordHunterWoW_QuestEN[845] = { title = "The Zhevra", description = "If you wish to serve my beloved horde, you'll have to prove your strength to me, pup. You can cut your teeth by hunting zhevra. They may not be the strongest of beasts in the Barrens, but stay clear of their kick or you'll regret it.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.", objectives = "" }
WordHunterWoW_QuestEN[848] = { title = "Fungal Spores", description = "The oases of the Barrens hide a mystery. Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near the Forgotten Pools to the northwest. Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.", objectives = "" }
WordHunterWoW_QuestEN[850] = { title = "Kolkar Leaders", description = "The centaurs have plagued the tauren for years. And recently, the Kolkar centaurs of the Barrens have grown into a real threat. Normally they were disorganized in these lands, but new leaders have risen among them. Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane. He camps west of these Forgotten Pools.\n\nDefeat him, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[851] = { title = "Verog the Dervish", description = "Verog may be hard to find, but judging by the info you gathered, his mate Wyneth is always in his command tent just west of here. If we kill her, Verog will come running.\n\nRegthar sent us here to scout, but he also said we should seize any opportunity to upset the centaur chain of command if we can. Lure out Verog and kill him!", objectives = "" }
WordHunterWoW_QuestEN[852] = { title = "Hezrul Bloodmark", description = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him. Bring me Hezrul's Head, and I will mount it from this outpost, so that they may know fear.\n\nHezrul leads his people from the Lushwater Oasis, to the south.", objectives = "" }
WordHunterWoW_QuestEN[855] = { title = "Centaur Bracers", description = "The centaur leadership relies on a core of trusted, disciplined warriors to keep the others in line. If we reduce their numbers, the Kolkar will have no might with which to support their rage. And so, I have a bounty task for you.\n\nAround the Lushwater Oasis to the south, slay Kolkar Marauders and Stormseers to collect their bracers. Return when you have a heap of these trophies and the Horde will reward you well.", objectives = "" }
WordHunterWoW_QuestEN[858] = { title = "Ignition", description = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.\n\nWe need to get out of here on the double! Search the upper level of the derrick, Supervisor Lugwizzle should have a key for this shredder.\n\nHelp me out here!", objectives = "" }
WordHunterWoW_QuestEN[863] = { title = "The Escape", description = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?", objectives = "" }
WordHunterWoW_QuestEN[865] = { title = "It's Gotta be the Horn", description = "The raptors of the Barrens are smarter than raptors in other lands. I think all those smarts are hiding in their horns! If so, then I could grind their horns into powder and use it to make \"smart drinks.\" I'll make a fortune!\n\nHere's where you come in: I want the horn from the smartest raptor around. \"King Reaperclaw\" leads a whole pack of intelligent raptors up on the bluffs north of Ratchet. Bring me his horn! And don't get ripped to ribbons like everyone else I've sent!", objectives = "" }
WordHunterWoW_QuestEN[866] = { title = "Root Samples", description = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.", objectives = "" }
WordHunterWoW_QuestEN[867] = { title = "Harpy Raiders", description = "Since you're here, {class}, perhaps you can help me with a small problem. The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nThe most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nTake out Witchwing harpies of any kind in the Northwest and bring me 6 Witchwing Talons. That should be a good start...", objectives = "" }
WordHunterWoW_QuestEN[869] = { title = "To Track a Thief", description = "Animal tracks surround the wreckage, tracks made by enormous curved claws. They appear to be raptor tracks.\n\nYour first instinct is that raptor-riders assaulted the caravan, but the impressions aren't deep and there are no non-animal tracks to be seen.\n\nThe tracks head northeast of here toward the east side of Thorn Hill. The answer to this mystery must lie in its shadow.", objectives = "" }
WordHunterWoW_QuestEN[870] = { title = "The Forgotten Pools", description = "Have you felt the tremors, {class}? Something has cleaved this land in two. But we druids can sense other tremors, as well.\n\nLife is stirring in lands once dry and lifeless. The oases around the Crossroads are suddenly blooming. I can sense a power leaking its way to the surface, but from where? Is it related to the disaster that shattered the Barrens?\n\nWe must find the source. Travel to the Forgotten Pools, northwest of the Crossroads. Search its waters for a source of power, then return here.", objectives = "" }
WordHunterWoW_QuestEN[871] = { title = "In Defense of Far Watch", description = "All the quilboars are our enemies, {name}. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply caravans that roll through here from Orgrimmar. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart just south of here, where they've been raiding our camps near the river. Seek them out, and slay them.", objectives = "" }
WordHunterWoW_QuestEN[872] = { title = "The Far Watch Offensive", description = "Pigmen running amok right on the border of Durotar? Not on my watch! It is as they say, {name}: The best defense is crushing all who oppose you.\n\nOne of my scouts followed the quilboar after the last caravan raid, so we know where to strike. Kreenig Snarlsnout is the mastermind behind the attacks along the river. Crush him, {class}. Defeat him and disembowel his forces so that the attacks on this camp cease.\n\nSearch for a quilboar-infested cavern along the river, just south of our stables.", objectives = "" }
WordHunterWoW_QuestEN[875] = { title = "Harpy Lieutenants", description = "The only way to stop the harpy raiders is to destroy their chain of command. The harpies are led by fearless lieutenants, Witchwing Slayers. If the Slayers fall, the rest will follow.\n\nGo to the Dry Hills and cut down the Witchwing Slayers. Make sure they die painfully, {name}. We want those harpy wenches to know the idiocy of picking fights with the Horde.", objectives = "" }
WordHunterWoW_QuestEN[876] = { title = "Serena Bloodfeather", description = "The harpies you've killed mentioned their matron, Serena Bloodfeather. Judging from their vile hatred toward the Horde, she must hold some kind of deep-seated grudge. You decide to hunt down Serena Bloodfeather and end matters once and for all.", objectives = "" }
WordHunterWoW_QuestEN[877] = { title = "The Stagnant Oasis", description = "Can what's happening to the south happen here? Judging by what you found at the Forgotten Pools, these oases may be the key. Let's perform an experiment.\n\nHere, take these seeds I've collected from the summit here. They are dead and infertile, but carry them down to the Stagnant Oasis just below us. If there is a fissure there, then place the seeds within it... and observe. Report your findings back to Tonga at the Crossroads.", objectives = "" }
WordHunterWoW_QuestEN[880] = { title = "Altered Beings", description = "It will be important to study both plant and animal life impacted by the oases and the unusual energies you've discovered. The Stagnant Oasis below us is home to a species of snapjaw turtles. Recently their population has exploded. Moreover, the once peaceful animals are growing aggressive, as I learned the hard way before trekking up here.\n\n<Jerrik holds up a bandaged finger.>\n\nI suspect they've been altered by the oases. Collect their shells and take them to Tonga at Crossroads for further study. ", objectives = "" }
WordHunterWoW_QuestEN[881] = { title = "Echeyakee", description = "Whitemist, or 'Echeyakee' in the tauren tongue, is the king of the savannah cats. He hunts with such stealth, they say he's like a thin, white mist on the earth. He kills so fast his prey have no time for fear or pain.\n\nThe tauren say he is both mercy and death.\n\n{name}, I now set you on the path to hunt Echeyakee. His lair is just northwest of here, on the north side of a small mountain, among the bones of giant Kodo.\n\nGo. Blow this horn when you reach his lair. Blow the horn, and he will come.", objectives = "" }
WordHunterWoW_QuestEN[887] = { title = "Southsea Freebooters", description = "Gazlowe promised me a promotion if I can help him with Ratchet's pirate issues. The problem is these new buccaneers that sailed in and took over Fray Island, south of here. They're not just after our goods - they've got grudges to settle! The other night they even went after one of our war galleons.\n\nI've got plans in the works to deal with the situation, but Gazlowe wants to see quick results. Head over to Fray Island and start lopping off some heads, will you?", objectives = "" }
WordHunterWoW_QuestEN[891] = { title = "A Captain's Vengeance", description = "Yet another ship from my fleet has been lost to those overzealous humans from Theramore!\n\nTheir new Rear Admiral has parked himself right off the coast here. He's boarding or sinking any vessel that doesn't heave-to at his whim.\n\nTravel south along the Merchant Coast to his camp. Bring me the medals of the marines and deck hands. Execute his top Lieutenants, Pyre and Buckland. Lay waste to them as they have laid waste to my fleet!", objectives = "" }
WordHunterWoW_QuestEN[895] = { title = "WANTED: Cap'n Garvey", description = "WANTED!\n\n    \"Cap'n\" J. Garvey of\n     the Maiden's Dagger\n\nCharged with piracy on the open seas, kidnapping, extortion, arson, slavery, et al. Garvey recently arrived in these waters leading a crew of Southsea Freebooters and was last seen assaulting Fray Island. Bring proof of death in an identifiable condition!\n\n-- Gazlowe", objectives = "" }
WordHunterWoW_QuestEN[899] = { title = "Consumed by Hatred", description = "They murdered my wife. They burned my homestead. Since that awful night I have traveled these lands, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched.\n\nYou, {class} - you could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.", objectives = "" }
WordHunterWoW_QuestEN[903] = { title = "Hunting the Huntress", description = "If you want to really demonstrate your bravery to me, let me send you after something that really bites. The savannah huntresses of the Barrens are as sly as they come. Tough, resourceful, quick... and deadly. They've been hassling our scouts recently around the outskirts of the town, especially to the northeast.\n\nBe wary as you hunt them, {name}, or you may find yourself no longer the predator, but instead the prey.", objectives = "" }
WordHunterWoW_QuestEN[905] = { title = "Into the Raptor's Den", description = "The hunt deepens, {name}. Now you must find and defeat your prey within its lair.\n\nHunt the Sunscale raptors to the south, where they have built a warren amongst the hills just off of the road. Slay them and remove the feathers they wear. Place the feathers on the sunscale raptor nests to show their brethren you do not fear them!\n\nBe cautious, {class}. Raptors hunt in packs and will swarm you if you are not cautious.", objectives = "" }
WordHunterWoW_QuestEN[918] = { title = "Timberling Seeds", description = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.\n\nSo it is disturbing to see how angry the timberlings are, particularly considering that things should be healing.\n\nI want to help hunt down the source.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?", objectives = "" }
WordHunterWoW_QuestEN[919] = { title = "Timberling Sprouts", description = "Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.\n\nWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!", objectives = "" }
WordHunterWoW_QuestEN[922] = { title = "Rellian Greenspyre", description = "{name}, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid that resides at Wellspring Hovel, and when last we spoke he revealed his interest in my work with the Timberlings. He had some ideas himself, and he will appreciate a specimen seed to work with.\n\nThank you, {name}. I hope that, some day, you will see the fruit of my labors.\n\nYou will find Wellspring Hovel along the road heading west out of Dolanaar, on the way to Darnassus.", objectives = "" }
WordHunterWoW_QuestEN[923] = { title = "Mossy Tumors", description = "There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help. Those that wander Wellspring Lake to the north are the most tainted. They must be removed!\n\nDestroy the Timberlings you find there, and gather the mossy tumors growing upon them. Bring the tumors to me so that they may be burned.", objectives = "" }
WordHunterWoW_QuestEN[927] = { title = "The Moss-twined Heart", description = "The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.\n\nPerhaps Denalan will want to see this heart.", objectives = "" }
WordHunterWoW_QuestEN[929] = { title = "Teldrassil: The Refusal of the Aspects", description = "Let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.\n\nTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. Pay heed to the lessons of the moonwells, lest we find ourselves furthering our shortcomings.", objectives = "" }
WordHunterWoW_QuestEN[930] = { title = "The Glowing Fruit", description = "Hanging from beneath the fronds of this glowing plant is a large, round fruit.\n\nDenalan would want to study this fruit, you are certain.", objectives = "" }
WordHunterWoW_QuestEN[931] = { title = "The Shimmering Frond", description = "The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.\n\nYou believe that Denalan would want a specimen of this.", objectives = "" }
WordHunterWoW_QuestEN[932] = { title = "Twisted Hatred", description = "I must warn you, {name}, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.\n\nHe is called Lord Melenas. He resides in the nearby cave of Fel Rock, to the north, where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.\n\nYou must find him within his nearby cave just to the north of here, and bring me his head.", objectives = "" }
WordHunterWoW_QuestEN[933] = { title = "Teldrassil: The Coming Dawn", description = "There is one last moonwell that I would like you to visit.  It is directly south of here, on the shores of the Pools of Arlithrien. Be wary as you seek out the well, and keep your weapons close at hand. I sense a growing corruption from the boughs of southern Teldrassil.\n\nWhen you have the water, I want you to bring it to a familiar face that you'll see at the pools. She wishes to battle the corruption, and has asked for you personally.", objectives = "" }
WordHunterWoW_QuestEN[935] = { title = "The Waters of Teldrassil", description = "Our tasks are done here for now. This water proved to be of great importance, but it wasn't originally meant for me. Go ahead and bring it back to Corithras at the crossroads, I'm sure he'd like you to deliver it to its original destination.", objectives = "" }
WordHunterWoW_QuestEN[937] = { title = "The Enchanted Glade", description = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.\n\nWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.\n\nIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.", objectives = "" }
WordHunterWoW_QuestEN[938] = { title = "Mist", description = "The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.\n\nShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.", objectives = "" }
WordHunterWoW_QuestEN[941] = { title = "Planting the Heart", description = "I have removed that foul moss from the heart, but it remains tainted...\n\nTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.", objectives = "" }
WordHunterWoW_QuestEN[976] = { title = "Supplies to Auberdine", description = "Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.\n\nIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.", objectives = "" }
WordHunterWoW_QuestEN[997] = { title = "Denalan's Earth", description = "Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...\n\nMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.\n\nCan you take the package to him?", objectives = "" }
WordHunterWoW_QuestEN[1036] = { title = "Avast Ye, Scallywag", description = "{name}... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty men just like you for a special mission.\n\nIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.", objectives = "" }
WordHunterWoW_QuestEN[1097] = { title = "Elmore's Task", description = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.", objectives = "" }
WordHunterWoW_QuestEN[1133] = { title = "Journey to Astranaar", description = "{name}, go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...", objectives = "" }
WordHunterWoW_QuestEN[1168] = { title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", objectives = "" }
WordHunterWoW_QuestEN[1201] = { title = "Theramore Spies", description = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!", objectives = "" }
WordHunterWoW_QuestEN[1202] = { title = "The Theramore Docks", description = "{name}, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, {name}, and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[1204] = { title = "Mudrock Soup and Bugs", description = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, {name}, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...", objectives = "" }
WordHunterWoW_QuestEN[1205] = { title = "Deadmire", description = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, {name}.  You must lead Deadmire to peace.", objectives = "" }
WordHunterWoW_QuestEN[1222] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, buddy.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?", objectives = "" }
WordHunterWoW_QuestEN[1258] = { title = "... and Bugs", description = "Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- spiny rock crawlers they call them -- will be perfect!\n\nThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.\n\nHead on over to the rocks surrounding Theramore and get me those legs!", objectives = "" }
WordHunterWoW_QuestEN[1270] = { title = "Stinky's Escape", description = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, buddy.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?", objectives = "" }
WordHunterWoW_QuestEN[1271] = { title = "Feast at the Blue Recluse", description = "", objectives = "" }
WordHunterWoW_QuestEN[1453] = { title = "Reclaimers' Business in Desolace", description = "There's work to be done in Desolace, {name}. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.\n\nYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.", objectives = "" }
WordHunterWoW_QuestEN[1454] = { title = "The Karnitol Shipwreck", description = "Greetings, friend. Have yerself a seat here...\n\nMy first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.\n\nHe wants us to find the chest and its contents, and return it to him in Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[1455] = { title = "The Karnitol Shipwreck", description = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.\n\nAfter going through the chest you find it to be completely empty.\n\nNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.", objectives = "" }
WordHunterWoW_QuestEN[1456] = { title = "The Karnitol Shipwreck", description = "Intriguing.\n\nWell, we might not be without hope quite yet.\n\nAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.\n\nIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.", objectives = "" }
WordHunterWoW_QuestEN[1467] = { title = "Reagents for Reclaimers Inc.", description = "To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.\n\nAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.", objectives = "" }
WordHunterWoW_QuestEN[1468] = { title = "Children's Week", description = "You're willing to help us here at the orphanage? Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle. You will only be able to use it for a short amount of time - typically not longer than Children's Week itself. When you use it, you will be able to talk with the child you've agreed to look after. Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward! I'm sure the child will be most eager to meet you.", objectives = "" }
WordHunterWoW_QuestEN[1578] = { title = "Supplying the Front", description = "The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.\n\nThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.\n\nThorvald is in Loch Modan's southern guard tower.", objectives = "" }
WordHunterWoW_QuestEN[1581] = { title = "Elixirs for the Bladeleafs", description = "Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.\n\nCan you help us?\n\nIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.", objectives = "" }
WordHunterWoW_QuestEN[1582] = { title = "Moonglow Vest", description = "We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.", objectives = "" }
WordHunterWoW_QuestEN[1618] = { title = "Gearing Redridge", description = "We dwarves aren't the only ones fighting.  Our human allies have their hands full too!\n\nRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.", objectives = "" }
WordHunterWoW_QuestEN[1918] = { title = "The Befouled Element", description = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps Mastok Wrilehiss at Splintertree Post, might have an idea.", objectives = "" }
WordHunterWoW_QuestEN[2039] = { title = "Find Bingles", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, {name}.", objectives = "" }
WordHunterWoW_QuestEN[2158] = { title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", objectives = "" }
WordHunterWoW_QuestEN[2159] = { title = "Dolanaar Delivery", description = "Greetings, young {class}.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.", objectives = "" }
WordHunterWoW_QuestEN[2206] = { title = "Snatch and Grab", description = "Our operatives in the field are reporting heavy bandit activity south of Goldshire. The reports indicate that bandits have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, {name}. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and {name}, should you be discovered, SI:7 will disavow all knowledge of your existence.", objectives = "" }
WordHunterWoW_QuestEN[2278] = { title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", objectives = "" }
WordHunterWoW_QuestEN[2280] = { title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  Someone would sure be interested in this!", objectives = "" }
WordHunterWoW_QuestEN[2399] = { title = "The Sprouted Fronds", description = "", objectives = "" }
WordHunterWoW_QuestEN[2438] = { title = "The Emerald Dreamcatcher", description = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, {class}? ", objectives = "" }
WordHunterWoW_QuestEN[2459] = { title = "Ferocitas the Dream Eater", description = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater, has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, {name}. And, while you're there, clear out some of the corrupted mystics as well.", objectives = "" }
WordHunterWoW_QuestEN[2499] = { title = "Oakenscowl", description = "I figured it out! I had to rush here to find you! It's so simple really... the corruption has spread from timberling to timberling, but there's but one that is the source.\n\nOakenscowl, he's being poisoned by the largest tumor I have ever seen... I would call it gargantuan, even.\n\nOakenscowl used to reside in a cave near my lake, but has since found his way to a nook to the northeast of here. {name}, Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.", objectives = "" }
WordHunterWoW_QuestEN[2518] = { title = "Tears of the Moon", description = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept at the nearby temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, {name}, and end her suffering. She dwells northeast of here, near the river. Gather her silvery spinnerets and bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[2541] = { title = "The Sleeping Druid", description = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, {name}, bring one to me.", objectives = "" }
WordHunterWoW_QuestEN[2561] = { title = "Druid of the Claw", description = "After examining this charm, {name}, I see now what must be done. Please take it, and do as I ask.\n\nYou are to approach the door to the nearby chamber. Inside, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.", objectives = "" }
WordHunterWoW_QuestEN[2751] = { title = "Barbaric Battlements", description = "Twenty generations of Omosh have held this hammer, {name}. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, {name}. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.", objectives = "" }
WordHunterWoW_QuestEN[2752] = { title = "On Iron Pauldrons", description = "Orokk sees the eagerness in your eyes, {name}. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.", objectives = "" }
WordHunterWoW_QuestEN[2753] = { title = "Trampled Under Foot", description = "Only two more lessons Orokk will teach, {name}. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!", objectives = "" }
WordHunterWoW_QuestEN[2754] = { title = "Horns of Frenzy", description = "The final lesson Orokk teaches you, {name}. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!\n", objectives = "" }
WordHunterWoW_QuestEN[2755] = { title = "Joys of Omosh", description = "Orokk is not crying, {name}. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to {name}.\n\nLearn Omosh dance of joy and then you learn fist of iron!\n", objectives = "" }
WordHunterWoW_QuestEN[2945] = { title = "Grime-Encrusted Ring", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", objectives = "" }
WordHunterWoW_QuestEN[2947] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", objectives = "" }
WordHunterWoW_QuestEN[2948] = { title = "Gnome Improvement", description = "Listen {name}, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", objectives = "" }
WordHunterWoW_QuestEN[2949] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", objectives = "" }
WordHunterWoW_QuestEN[2950] = { title = "Nogg's Ring Redo", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", objectives = "" }
WordHunterWoW_QuestEN[2951] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "" }
WordHunterWoW_QuestEN[2952] = { title = "The Sparklematic 5200!", description = "", objectives = "" }
WordHunterWoW_QuestEN[3064] = { title = "<NYI> <TXT> Pirate Hats", description = "I need pirate hats for my shop.  Get me lots!", objectives = "" }
WordHunterWoW_QuestEN[3361] = { title = "A Refugee's Quandary", description = "I was on my way to join my fellow gnomes at Gnomeregan, but then it all went so horribly wrong!\n\nI left Anvilmar, bags packed and wading through waist-deep snow.  Then we had this ridiculous earthquake, and I got all turned around.  I ended up here, and what's worse: the trolls stole all my stuff!\n\n{name}, I've obviously proven myself to be quite incompetent over the last day and a half.  Would you mind infiltrating the troll camps southwest of here and returning my stuff to me?", objectives = "" }
WordHunterWoW_QuestEN[3721] = { title = "An OOX of Your Own", description = "", objectives = "" }
WordHunterWoW_QuestEN[4021] = { title = "Counterattack!", description = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!\n\nFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.\n\nWe're counting on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[4083] = { title = "The Spectral Chalice", description = "The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.", objectives = "" }
WordHunterWoW_QuestEN[4512] = { title = "A Little Slime Goes a Long Way", description = "But the thing I've studied most is ooze. I know it sounds odd, but they're all over!\n\nI helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from?\n\nI've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatures.", objectives = "" }
WordHunterWoW_QuestEN[4513] = { title = "A Little Slime Goes a Long Way", description = "I'm going to need more samples, {name}. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?!\n\nBah! {name}, take these containers just in case you find any on your own.", objectives = "" }
WordHunterWoW_QuestEN[4601] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "" }
WordHunterWoW_QuestEN[4602] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "" }
WordHunterWoW_QuestEN[4605] = { title = "The Sparklematic 5200!", description = "", objectives = "" }
WordHunterWoW_QuestEN[4606] = { title = "The Sparklematic 5200!", description = "", objectives = "" }
WordHunterWoW_QuestEN[4621] = { title = "Avast Ye, Admiral!", description = "Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder.  Were ye to put a knife to Fleet Master Seahorn, we'd ne'er run afoul of a Booty Bay's vessel.  Were ye to put a knife to Baron Revilgaz, we'd ne'er face the law on their terms.\n\nIf ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says.  Go now lad, and return to me once ye does the deeds.", objectives = "" }
WordHunterWoW_QuestEN[5041] = { title = "Supplies for the Crossroads", description = "Whatever has happened in Southern Barrens is causing some of the quilboar tribes to flee our direction. The displaced Razormane in particular grow desperate, and their attacks grow bolder. I've lost two caravans this week alone!\n\nOur warriors at the Crossroads desperately need those supplies, and I'm not about to let the quilboar grow fat off of their misdeeds. Find the missing supply crates and bring them to me. I'd search the quilboar hovel south of here, along the river.", objectives = "" }
WordHunterWoW_QuestEN[5421] = { title = "Fish in a Bucket", description = "I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon!\n\nBelow the docks here in Shadowprey Village, I've many shellfish traps.  If you're kind enough to do my work and collect me my shellfish, then I'll reward you with something you want... get my drift mon?", objectives = "" }
WordHunterWoW_QuestEN[5501] = { title = "Bone Collector", description = "We're sitting on a goldmine here, I tell you - a goldmine!  Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them.\n\nThere's a caravan that comes by and picks up my kodo bones and then sells them at Shadowprey Village.  If you can travel to the kodo graveyard south of here and bring me ten kodo bones, I'll give you something in return.  Is it a deal?", objectives = "" }
WordHunterWoW_QuestEN[5502] = { title = "A Warden of the Horde", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he's still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", objectives = "" }
WordHunterWoW_QuestEN[5545] = { title = "A Bundle of Trouble", description = "I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.\n\nI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.", objectives = "" }
WordHunterWoW_QuestEN[5561] = { title = "Kodo Roundup", description = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[5581] = { title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one of the Burning Blade leaders myself.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do.\n\nWith the demon threat increasing we must close these portals to stem the tide of demons to this world.", objectives = "" }
WordHunterWoW_QuestEN[5713] = { title = "One Shot.  One Kill.", description = "I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.\n\nI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.\n\nShould we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.", objectives = "" }
WordHunterWoW_QuestEN[5741] = { title = "Sceptre of Light", description = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.", objectives = "" }
WordHunterWoW_QuestEN[5805] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "" }
WordHunterWoW_QuestEN[5821] = { title = "Bodyguard for Hire", description = "Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!\n\nI'll tell you what {class}, if you protect us past the Kolkar village we'll make it worth your while.\n\nIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.", objectives = "" }
WordHunterWoW_QuestEN[5841] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[5842] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[5843] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[5844] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[5847] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[5882] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5883] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5884] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "" }
WordHunterWoW_QuestEN[5885] = { title = "Salve via Skinning", description = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", objectives = "" }
WordHunterWoW_QuestEN[5886] = { title = "Salve via Disenchanting", description = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser eternal essences will work.\n\nI just need a single lesser eternal essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", objectives = "" }
WordHunterWoW_QuestEN[5887] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5888] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5889] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "" }
WordHunterWoW_QuestEN[5890] = { title = "Salve via Skinning", description = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", objectives = "" }
WordHunterWoW_QuestEN[5891] = { title = "Salve via Disenchanting", description = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser eternal essences will work.\n\nI just need a single lesser eternal essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", objectives = "" }
WordHunterWoW_QuestEN[5943] = { title = "Gizelton Caravan", description = "You look like a capable {race}. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp.", objectives = "" }
WordHunterWoW_QuestEN[6027] = { title = "Book of the Ancients", description = "{name}, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!", objectives = "" }
WordHunterWoW_QuestEN[6031] = { title = "Runecloth", description = "In Timbermaw, we are content.  We do not like strangers.  This is good for us, but it is bad for trade.\n\nNot long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak.  Runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing.\n\nWill you bring me runecloth?  If you bring me enough, then I will give you something in trade.", objectives = "" }
WordHunterWoW_QuestEN[6032] = { title = "Sacred Cloth", description = "Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us.  But mooncloth is sacred.\n\nBring me a small supply of this holy cloth, and I will teach you a secret fashioning technique. ", objectives = "" }
WordHunterWoW_QuestEN[6132] = { title = "Get Me Out of Here!", description = "Get me out of here!\n\nI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don't want to talk!  I think they want to eat me!\n\nGet me out of here and my brother Hornizz will pay you big!  He's at our camp next to the kodo graveyard, to the east.\n\nLet's hurry, {name}.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...", objectives = "" }
WordHunterWoW_QuestEN[6134] = { title = "Ghost-o-plasm Round Up", description = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the Magram!  If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs.\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm--that's what we'll sell to the Magram.", objectives = "" }
WordHunterWoW_QuestEN[6321] = { title = "Supplying Brill", description = "Executor Zygand asked me to take stock of our equipment here in Brill.  With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need.\n\nI found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field.\n\nHere is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity.  Take the order to Bat Handler Anette and speak with her about transport to the Undercity.", objectives = "" }
WordHunterWoW_QuestEN[6322] = { title = "Michael Garrett", description = "I have placed Brill's supplies into this crate.  If you have already visited Brill and spoken with their bat master, then you may ride a bat back to her.\n\nSpeak with the Undercity's bat master, Michael Garrett.  He can provide you with a bat to Brill.", objectives = "" }
WordHunterWoW_QuestEN[6323] = { title = "Ride to the Undercity", description = "One of my bats can take you to the Undercity.  Normally these flights require a small fee, but the flight to Undercity is complimentary for a handsome {race} like you.  Speak with me again when you are ready so that we may arrange your transport.\n\nYou will find Gordon Wendham in the Trade Quarter of the Undercity.  That is the same quarter where my bat will land.", objectives = "" }
WordHunterWoW_QuestEN[6324] = { title = "Return to Morris", description = "The bat master in Brill is Bat Handler Anette.  If you have already met her, then I can give you a bat to fly back to her.\n\nOur bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master.\n\nYou have met Anette in Brill, so you may now fly bats there.  Speak with me again when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[6341] = { title = "To Darnassus", description = "Everyone in Dolanaar is so proud of Sister Aquinne. I'm certain she'll be pleased to receive this thoughtful gift from Nyoma.\n\nWhen you're ready to travel to Darnassus, just speak to me again and for a few coins, you can hire a hippogryph to take you there. I'm told Sister Aquinne enjoys the solitude of a small plaza just south of the hippogryph master in Darnassus. Look for her there after you arrive.", objectives = "" }
WordHunterWoW_QuestEN[6342] = { title = "An Unexpected Gift", description = "This is wonderful! It's just the kind of thing I need to remind me of home while I continue my studies in the Temple of the Moon. I'll try out one of the recipes tonight. I can't wait!\n\nWould you take this short note of thanks back to Nyoma? You can hire a hippogryph to take you back to Dolanaar. Just visit our hippogryph master, Leora, when you're ready to leave. She'll help you get a ride back to Dolanaar.", objectives = "" }
WordHunterWoW_QuestEN[6343] = { title = "Return to Nyoma", description = "It will be easy to get you a flight back to Dolanaar. Since you already know Fidelio in Dolanaar, you'll be able to fly back there without any problems.\n\nWhenever you arrive in a new town, you should remember to speak to the flight master so that you can fly to and from the new location.\n\nSpeak with me when you're ready to hire a hippogryph to return to Dolanaar.", objectives = "" }
WordHunterWoW_QuestEN[6344] = { title = "Reminders of Home", description = "A friend of mine, Sister Aquinne, is training to be a priestess of the moon in Darnassus.  She left Dolanaar to study in the temple last year. Her letters say she is doing well and learning much, but she misses home and her old friends. I've put together a book of her favorite recipes from Dolanaar.\n\nIf you have time, would you take them to her in Darnassus? You can rent a hippogryph from Fidelio. He's in the center of town, just across from the inn.", objectives = "" }
WordHunterWoW_QuestEN[6361] = { title = "A Bundle of Hides", description = "I have a bundle of hides from the animals of Mulgore, and must get them to Thunder Bluff.  A colleague there, Ahanu, will use the hides to create leather goods.\n\nWill you take the hides to him for me?\n\nThe quickest way to Thunder Bluff is on the back of a wind rider.  Bring the bundle of hides to Tak, our wind rider master in Bloodhoof Village, and speak to him about transport to Thunder Bluff.", objectives = "" }
WordHunterWoW_QuestEN[6362] = { title = "Ride to Thunder Bluff", description = "For a small fee, I will give you a wind rider to Thunder Bluff.  There's no faster way to the city!\n\nIf that is acceptable, speak to me again when you are ready to go.\n\nIf you're taking those hides to Ahanu, then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff.  And that's right where you'll land!", objectives = "" }
WordHunterWoW_QuestEN[6363] = { title = "Tal the Wind Rider Master", description = "I have prepared leather goods for Varg to sell at the Bloodhoof Village.  Will you bring them to him?\n\nIf you have already been to Bloodhoof Village and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him.\n\nTake the leather goods to Tal, our wind rider master in Thunder Bluff, and speak with him to arrange transport to Bloodhoof Village.", objectives = "" }
WordHunterWoW_QuestEN[6364] = { title = "Return to Varg", description = "In order to fly to a town, you must have already been there and spoken with the wind rider master of that town.  You have been to the Bloodhoof Village and spoken to their wind rider master Tak, so for a small fee you can take a wind rider to him from here.\n\nSpeak with me again when you are ready.  Once at Bloodhoof Village, you can then deliver the leather goods to Varg Windwhisper.", objectives = "" }
WordHunterWoW_QuestEN[6365] = { title = "Meats to Orgrimmar", description = "I have some choice cuts of meat that I want to send to a friend.  Her name is Gryshka, the innkeeper in Orgrimmar.  Will you deliver the meat for me?\n\nThe fastest way to Orgrimmar is on a wind rider.  Take the meats to the Razor Hill wind rider master, Burok, and speak with him about transport to Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[6384] = { title = "Ride to Orgrimmar", description = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Grimtak's meats to Gryshka.  Her inn is in the Valley of Strength.\n\nSpeak with me again when you are ready for the journey.", objectives = "" }
WordHunterWoW_QuestEN[6385] = { title = "Doras the Wind Rider Master", description = "I've written a letter of thanks to Grimtak.  Will you deliver it for me?  If you've already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.", objectives = "" }
WordHunterWoW_QuestEN[6386] = { title = "Return to Razor Hill", description = "My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.\n\nYou have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here.  Once you're at Razor Hill, you can deliver Gryshka's letter to Grimtak.\n\nSpeak with me when you are ready to go.", objectives = "" }
WordHunterWoW_QuestEN[6387] = { title = "Honor Students", description = "I see a lot of young dwarves at my door, eager to learn the trade of cooking.  And if there's one thing a cook needs more than anything, it's a cleaver!\n\nI have a list of students who scored high in their lessons and earned an honorary cleaver.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the cleavers ready.\n\nThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard, and speak with him about transport to Ironforge.", objectives = "" }
WordHunterWoW_QuestEN[6388] = { title = "Gryth Thurden", description = "Here are the honorary cleavers for Gremlock's students.  If you've already been to Kharanos, then you should fly a gryphon back there!\n\nTake the cleavers to our gryphon master, Gryth Thurden, and speak with him about a ride back to Kharanos.", objectives = "" }
WordHunterWoW_QuestEN[6391] = { title = "Ride to Ironforge", description = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Gremlock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!\n\nSpeak to me again when you're ready for the journey.", objectives = "" }
WordHunterWoW_QuestEN[6392] = { title = "Return to Gremlock", description = "For a small fee you can buy a gryphon ride to Kharanos... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.\n\nYou've already been to Brolan, the gryphon master of Kharanos, so now you can return to him.  And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor.\n\nSpeak with me when you're ready to go.", objectives = "" }
WordHunterWoW_QuestEN[6441] = { title = "Satyr Horns", description = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your time.", objectives = "" }
WordHunterWoW_QuestEN[6442] = { title = "Naga at the Zoram Strand", description = "There is evil lurking here along the coast, {race}.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!", objectives = "" }
WordHunterWoW_QuestEN[6462] = { title = "Troll Charm", description = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\n{name}, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.", objectives = "" }
WordHunterWoW_QuestEN[6482] = { title = "Freedom to Ruul", description = "Eh?  Who are you?\n\n{name}?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\n{name}! I must escape!", objectives = "" }
WordHunterWoW_QuestEN[6503] = { title = "Ashenvale Outrunners", description = "Blasted elves! Dey knew right where to hit us!\n\nIt was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens!\n\nNever too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!", objectives = "" }
WordHunterWoW_QuestEN[6544] = { title = "Torek's Assault", description = "Hey!  {class}!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, {name}, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?", objectives = "" }
WordHunterWoW_QuestEN[6563] = { title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", objectives = "" }
WordHunterWoW_QuestEN[6607] = { title = "Nat Pagle, Angler Extreme", description = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:", objectives = "" }
WordHunterWoW_QuestEN[6608] = { title = "You Too Good.", description = "Lumak no can teach {name} no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", objectives = "" }
WordHunterWoW_QuestEN[6610] = { title = "Clamlette Surprise", description = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, {name}, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:", objectives = "" }
WordHunterWoW_QuestEN[6611] = { title = "To Gadgetzan You Go!", description = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat {race} needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!", objectives = "" }
WordHunterWoW_QuestEN[6621] = { title = "King of the Foulweald", description = "My research has paid off.\n\nI believe that with a show of force, we can diminish the furbolgs' aggressiveness.\n\nTake this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, {name}. This is no task for a single {class}.", objectives = "" }
WordHunterWoW_QuestEN[6622] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.\n", objectives = "" }
WordHunterWoW_QuestEN[6623] = { title = "Horde Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!", objectives = "" }
WordHunterWoW_QuestEN[6624] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.\n", objectives = "" }
WordHunterWoW_QuestEN[6625] = { title = "Alliance Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!", objectives = "" }
WordHunterWoW_QuestEN[6641] = { title = "Vorsha the Lasher", description = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, {name}. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.", objectives = "" }
WordHunterWoW_QuestEN[6661] = { title = "Deeprun Rat Roundup", description = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...", objectives = "" }
WordHunterWoW_QuestEN[6662] = { title = "Me Brother, Nipsy", description = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.", objectives = "" }
WordHunterWoW_QuestEN[6922] = { title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.", objectives = "" }
WordHunterWoW_QuestEN[6961] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "" }
WordHunterWoW_QuestEN[6962] = { title = "Treats for Great-father Winter", description = "Hey, can you do Great-father Winter a favor, um, little boy?\n\nNot to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Great-father and fetch some for me?", objectives = "" }
WordHunterWoW_QuestEN[6964] = { title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", objectives = "" }
WordHunterWoW_QuestEN[6983] = { title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Orgrimmar are disappointed!", objectives = "" }
WordHunterWoW_QuestEN[6984] = { title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", objectives = "" }
WordHunterWoW_QuestEN[7021] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "" }
WordHunterWoW_QuestEN[7022] = { title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "" }
WordHunterWoW_QuestEN[7023] = { title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Ironforge!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "" }
WordHunterWoW_QuestEN[7024] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "" }
WordHunterWoW_QuestEN[7025] = { title = "Treats for Greatfather Winter", description = "Hey, can you do Greatfather Winter a favor, um, little boy?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", objectives = "" }
WordHunterWoW_QuestEN[7043] = { title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!", objectives = "" }
WordHunterWoW_QuestEN[7045] = { title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", objectives = "" }
WordHunterWoW_QuestEN[7061] = { title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Baine Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.  ", objectives = "" }
WordHunterWoW_QuestEN[7062] = { title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorers' League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", objectives = "" }
WordHunterWoW_QuestEN[7063] = { title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Muradin Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.  ", objectives = "" }
WordHunterWoW_QuestEN[7081] = { title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", objectives = "" }
WordHunterWoW_QuestEN[7082] = { title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", objectives = "" }
WordHunterWoW_QuestEN[7101] = { title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", objectives = "" }
WordHunterWoW_QuestEN[7102] = { title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", objectives = "" }
WordHunterWoW_QuestEN[7121] = { title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", objectives = "" }
WordHunterWoW_QuestEN[7122] = { title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", objectives = "" }
WordHunterWoW_QuestEN[7123] = { title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[7124] = { title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", objectives = "" }
WordHunterWoW_QuestEN[7141] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[7142] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[7161] = { title = "Proving Grounds", description = "Hail, {class}. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...\n\nAll newcomers to the Valley must first complete the rite of battle.\n\nDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.", objectives = "" }
WordHunterWoW_QuestEN[7162] = { title = "Proving Grounds", description = "You've arrived just in time, {class}. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.\n\nBefore you make your way to the field of battle, you will want to join the rank of Stormpike.\n\nSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.", objectives = "" }
WordHunterWoW_QuestEN[7163] = { title = "Rise and Be Recognized", description = "<Warmaster Laggrond salutes you.>\n\nIt is your time, {name}. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", objectives = "" }
WordHunterWoW_QuestEN[7164] = { title = "Honored Amongst the Clan", description = "It is good to see you again, {class}. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, {name}. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7165] = { title = "Earned Reverence", description = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7166] = { title = "Legendary Heroes", description = "Your radiate command and power, {class}. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7167] = { title = "The Eye of Command", description = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander {name}.\n\n<Warmaster Laggrond salutes.>", objectives = "" }
WordHunterWoW_QuestEN[7168] = { title = "Rise and Be Recognized", description = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, {class}. The time has come.\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7169] = { title = "Honored Amongst the Guard", description = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7170] = { title = "Earned Reverence", description = "I must know, {name}. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", objectives = "" }
WordHunterWoW_QuestEN[7171] = { title = "Legendary Heroes", description = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", objectives = "" }
WordHunterWoW_QuestEN[7172] = { title = "The Eye of Command", description = "Let them hear your voice, Commander {name}! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.\n", objectives = "" }
WordHunterWoW_QuestEN[7181] = { title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", objectives = "" }
WordHunterWoW_QuestEN[7202] = { title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.", objectives = "" }
WordHunterWoW_QuestEN[7223] = { title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", objectives = "" }
WordHunterWoW_QuestEN[7224] = { title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", objectives = "" }
WordHunterWoW_QuestEN[7281] = { title = "Brotherly Love", description = "Tragic... My brother faces me on the field of battle: A commander for the Stormpike.\n\nOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...\n\nDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.\n\nAnd soldier, do not go alone.", objectives = "" }
WordHunterWoW_QuestEN[7282] = { title = "Brotherly Love", description = "He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.\n\nVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.", objectives = "" }
WordHunterWoW_QuestEN[7301] = { title = "Fallen Sky Lords", description = "We got them held prisoner, {race}. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.\n\nSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.", objectives = "" }
WordHunterWoW_QuestEN[7302] = { title = "Fallen Sky Lords", description = "Our air support is in shambles, {name}. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!\n\nGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.\n\nThat's all the information I have. Move out! Search through the areas thoroughly.", objectives = "" }
WordHunterWoW_QuestEN[7361] = { title = "Favor Amongst the Darkspear", description = "<Najak snarls.>\n\nBefore the night elves existed there was troll. It was from troll that the night elves came.\n\nTheir mutinous attacks against my people will not be tolerated. Staghelm seeks to wipe us out - to leave no trace of those that bore him and his ilk. It will not happen!\n\nFor every night elf that you slay and decapitate, Najak will grant you favor amongst the Darkspear. Word of your deeds will be spread across Kalimdor and the Eastern Kingdoms. Go now and serve the Darkspear!", objectives = "" }
WordHunterWoW_QuestEN[7362] = { title = "Ally of the Tauren", description = "The Elder Crone has sent me to this warzone to research the other races. More specifically, I am to collect gnome samples. Magatha is primarily interested in their survivability. Aye, the gnomes - while pitifully weak and miniscule - exude great resilience both in and out of combat.\n\nFortunately for you, I am looking for ruffians to do Magatha's bidding. Return to me with tufts of gnome hair and you shall be known to the tauren as an ally.", objectives = "" }
WordHunterWoW_QuestEN[7363] = { title = "The Human Condition", description = "Humans are so utterly detestable.\n\n<Commander Philips grimaces.>\n\nWhile it is true that I am a soldier of Frostwolf, I remain a servant of Sylvanas.\n\nDuring my tour of duty, I do extra work on the side for the Dark Apothecaries of the Undercity.\n\nI have been tasked with collecting human bone chips that are to be used in curing the human condition.\n\nI am authorized to pass that task on to my subordinates.\n\nFind them. Kill them. Return their bone chips to me.", objectives = "" }
WordHunterWoW_QuestEN[7364] = { title = "Gnomeregan Bounty", description = "The High Tinkerer himself has sent me to this field of battle to defend my gnomish brothers and sisters. We have received word that the tauren are singling out and slaying gnomes. Worst of all, they are removing tufts of glorious gnome hair from the corpses of the fallen. These atrocities must be stopped. We must reciprocate!\n\nI want them de-hoofed, {class}. Bring me their hooves! Show yourself as an ally of the gnomes.", objectives = "" }
WordHunterWoW_QuestEN[7365] = { title = "Staghelm's Requiem", description = "Staghelm has given the order. All trolls on the field of battle must be exterminated. Their preposterous claims of birthing night elves must be met with force and due prejudice.\n\nSlay them and return to me with their mojo. To reiterate: I want you to steal their mojo.", objectives = "" }
WordHunterWoW_QuestEN[7366] = { title = "The Archbishop's Mercy", description = "The Archbishop is as kind as he is wise. For a man to look mercifully on such a wretched lot...\n\n<Commander Philips shakes his head in disbelief.>\n\nToo kind... Just too kind.\n\nThe Archbishop asks that we take pity on the undead and grant them swift and permanent deaths. For this grand display of mercy, we merely require their black, disease ridden hearts.\n\nBring me the hearts of the Forsaken so that they may be ceremoniously incinerated at the Cathedral of Light. Make haste, {name}!", objectives = "" }
WordHunterWoW_QuestEN[7367] = { title = "Defusing the Threat", description = "The Frostwolf have their front lines and bases booby trapped, {class}. You have to watch your step when invading enemy territory.\n\nIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.\n\nYou will probably find him in a tower near the Iceblood Garrison. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[7368] = { title = "Defusing the Threat", description = "I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.\n\nIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.\n\nIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.", objectives = "" }
WordHunterWoW_QuestEN[7383] = { title = "Teldrassil: The Burden of the Kaldorei", description = "You must now visit the moonwell that rests under the boughs of the Oracle Tree, far to the northwest. The first and most powerful of our wells, its waters are said to possess the very essence of Elune's Powers.\n\nRetrieve a phial of its water and return to me. I will meet you at the crossroads in front of Darnassus when your task is complete.", objectives = "" }
WordHunterWoW_QuestEN[7401] = { title = "WANTED: Dwarves!", description = "By order of Sergeant Yazra Bloodsnarl, all dwarves on the field of battle are to be killed on sight.\n\nShould you slay a dwarf in combat, rip out their spine, leaving a spineless heap of stink and rot to serve as a warning to any and all that dare oppose the might of the Frostwolf.\n\nReturn to Sergeant Yazra Bloodsnarl with proof of your heroics.", objectives = "" }
WordHunterWoW_QuestEN[7402] = { title = "WANTED: Orcs!", description = "By order of Corporal Noreg Stormpike, all able bodied soldiers of Stormpike are required to slay any opposing orcs that they meet upon the field of battle.\n\nSoldiers are required to remove a tusk or tooth from the maw of the enemy and present said tooth as proof of their accomplishment.\n\nWear protective gloves.", objectives = "" }
WordHunterWoW_QuestEN[7490] = { title = "Victory for the Horde", description = "You have accomplished the impossible.\n\nThe brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Warchief's advisor Eitrigg.", objectives = "" }
WordHunterWoW_QuestEN[7491] = { title = "For All To See", description = "Overlord Natoj awaits your arrival in the Valley of Strength.\n\n<Eitrigg salutes you.>\n\nDo not keep the Horde waiting!", objectives = "" }
WordHunterWoW_QuestEN[7493] = { title = "The Journey Has Just Begun", description = "", objectives = "" }
WordHunterWoW_QuestEN[7495] = { title = "Victory for the Alliance", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Grand Admiral in honor of the King.", objectives = "" }
WordHunterWoW_QuestEN[7496] = { title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", objectives = "" }
WordHunterWoW_QuestEN[7497] = { title = "The Journey Has Just Begun", description = "", objectives = "" }
WordHunterWoW_QuestEN[7604] = { title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to him as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", objectives = "" }
WordHunterWoW_QuestEN[7761] = { title = "Blackhand's Command", description = "Imbecile,\n\nI hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing.\n\nOnly those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself!\n\n-Warchief Rend Blackhand\n\nP.S. Destroy this letter, idiot.", objectives = "" }
WordHunterWoW_QuestEN[7781] = { title = "The Lord of Blackrock", description = "The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Bring it to the Grand Admiral on the King's behalf, champion.", objectives = "" }
WordHunterWoW_QuestEN[7782] = { title = "The Lord of Blackrock", description = "Go to the Valley of Heroes and speak with Field Marshal Stonebridge.", objectives = "" }
WordHunterWoW_QuestEN[7783] = { title = "The Lord of Blackrock", description = "The old feeling returns. The welcome pangs of victory reverberate throughout your being. Before you lies the monolithic, battle scarred head of Nefarian. Return it to the Warchief's advisor Eitrigg, champion.", objectives = "" }
WordHunterWoW_QuestEN[7784] = { title = "The Lord of Blackrock", description = "Seek out Overlord Natoj in the Valley of Strength.", objectives = "" }
WordHunterWoW_QuestEN[7785] = { title = "Examine the Vessel", description = "Examine the vessel of his rebirth, mortal. It is from this that the Windseeker shall be reborn!", objectives = "" }
WordHunterWoW_QuestEN[7786] = { title = "Thunderaan the Windseeker", description = "I have told you all that I know, {name}. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.\n\nDo this and gain the blessing of Thunderaan.", objectives = "" }
WordHunterWoW_QuestEN[7787] = { title = "Rise, Thunderfury!", description = "You have defeated the Wind Seeker. Take the dormant blade and force the lying wretch, Demitrian, to use the materials you provided for his betrayal to wake Thunderfury.", objectives = "" }
WordHunterWoW_QuestEN[7810] = { title = "Arena Master", description = "There must be more to being a master of the arena than this!\n\nPerhaps the Pirate who runs the event at Gurubashi will know!", objectives = "" }
WordHunterWoW_QuestEN[7848] = { title = "Attunement to the Core", description = "Rifts stir, tear, and collapse all around us, {race}. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", objectives = "" }
WordHunterWoW_QuestEN[7863] = { title = "Sentinel Basic Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7864] = { title = "Sentinel Standard Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7865] = { title = "Sentinel Advanced Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7866] = { title = "Outrider Basic Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7867] = { title = "Outrider Standard Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7868] = { title = "Outrider Advanced Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[7905] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.", objectives = "" }
WordHunterWoW_QuestEN[7926] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Thunder Bluff in Mulgore!", objectives = "" }
WordHunterWoW_QuestEN[7946] = { title = "Spawn of Jubjub", description = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", objectives = "" }
WordHunterWoW_QuestEN[8149] = { title = "Honoring a Hero", description = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer.\n\nHelp us honor Uther by taking this offering to his tomb in the Western Plaguelands.  Place it at his statue, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.", objectives = "" }
WordHunterWoW_QuestEN[8150] = { title = "Honoring a Hero", description = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream.\n\nHelp us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale.  Place it at the base, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.", objectives = "" }
WordHunterWoW_QuestEN[8260] = { title = "Arathor Basic Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8261] = { title = "Arathor Standard Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8262] = { title = "Arathor Advanced Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8263] = { title = "Defiler's Basic Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8264] = { title = "Defiler's Standard Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8265] = { title = "Defiler's Advanced Care Package", description = "", objectives = "" }
WordHunterWoW_QuestEN[8271] = { title = "Hero of the Stormpike", description = "", objectives = "" }
WordHunterWoW_QuestEN[8272] = { title = "Hero of the Frostwolf", description = "", objectives = "" }
WordHunterWoW_QuestEN[8277] = { title = "Deadly Desert Venom", description = "Beetix Ficklespragg at your service!  My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists.  Or used to, anyway.  He came back from his last trip with a strong poison running though his veins.\n\nI've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him.\n\nNoggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it.  Bring me some stingers and fangs and I'll try to make an antidote for him.", objectives = "" }
WordHunterWoW_QuestEN[8278] = { title = "Noggle's Last Hope", description = "Blasted!  The antidote didn't work.  Noggle must've been stung by one of the stronger creatures in the far south.\n\nI'm going to need you to go there and get me some more samples, {name}.  The good news is that since their poison is stronger I won't require as many.  The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.", objectives = "" }
WordHunterWoW_QuestEN[8279] = { title = "The Twilight Lexicon", description = "The Twilight's Hammer are not kind to those that leave their ranks.  They hunt me to this day like I'm some sort of beast!  Needless to say, an enemy of theirs is a friend of mine!\n\nTo decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon.  It's such an important tool that they keep its three chapters in different locations!  The officers entrusted with the Lexicon are known as Twilight Keepers.  Look for them at the Twilight's Hammer camps.", objectives = "" }
WordHunterWoW_QuestEN[8280] = { title = "Securing the Supply Lines", description = "Cenarion Hold is a location of utmost strategic importance.  I'm convinced that while we hold it our victory over the silithid is guaranteed.  Provided our influx supplies can be maintained, that is.\n\nDesert worms have proven to be more of a threat to our supply caravans than even the silithid themselves.  Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers.  I need you to thin their numbers to ensure our supplies aren't jeopardized.", objectives = "" }
WordHunterWoW_QuestEN[8281] = { title = "Stepping Up Security", description = "Your performance has been truly exemplary so far, {name}.  Our supply lines are not completely safe yet, however.  In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north.\n\nYou'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.  ", objectives = "" }
WordHunterWoW_QuestEN[8282] = { title = "Noggle's Lost Satchel", description = "Where am I?  Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid.  In my rush to escape I walked right into a nest of stonelash flayers.\n\nThe satchel I was carrying had all sorts of rare reagents in it.  Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs.  I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents.\n\nI ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.", objectives = "" }
WordHunterWoW_QuestEN[8283] = { title = "Wanted - Deathclasp, Terror of the Sands", description = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity.  She presents a great threat to patrols and expeditions in the southern regions.  Individuals participating in her destruction will be remunerated handsomely.  Inquire with Captain Vish Kozus, at the top of the Cenarion Hold Watchtower, regarding a reward.", objectives = "" }
WordHunterWoW_QuestEN[8284] = { title = "The Twilight Mystery", description = "A camp of Twilight's Hammer cultists once thrived northwest of here.  If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was.\n\nI've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful.  See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus.", objectives = "" }
WordHunterWoW_QuestEN[8285] = { title = "The Deserter", description = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect.  Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit.  Perhaps you can enlist his help in deciphering the tablet.\n\nTake the restored tablet with you and seek out Ortell.", objectives = "" }
WordHunterWoW_QuestEN[8287] = { title = "A Terrible Purpose", description = "Ok, here we are... a pretty valuable chunk of information, I must say!  I've seen the Cenarion Circle forces arrive at Silithus.  They plan to drive the Twilight's Hammer out, don't they?  This will help.  \n\nTake this parchment to their leader, Commander Mar'alith.  Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!", objectives = "" }
WordHunterWoW_QuestEN[8304] = { title = "Dearest Natalia", description = "My dear Natalia has gone missing.\n\nTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.\n\nShe was last seen heading to Bronzebeard's camp to the south.\n\nMy soldiers are spread too thin, {name}. I need you to go to Bronzebeard's camp and question those dwarves. ", objectives = "" }
WordHunterWoW_QuestEN[8306] = { title = "Into The Maw of Madness", description = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, {name}. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive.\n\nAnd {name}, if she truly is as mad as they say... do what you must.", objectives = "" }
WordHunterWoW_QuestEN[8307] = { title = "Desert Recipe", description = "Adapting to life in the desert has been difficult to say the least.  Not only do I miss the birds and trees of Auberdine but our food selection is severely limited by this arid environment.  I'm trying to learn about desert herbs, but there aren't many.\n\nI've seen Twilight's Hammer groups from the camp west of here hunt sandworms for food.  Sandworm meat is so bitter though, I can't imagine how they make it palatable.  Keep your eyes open if you go to their camp and let me know if you learn anything.", objectives = "" }
WordHunterWoW_QuestEN[8308] = { title = "Brann Bronzebeard's Lost Letter", description = "To Whom It May Concern:\n\nIf you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow.\n\nFound information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it.\n\nTake this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs.\n\n-Brann Bronzebeard, Explorer Extreme\n\nP.S. Watch out for crazy Old God worshipping night elf.", objectives = "" }
WordHunterWoW_QuestEN[8309] = { title = "Glyph Chasing", description = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.\n\nIf I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness.\n\nTake this transcription set  and hit Hive'Regal to the east, {name}. That's the last rubbing I need!", objectives = "" }
WordHunterWoW_QuestEN[8310] = { title = "Breaking the Code", description = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! \n\nWhat do I need? Glad you asked! I need brains!\n\nNormally I'd need a brain from each silithid type that inhabit the hives. Another brave explorer brought me two of 'em here... and never came back from Hive'Regal.\n\nBring me back a silithid brain from Hive'Regal... and be careful not to end up like him!", objectives = "" }
WordHunterWoW_QuestEN[8311] = { title = "Hallow's End Treats for Jesper!", description = "I'm not allowed to go trick-or-treating.  After Deathwing's attack, I'm lucky Matron Nightingale lets me be this far away.\n\nIf you trick-or-treat for me, I'd trade you the candy you get for some I already have!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a little gnome named Talvash in Ironforge is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "" }
WordHunterWoW_QuestEN[8312] = { title = "Hallow's End Treats for Spoops!", description = "I want to keep trick-or-treating, but I can't because the Matron won't let me.  If you go for me, I'd trade you the candy you get for some I already have!  I think you'd like this candy - it makes you turn into things both funny and scary!\n\nEach of the innkeepers in the big cities have candy they give for Hallow's End - talk to them and do the tricks they ask for!  Also, a troll named Kali Remik in Orgrimmar is handing out candy as well.  When you have all the candy, bring them back to me here!", objectives = "" }
WordHunterWoW_QuestEN[8313] = { title = "Sharing the Knowledge", description = "While the recipe for cooking sandworm meat is legible, it contains references to herbs and spices you've never heard of.  Calandrath might have enough knowledge of the plants that grow in the desert to make sense of it.  ", objectives = "" }
WordHunterWoW_QuestEN[8314] = { title = "Unraveling the Mystery", description = "We're on the verge of a breakthrough, {name}! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.\n\nUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.\n\nTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help.", objectives = "" }
WordHunterWoW_QuestEN[8316] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8317] = { title = "Kitchen Assistance", description = "That recipe sure will come in handy.  I'd better get to work so I can have some smoked desert dumplings ready for today.  I could use a hand in making some, I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[8318] = { title = "Secret Communication", description = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them.  I want you to bring me a stack of them, {class}.\n\nI can't figure out what the gibberish means, but that's not the point!  These papers are how their different groups communicate secretly.  The more texts we take out of circulation, the less they can communicate!", objectives = "" }
WordHunterWoW_QuestEN[8320] = { title = "Twilight Geolords", description = "The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night.  We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert.\n\nAlthough their mystery may one day be solved, we must first deal with their immediate threat.  Go to their camps to the west and seek out Twilight geolords.  They are the heads of these serpents; that is where we must strike!", objectives = "" }
WordHunterWoW_QuestEN[8321] = { title = "Vyral the Vile", description = "We have discovered another base of operations for the Twilight's Hammer.  It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus.  The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat.  When you have done this, bring me his signet ring.\n\nFortune to you, {name}.  The horrors of Twilight's Run are formidable indeed.", objectives = "" }
WordHunterWoW_QuestEN[8323] = { title = "True Believers", description = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you.\n\nMy former organization has a secret encoded bulletin they circulate on a monthly basis.\n\nIf they make any progress searching for me or if they call off the search, word will be published on the True Believer.\n\nAlthough this information is obviously valuable to me, the publication contains other useful information that I can share.  Bring me any encoded texts you find on Twilight's Hammer members.", objectives = "" }
WordHunterWoW_QuestEN[8325] = { title = "Reclaiming Sunstrider Isle", description = "The sooner you begin your education, {name}, the better for us all.  There is little room for error, so listen closely.\n\nThe Burning Crystals - the green floating objects to the west of the Sunspire here - have long been used to power the isle's experimentations.  The mana wyrms were their guardians, but the Scourge invasion of Quel'Thalas has driven them errant from our lack of magical control over them.\n\nThere is little choice but to thin their numbers for reclamation.  Do this, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[8326] = { title = "Unfortunate Measures", description = "Your effort has made something clear that, honestly, I wish were not true.  The unchecked power of the Burning Crystals has maligned a much larger swath of the isle's natural balance than I thought.  We must now take on more unfortunate measures to reclaim control.\n\nThe nearby lynxes have succumbed to the influence of the crystals, and they must be put down.  Bring their collars, {name}, as I may yet be able to fashion a magical restraint to turn some back from being uncontrolled.", objectives = "" }
WordHunterWoW_QuestEN[8327] = { title = "Report to Lanthan Perilon", description = "You are to report to my assistant, Lanthan Perilon.  He will instruct you on what needs to be done next.  While we here at the Sunspire will continue to rein in the Burning Crystals, you will be focused on a more pressing matter concerning Falthrien Academy.  Lanthan will explain fully when you speak to him.\n\nSimply walk west of here along the path, and you should see him standing close by.\n\nGood luck, {name} - your continued successes shall be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[8334] = { title = "Aggression", description = "Before sending you to the Academy, I want you on another task that needs to be dealt with immediately.  Once used to aid us in the gardening of Sunstrider Isle, the bestial tenders now have grown out of our control.  Clear them out with due haste, but be warned - their lack of control has made them aggressive.  It is such aggression that forces us to put down these once-gentle servants.\n\nIt doesn't please me to ask you to do such a task, but survival is survival.  I'll mourn later.", objectives = "" }
WordHunterWoW_QuestEN[8335] = { title = "Felendren the Banished", description = "A betrayer of our people resides atop Falthrien Academy to the southwest.\n\nFelendren is his name, and he was banished from blood elf lands for failing to heed the warnings of our teachers and elders.  He is the worst of our society, as he lives only to feed his insatiable magical addictions.  He refused to learn control; he is a shell of his former self - one of the Wretched - and he is a threat to the Sunspire.\n\nDestroy him and the wraiths he uses as minions.", objectives = "" }
WordHunterWoW_QuestEN[8338] = { title = "Tainted Arcane Sliver", description = "You've found an odd sliver of crystallized mana on the corpse of the tainted arcane wraith.  The sliver is different than others you may have seen in that it is as dark and sinister-looking as the wraith you looted it from.  Just holding it gives you a sense of unnatural foreboding.\n\nArcanist Helion at the gazebo of the Sunspire on Sunstrider Isle just might be someone who would have a use for the sliver.", objectives = "" }
WordHunterWoW_QuestEN[8347] = { title = "Aiding the Outrunners", description = "Magistrix Erona wanted you to head over to Silvermoon City in order to aid our reclamation efforts there... that is, once you had successfully addressed the situation at Falthrien Academy.  You did not disappoint us, {name}.\n\nOn your way to Falconwing Square, south of here, you should speak with Outrunner Alarion.  She's not far from the bridge.\n\nThe Outrunners take care of shuttling goods between here and the mainland, and since you've proven to be so resourceful, they could use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[8350] = { title = "Completing the Delivery", description = "The death of another outrunner is a true tragedy, but it's a risk we all accept when we take the job.  Magistrix Erona at the Sunspire needs to get this package to the inn at Falconwing Square, and she needs it there as soon as possible.\n\nWe're short handed and I don't have anyone else available that can cover for us.\n\nI'm not going to lie to you; the path to Falconwing Square can be extremely dangerous if you leave the safety of Dawning Lane.  Do you feel up to the task, {name}?", objectives = "" }
WordHunterWoW_QuestEN[8376] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8377] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8378] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8379] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8380] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8381] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8382] = { title = "Armaments of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[8446] = { title = "Shrouded in Nightmare", description = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.", objectives = "" }
WordHunterWoW_QuestEN[8447] = { title = "Waking Legends", description = "The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, {name}.", objectives = "" }
WordHunterWoW_QuestEN[8463] = { title = "Unstable Mana Crystals", description = "A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums.  If not handled properly, the crystals could explode with enough force to blow a hole into the city walls.\n\nNow, {name}, I don't quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad.\n\nBring me back any remaining stolen crystals you find; they might still be inside their original crates.", objectives = "" }
WordHunterWoW_QuestEN[8468] = { title = "WANTED: Thaelis the Hungerer", description = "The city of Silvermoon hereby issues a reward for the head of Thaelis the Hungerer, notorious Wretched ringleader.  He is wanted for repeated crimes against the general populace of Silvermoon City, including the murder of two city guards.\n\nReport to Sergeant Kan'ren to collect the reward.", objectives = "" }
WordHunterWoW_QuestEN[8470] = { title = "Deadwood Ritual Totem", description = "You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.\n", objectives = "" }
WordHunterWoW_QuestEN[8472] = { title = "Major Malfunction", description = "The arcane patrollers crafted by our forefathers to protect the city have fallen into a dangerous state of disrepair.  They fail to recognize us as their masters and will attack us on sight!\n\nEven though they were created many years ago, the arcane cores that power them are still quite useful and valuable to us.  I want you to gather these cores and bring them to me so I can put them to good use again.  You will find the patrollers in the ruined section of Silvermoon, to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[8473] = { title = "A Somber Task", description = "These are difficult times for us, {name}.  It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge's expansion.\n\nThe treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove.\n\nThis is a painful thing to ask of you, {class}, but we've failed to convince our former allies to cease their endeavors.  I need you to stop them by the only means that remain to us: force.", objectives = "" }
WordHunterWoW_QuestEN[8474] = { title = "Old Whitebark's Pendant", description = "The pendant has the initials L.R. etched on to it.  Perhaps these letters will lead to the pendant's maker.", objectives = "" }
WordHunterWoW_QuestEN[8475] = { title = "The Dead Scar", description = "The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city.\n\nThis blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon.\n\nGo, {name}, and give my men a hand in killing the mindless undead that walk down the Dead Scar.", objectives = "" }
WordHunterWoW_QuestEN[8476] = { title = "Amani Encroachment", description = "Ours are not the vast kingdoms of the humans and orcs.  All we have left of our lands in Azeroth lies mostly before your eyes, {name}.\n\nUntil we can reach Outland, we must defend what little land we have at any cost.\n\nOur uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands.  Their daily raids are something we can't tolerate anymore.  Go to their settlements, Zeb'Watha and Tor'Watha, and teach them a lesson.", objectives = "" }
WordHunterWoW_QuestEN[8477] = { title = "The Spearcrafter's Hammer", description = "The Amani and the sin'dorei have a long history of mutual dislike and open hostility.  That doesn't prevent me from appreciating a fellow craftsman's work, {name}.\n\nI've come across pieces of Amani weaponry and I must admit I'm impressed by the quality of their work.  It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency.\n\nIf you bring me this tool I'll use it to craft you a weapon.", objectives = "" }
WordHunterWoW_QuestEN[8479] = { title = "Zul'Marosh", description = "Come closer, mon.  Don't be 'fraid, Ven'jashi not gonna hurt you.\n\nUs Darkspears be mortal enemies of the Amani just like you.  Their boss Zul'Marosh is evil troll.  He give me the bad poison and leave me in this cage to die.\n\nI not scared of dyin', mon.  I seen death in the eye an' I laugh at her.\n\nI cannot die in peace yet, mon.  Not 'til Zul'Marosh be dead too.  You find him 'cross the lake in Zeb'Watha.  I hold this poison off 'til you bring me his big ugly head, mon.  Only then I die peacefully.", objectives = "" }
WordHunterWoW_QuestEN[8480] = { title = "Lost Armaments", description = "The Wretched grow bolder every day, {name}.  They've achieved enough coordination to launch an attack on Sunsail Anchorage.\n\nAs if that weren't embarrassing enough, most of our weapons were left behind when they attacked.  Bring me back our armaments so that we may show those ruffians who's boss.", objectives = "" }
WordHunterWoW_QuestEN[8481] = { title = "The Root of All Evil", description = "{name}, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!\n\nTake this torch to the mouth of Grolnar's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.", objectives = "" }
WordHunterWoW_QuestEN[8482] = { title = "Incriminating Documents", description = "The documents contain detailed maps of different strategic buildings in Eversong Woods.  A diagram of an arcane sanctum is also sketched in good detail.  There seem to be numerous notes in a language you don't recognize.\n\nAs these were carried by a Darnassian spy, it might be a good idea to bring them to the Captain of the Guard - Aeldon Sunbrand.", objectives = "" }
WordHunterWoW_QuestEN[8483] = { title = "The Dwarven Spy", description = "Listen, {name}.  This is a very delicate situation; even though we've identified the spy, we cannot kill him out in the open.  We cannot try to capture him either as the risk of him escaping is too great.\n\nI want you to go find Prospector Anvilward at the North Sanctum and kill him.  Do this in a quiet manner, we don't want word to spread that we allowed a spy into our city.\n\nBring me his head as proof.  Ironforge will learn not to meddle with the sin'dorei.", objectives = "" }
WordHunterWoW_QuestEN[8486] = { title = "Arcane Instability", description = "It's about time that dimwit, Caidanis, sent someone this way.\n\nI warned of the dangers of increasing the load on the West Sanctum!  Now one of our energy converters is destroyed and arcane wraiths are pouring out of the sanctum!\n\nI'm going to need you to take care of these creatures before we send anyone in for repairs.  Make haste!", objectives = "" }
WordHunterWoW_QuestEN[8487] = { title = "Corrupted Soil", description = "This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon.\n\nNow it's as useful to us as any part of the Dead Scar.  The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted.\n\nWhat I want to know, {name}, is whether this taint is reversible or not.  I want you to collect soil samples from this area so I can study them.  Perhaps with time we can set things back to normal.", objectives = "" }
WordHunterWoW_QuestEN[8488] = { title = "Unexpected Results", description = "Something's wrong, {name}.  I sense the presence of Scourge.  Be ready to fight them!", objectives = "" }
WordHunterWoW_QuestEN[8490] = { title = "Powering our Defenses", description = "Ancient runestones once powered a protective barrier across the Eversong border.  Many were destroyed during Arthas' attack; others were stolen.\n\nOf the three that remain, only this one has retained its powers.  The runestone to the east might be salvageable, though.\n\nTake this crystal and instill its energy on the Eastern Runestone.  The process should take but a minute.  Beware though, nearby Scourge will be drawn to it and will seek to destroy it.  Do not let them! ", objectives = "" }
WordHunterWoW_QuestEN[8491] = { title = "Pelt Collection", description = "The springpaw that inhabit this region are known for their high quality pelts.  We've even seen night elf scum travel to these lands just to poach them.\n\nOur skirmishes with the Amani have put a bit of a strain on our supply of gear and our rangers don't have much time to hunt for pelts anymore.  If you'd be willing to lend a hand by collecting springpaw pelts, I'd be happy to reward you with a hand-crafted piece of armor.  You'll find springpaw stalkers all around the woods north of here.", objectives = "" }
WordHunterWoW_QuestEN[8492] = { title = "The Alliance Needs Copper Bars!", description = "Hey there, {class}, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.\n\nI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?", objectives = "" }
WordHunterWoW_QuestEN[8494] = { title = "The Alliance Needs Iron Bars!", description = "Well hello there, Mr. Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8499] = { title = "The Alliance Needs Thorium Bars!", description = "It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8503] = { title = "The Alliance Needs Stranglekelp!", description = "So, {class}, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!", objectives = "" }
WordHunterWoW_QuestEN[8505] = { title = "The Alliance Needs Purple Lotus!", description = "{class}, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.\n\nI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?", objectives = "" }
WordHunterWoW_QuestEN[8509] = { title = "The Alliance Needs Arthas' Tears!", description = "I'll keep it simple and to the point, {class}. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?", objectives = "" }
WordHunterWoW_QuestEN[8511] = { title = "The Alliance Needs Light Leather!", description = "We Stoneflayers have a long history of being skinners, {class}. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.\n\nSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, lad, will you give it a go?", objectives = "" }
WordHunterWoW_QuestEN[8513] = { title = "The Alliance Needs Medium Leather!", description = "Yes sir, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.", objectives = "" }
WordHunterWoW_QuestEN[8515] = { title = "The Alliance Needs Thick Leather!", description = "Oh boy, this is going to be great! {class}, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.\n\nSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!", objectives = "" }
WordHunterWoW_QuestEN[8517] = { title = "The Alliance Needs Linen Bandages!", description = "The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.\n\nI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8520] = { title = "The Alliance Needs Silk Bandages!", description = "With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.\n\nDo you think you can help me out, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8522] = { title = "The Alliance Needs Runecloth Bandages!", description = "Argue the merits of the war if you will, {class}, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.\n\nTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?", objectives = "" }
WordHunterWoW_QuestEN[8524] = { title = "The Alliance Needs Rainbow Fin Albacore!", description = "Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.", objectives = "" }
WordHunterWoW_QuestEN[8526] = { title = "The Alliance Needs Roast Raptor!", description = "Oh, how's it going, {class}? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.\n\nAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.", objectives = "" }
WordHunterWoW_QuestEN[8528] = { title = "The Alliance Needs Spotted Yellowtail!", description = "It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young {class}. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.\n\nAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?", objectives = "" }
WordHunterWoW_QuestEN[8532] = { title = "The Horde Needs Copper Bars!", description = "So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8542] = { title = "The Horde Needs Tin Bars!", description = "Lok'tar, {race}, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\n\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.\n", objectives = "" }
WordHunterWoW_QuestEN[8545] = { title = "The Horde Needs Mithril Bars!", description = "{class}, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!\n\nSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?", objectives = "" }
WordHunterWoW_QuestEN[8547] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Marsilla Dawnstar in Falconwing Square.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "" }
WordHunterWoW_QuestEN[8549] = { title = "The Horde Needs Peacebloom!", description = "It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.\n\nI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8556] = { title = "Signet of Unyielding Strength", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, {class}.", objectives = "" }
WordHunterWoW_QuestEN[8557] = { title = "Drape of Unyielding Strength", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", objectives = "" }
WordHunterWoW_QuestEN[8558] = { title = "Sickle of Unyielding Strength", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, {name}, and I will make you a powerful weapon from the finest Qiraji materials.", objectives = "" }
WordHunterWoW_QuestEN[8579] = { title = "Mortal Champions", description = "We sense the presence of our enslaved brethren deeper inside Ahn'Qiraj; yet not even an army of dragons would be enough to rescue them, {race}.\n\nThe same spell that imprisoned them would place us firmly under C'Thun's control should we come any closer to him.\n\nThe Old God has foreseen our arrival.  All hope is lost.  What difference could a mere mortal like you possibly make?", objectives = "" }
WordHunterWoW_QuestEN[8580] = { title = "The Horde Needs Firebloom!", description = "Hey, {class}. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki!\n\nPele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?", objectives = "" }
WordHunterWoW_QuestEN[8582] = { title = "The Horde Needs Purple Lotus!", description = "The purple lotus, {class}, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower.\n\nThat's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for us?", objectives = "" }
WordHunterWoW_QuestEN[8588] = { title = "The Horde Needs Heavy Leather!", description = "Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too.\n\nBut first we need to get our hands on more of it. That's your job, {class}. Sharpen your knife and bring me back a bundle. Then we'll talk further.", objectives = "" }
WordHunterWoW_QuestEN[8590] = { title = "The Horde Needs Thick Leather!", description = "I'm glad that you decided to speak to me about this, {class}. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part.\n\nI've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?", objectives = "" }
WordHunterWoW_QuestEN[8600] = { title = "The Horde Needs Rugged Leather!", description = "I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, {class}? But you and I don't have such problems as we maintain the sharpest of edges, yes? \n\nWell, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do, no?", objectives = "" }
WordHunterWoW_QuestEN[8604] = { title = "The Horde Needs Wool Bandages!", description = "Greetings, {class}. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them.\n\nIf you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.", objectives = "" }
WordHunterWoW_QuestEN[8607] = { title = "The Horde Needs Mageweave Bandages!", description = "I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, {class}, and I will personally see to it that you are properly rewarded.", objectives = "" }
WordHunterWoW_QuestEN[8609] = { title = "The Horde Needs Runecloth Bandages!", description = "It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war.\n\nI am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, {class}?\n", objectives = "" }
WordHunterWoW_QuestEN[8611] = { title = "The Horde Needs Lean Wolf Steaks!", description = "I'm not standing here just to get a nice tan, {class}. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too!\n\nThey have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?", objectives = "" }
WordHunterWoW_QuestEN[8613] = { title = "The Horde Needs Spotted Yellowtail!", description = "It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[8615] = { title = "The Horde Needs Baked Salmon!", description = "The Ahn'Qiraj war effort is an immense undertaking, {class}. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters.\n\nThus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, {class}?", objectives = "" }
