WordHunterWoW_QuestEN[8748] = { title = "The Path of the Protector", description = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.\n", objectives = "" }
WordHunterWoW_QuestEN[8749] = { title = "The Path of the Protector", description = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", objectives = "" }
WordHunterWoW_QuestEN[8750] = { title = "The Path of the Protector", description = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.\n", objectives = "" }
WordHunterWoW_QuestEN[8751] = { title = "The Protector of Kalimdor", description = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", objectives = "" }
