WordHunterWoW_QuestEN[8767] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[8768] = { title = "A Gaily Wrapped Present", description = "", objectives = "" }
WordHunterWoW_QuestEN[8769] = { title = "A Ticking Present", description = "", objectives = "" }
WordHunterWoW_QuestEN[8788] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[8791] = { title = "The Fall of Ossirian", description = "A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.", objectives = "" }
WordHunterWoW_QuestEN[8801] = { title = "C'Thun's Legacy", description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed.\n\nAs you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in the next chamber.", objectives = "" }
WordHunterWoW_QuestEN[8802] = { title = "The Savior of Kalimdor", description = "To the Caverns of Time you go, Lord {name}. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.\n", objectives = "" }
WordHunterWoW_QuestEN[8803] = { title = "A Festive Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[8827] = { title = "Winter's Presents", description = "I hear Greatfather Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", objectives = "" }
WordHunterWoW_QuestEN[8828] = { title = "Winter's Presents", description = "I hear Great-father Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.", objectives = "" }
WordHunterWoW_QuestEN[8860] = { title = "New Year Celebrations!", description = "Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Allison in Stormwind needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?\n\nThanks, {name}!  Innkeeper Allison is in The Gilded Rose, in the Trade District of Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[8861] = { title = "New Year Celebrations!", description = "Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!\n\nIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?\n\nThanks, {name}!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.", objectives = "" }
WordHunterWoW_QuestEN[8862] = { title = "Elune's Candle", description = "Elune's candle is an artifact of great reverence to the disciples of the Lunar Festival.  Stored within the candle is true moonlight, ready to be unleashed!\n\nThis light is harmless to most creatures, but you will find that Omen and his minions are burned and dazzled by it.", objectives = "" }
WordHunterWoW_QuestEN[8866] = { title = "Bronzebeard the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[8867] = { title = "Lunar Fireworks", description = "Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.\n\nWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!\n\nFor a small donation you can purchase colorful rockets from our vendor. Try using some of the launchers around here, {name}.", objectives = "" }
WordHunterWoW_QuestEN[8868] = { title = "Elune's Blessing", description = "The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.\n\nFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs...\n\nGather cohorts, {name}, and summon and defeat the beast Omen.  Earn the blessing of Elune!", objectives = "" }
WordHunterWoW_QuestEN[8870] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. ou will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8871] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8872] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8873] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8874] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8875] = { title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", objectives = "" }
WordHunterWoW_QuestEN[8883] = { title = "Valadar Starsong", description = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!", objectives = "" }
WordHunterWoW_QuestEN[8884] = { title = "Fish Heads, Fish Heads...", description = "Greetings, {class}.  Take a look toward the shore; what do you see?  That's right, our beach... our Tranquil Shore, has been infested with the malignancy known as the murloc.\n\nThis blight will not stand!\n\nI have a task for you.  If you feel that you're up to it, I would have their heads!  Let us see if we can put a dent in their numbers so large that, if they have any sense at all, they will return to the murky depths from which they sprang!", objectives = "" }
WordHunterWoW_QuestEN[8885] = { title = "The Ring of Mmmrrrggglll", description = "The Grimscale murlocs have not been scared off by your efforts. But, I think I know what will send them packing, as well as get me some personal retribution.\n\nThey have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand south of the river inlet. The beast once slew a compatriot of mine, and now wears his ring in open defiance and mockery.\n\nSlay Mmmrrrggglll, and bring back my friend's ring. Then we shall see these monsters cowed!", objectives = "" }
WordHunterWoW_QuestEN[8886] = { title = "Grimscale Pirates!", description = "Thank goodness for you, {class}! Those slimy Grimscale murlocs have pirated away my cargo! It's bad enough that the Wretched have stolen what little magical goods I had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for any of it at this point. It was the Grimscale murlocs in the huts, just to the west and south of the anchorage on the Golden Strand, I'm sure of it!\n", objectives = "" }
WordHunterWoW_QuestEN[8887] = { title = "Captain Kelisendra's Lost Rutters", description = "Interesting... what you have found here is a water-proofed, leather tube containing a number of sheets of parchment. By the markings upon them, the pages are clearly navigation rutters, and each bears the signature of one Captain Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail Anchorage. Maybe the captain is there?", objectives = "" }
WordHunterWoW_QuestEN[8888] = { title = "The Magister's Apprentice", description = "{class}, hear my request. For reasons that I cannot go into now, I decided to shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice Loralthalis, there with this very task. I have not heard back from her since.\n\nWill you go to Duskwither Spire and check in on her, to make sure that she is well? You'll find it by heading north on the path out of Farstrider Retreat, then go to the right when the road branches.", objectives = "" }
WordHunterWoW_QuestEN[8889] = { title = "Deactivating the Spire", description = "As you may know, Magister Duskwither sent me back here to shut down the power sources that feed the Spire. There are three of them, each located in a different place inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun with strange, magical creatures. While I haven't the expertise to accomplish this task, surely a {class}, such as yourself, could do so easily?", objectives = "" }
WordHunterWoW_QuestEN[8890] = { title = "Word from the Spire", description = "{name}, I have one last favor to ask of you. Would you please relay what's transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know that I am well, but make certain that he is aware that some of the apprentices have become Wretched.\n\nThank you for your help!", objectives = "" }
WordHunterWoW_QuestEN[8891] = { title = "Abandoned Investigations", description = "You have discovered what appears to be an investigative journal left behind by Magister Duskwither. A brief scan of its contents reveal some shocking attempts at filtering corrupted magical flows, which might explain what has happened here at Duskwither Spire. The magister is sure to want this brought back to him.", objectives = "" }
WordHunterWoW_QuestEN[8892] = { title = "Situation at Sunsail Anchorage", description = "Sunsail Anchorage has been overrun by Wretched scum.  As soon as we manage to get reinforcements to the area we'll show those thugs who's boss, {name}.\n\nIn the meantime you can help by showing them a bit of discipline.  Go in there and show them we are not to be trifled with.  You will find Sunsail Anchorage just to the west of Fairbreeze Village.", objectives = "" }
WordHunterWoW_QuestEN[8894] = { title = "Cleaning up the Grounds", description = "It's horrible, I tell you! Strange things happening in the spire, the magister and his apprentices run off, and then the next thing that you know, the whole grounds are overrun with these magical beasties! And who told Wyllithen? No one, that's who!\n\n{class}, you've got to help me clear some of these things out... I cannot maintain the grounds while these 'anomalies' are running amok!", objectives = "" }
WordHunterWoW_QuestEN[8895] = { title = "Delivery to the North Sanctum", description = "I'm pleased to discover that you're at least somewhat competent, {name}.  I'll give you another task since you seem so eager to prove yourself.\n\nThis is a letter to Ley-Keeper Caidanis, the arcanist in charge of the upkeep of the North Sanctum.  Go southwest of Falconwing Square  and you will find him.  He is a very important person, so I hope you don't bother him too much with trivial chatter.", objectives = "" }
WordHunterWoW_QuestEN[8897] = { title = "Dearest Colara,", description = "I've got to keep watch here at the gate, but I'm always worrying about my sweetheart, Colara. I only get to see her for a few hours, if I'm lucky, and well, just look at me. I've got a minor officer's pay and I could be called to the front any day now.\n\nWould she just forget about me? There are a lot of men in the city. A lot of rich ones.\n\nAnyways, I've scribbled some things down... nothing much, but if you could take it to her for me, that'd be great.", objectives = "" }
WordHunterWoW_QuestEN[8898] = { title = "Dearest Colara,", description = "I met a lass in Stormwind when I was last there on the bank's business. She stole my heart away. Now, I can't stop thinking about her! I'd like to send her this message - I've rewritten it twelve times!\n\nThe mail is so full now, and I want to make sure it gets there.\n\nIf you're heading that way, could you help me?", objectives = "" }
WordHunterWoW_QuestEN[8899] = { title = "Dearest Colara,", description = "How to describe her beauty? Thousands of years of words and I am at a loss.\n\nThese mortals confound the mind and leave us babbling fools.\n\nI've stared at these words too long. No more eloquent meaning can I squeeze from them. No, she must have it now, or some other suitor will surely steal her eye.", objectives = "" }
WordHunterWoW_QuestEN[8900] = { title = "Dearest Elenia,", description = "She was so sad. I could see that, once I saw past her state. I mean, she seemed sad - wouldn't you?\n\nBut after talking to her, there was a connection. I didn't think anyone could understand what I was thinking, but she could.\n\nWhen I told the others, they laughed at me, so I never spoke with her again. But I miss her. Can you take this letter to her for me? I want to be sure it finds her hands.", objectives = "" }
WordHunterWoW_QuestEN[8901] = { title = "Dearest Elenia,", description = "Have you ever known love, young one? It was a thing foreign to me until lately, when I met a girl from the Undercity, Elenia. It is rare enough for one of my kind to look outside our own, let alone one of the Forsaken.\n\nBut now thoughts of her occupy my mind both days and nights.\n\nIf you can, could you take this letter to her? I want her to come here to Mulgore. I hope that she will say yes.", objectives = "" }
WordHunterWoW_QuestEN[8902] = { title = "Dearest Elenia,", description = "A lifetime ago, I was betrothed to marry Elenia, my childhood sweetheart. It's been years since I thought about her last, but of late, she frequently occupies my thoughts.\n\nPerhaps, even with everything that has passed, there can be some room in each other's lives for our love.\n\nI'm sure she has changed, also. Can you deliver this letter to her for me? I am too nervous to give it in person.", objectives = "" }
WordHunterWoW_QuestEN[8979] = { title = "Fenstad's Hunch", description = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.", objectives = "" }
WordHunterWoW_QuestEN[8980] = { title = "Zinge's Assessment", description = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.", objectives = "" }
WordHunterWoW_QuestEN[8982] = { title = "Tracing the Source", description = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.", objectives = "" }
WordHunterWoW_QuestEN[8983] = { title = "Tracing the Source", description = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Magic Quarter.", objectives = "" }
WordHunterWoW_QuestEN[8984] = { title = "The Source Revealed", description = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction.\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.", objectives = "" }
WordHunterWoW_QuestEN[9024] = { title = "Aristan's Hunch", description = "I've got it! Have you smelled the new fragrance on the wind? The new colognes and perfumes that have come into fashion? Our guards wouldn't neglect their duties so easily.\n\nThat is, unless their thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to Morgan Pestle, and tell him my suspicions. I will reimburse you for their purchase when you return.", objectives = "" }
WordHunterWoW_QuestEN[9025] = { title = "Morgan's Discovery", description = "Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.\n\nIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.", objectives = "" }
WordHunterWoW_QuestEN[9026] = { title = "Tracing the Source", description = "We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from.", objectives = "" }
WordHunterWoW_QuestEN[9027] = { title = "Tracing the Source", description = "Something funny about the cologne? It's possible. I've never seen so many people after one product like this.\n\nLook, if there's something wrong with it, I want to know, too. I bought my supply from a merchant named Evert Sorisam. He's new in town.\n\nHe mentioned he had some goods he was going to deliver to The Finest Thread.", objectives = "" }
WordHunterWoW_QuestEN[9028] = { title = "The Source Revealed", description = "What? Treason? No, no. I assure you, my intentions are completely harmless.\n\nIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.\n\nAnd to prove that I mean no harm, I will even tell you my source.\n\nThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.\n\nOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him.", objectives = "" }
WordHunterWoW_QuestEN[9029] = { title = "A Bubbling Cauldron", description = "", objectives = "" }
WordHunterWoW_QuestEN[9035] = { title = "Roadside Ambush", description = "You, there!  You must help me, please!\n\nA fellow apprentice and I were attacked by the Wretched!  In their mad hunger for magic, they took everything they could get their hands on: mana crystals, wands, spellbooks... everything!\n\nMeledor gave chase after them; I had to stay behind and look after what they didn't take.  Continue down the road and see if you can lend him a hand.", objectives = "" }
WordHunterWoW_QuestEN[9062] = { title = "Soaked Pages", description = "Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them.  But let's not worry about that now.  I need to find my instructor's elemental grimoire.\n\nI'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it.  I could use another set of eyes.  I'll throw in a bit of coin if you spot it.", objectives = "" }
WordHunterWoW_QuestEN[9064] = { title = "Taking the Fall", description = "Antheol is going to fly off his rocker when he finds out his book is ruined.  I've got a little proposal for you; don't worry, I'll make it worth your while.\n\nTake this book to him and tell him nothing of this incident.  If he asks, just tell him you dropped the book into a puddle.  He has no direct authority over you, so there's not much he can do.\n\nAntheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon.  You'll do this for us, right?  I'll reward you handsomely for this favor!", objectives = "" }
WordHunterWoW_QuestEN[9066] = { title = "Swift Discipline", description = "I hope you learn a valuable lesson today, {name}.  Never trust someone else to lie for you.\n\nNow I want you to go back to my two dimwitted students and discipline them using this wand.  My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar.\n\nCome back to me after you've done this.  I'll give you a small reward for your troubles.", objectives = "" }
WordHunterWoW_QuestEN[9067] = { title = "The Party Never Ends", description = "I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas!\n\nBut, I'm in a bit of a bind.  I need you to gather up more party supplies.\n\nFrom Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve.  From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers.  And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village.\n\nBe quick about it!", objectives = "" }
WordHunterWoW_QuestEN[9076] = { title = "Wretched Ringleader", description = "The Wretched are so oblivious, gorging on foul magic, that they haven't realized we've recovered most of our weapons.  We can't expect them to remain in their stupor, though.  Now is the time for a decisive attack.  Let us make an example of their leader, Aldaron.  He was spotted on the top floor of the building by the anchorage.  Bring me his head; I'll reward you suitably.", objectives = "" }
WordHunterWoW_QuestEN[9085] = { title = "Shadows of Doom", description = "After you bring down the defenses of the Scourge summoning circles, you must confront the acolytes who protect them.\n\nIn truth, these are not men. They are shadows, some of the Lich King's most frightening creatures. They can be revealed using the necrotic runes they carry, and then destroyed with magic or strength of arms.", objectives = "" }
WordHunterWoW_QuestEN[9119] = { title = "Malfunction at the West Sanctum", description = "Since you're here, {name}, I've a favor to ask you.  Ley-Keeper Velania's apprentice dropped by earlier to ask for assistance.  Apparently there's some malfunction happening at the West Sanctum.  I've been a bit busy entertaining our... most pleasant... dwarven guest.  See if you can give her a hand.  You'll find the West Sanctum southwest of here.", objectives = "" }
WordHunterWoW_QuestEN[9130] = { title = "Goods from Silvermoon City", description = "Welcome volunteer!  We're running low on supplies here, but Silvermoon has promised us materiel assistance.  That's where you come in.\n\nTake this list over to Skymaster Brightdawn. He'll have further instructions for you on how best to get up to Silvermoon City.", objectives = "" }
WordHunterWoW_QuestEN[9133] = { title = "Fly to Silvermoon City", description = "{class}, for a very modest amount of coin, I can send you swiftly flying through the air on one of these magnificent beasts.  And, it's safer than walking there, I can assure you!\n\nWhen you arrive in Silvermoon City, seek out Sathren Azuredawn in the Bazaar.\n\nSpeak with me once more when you've decided you're ready to brave the skies.", objectives = "" }
WordHunterWoW_QuestEN[9134] = { title = "Skymistress Gloaming", description = "It doesn't look as if you have a cart or a beast of burden with you, so I'd better send you back only with what you can carry.  If you've spoken with Skymaster Brightdawn at Fairbreeze Village, then you should get this to Sathiel as soon as possible by flying back.\n\nTake these goods for final inspection to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.", objectives = "" }
WordHunterWoW_QuestEN[9135] = { title = "Return to Sathiel", description = "It all checks out as far as I can tell.\n\nSo, the question is, have you already spoken to Skymaster Brightdawn in Fairbreeze Village?  If so, then this can be as simple as you paying the small fare and quickly flying back.\n\nLet me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[9138] = { title = "Suncrown Village", description = "We're surrounded here, {class}.  The outlying villages have all been overrun by the Scourge!\n\nYou must head northeast to Suncrown Village immediately and deal with the Nerubian Scourge menace.  You can't miss them - they're spider-like creatures.\n\nThere's no time to waste.... Quel'Thalas must be reclaimed!", objectives = "" }
WordHunterWoW_QuestEN[9139] = { title = "Goldenmist Village", description = "We've had one success, but there are two more villages that must be reclaimed!\n\nGoldenmist Village is our next target. It lies to the northwest, and has been taken by the ghosts of the high elves that used to live there. Gruesome, I know, but these are apparently the sorts of tactics that the Scourge like to employ.\n\nGo and defeat these ghosts and wraiths, {class}. Take the west road out of Tranquillien to get there.", objectives = "" }
WordHunterWoW_QuestEN[9140] = { title = "Windrunner Village", description = "{name}, the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers.\n\nThe magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them.\n\nGood hunting!", objectives = "" }
WordHunterWoW_QuestEN[9143] = { title = "Dealing with Zeb'Sora", description = "The lieutenant here rushed us into battle with the trolls across the lake instead of scouting the situation first. We were decimated by his stupidity! You hear me Tomathren? You're an idiot!\n\nWill you help us, {class}? Those trolls still need to be dealt with. I need to stay here and nursemaid him -- I think he's lost his mind.\n\nJust head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their ears so that I can fashion a nice necklace!", objectives = "" }
WordHunterWoW_QuestEN[9144] = { title = "Missing in the Ghostlands", description = "My nephew was sent into the Ghostlands a few days ago.  He never mentioned anything about his task, except that it was of an extremely secret nature.\n\nHe never returned and I fear for the worst, {class}.  A missing messenger might not mean much to the callous magisters of Silvermoon, but he's like a son to me.  Please, {name}, will you look for him?", objectives = "" }
WordHunterWoW_QuestEN[9145] = { title = "Help Ranger Valanna!", description = "{class}, I can't just sit here waiting for an audience with the high executor or Dame Auriferous! This cannot wait!\n\nWe were dealing with the Shadowpine trolls of Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack and we lost a lot of Farstriders. Then he just fell to pieces afterward.  Ranger Valanna sent me here, and Ranger Salissa to the Farstrider Enclave for help.\n\nPlease find them, {class}. Valanna was badly injured and the lieutenant's useless.", objectives = "" }
WordHunterWoW_QuestEN[9146] = { title = "Report to Captain Helios", description = "I need one last favor of you, {class}.  Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help.\n\nJust check in with Captain Helios and let him know what's happened here.  I'm sure he'll send help back as soon as he can.", objectives = "" }
WordHunterWoW_QuestEN[9147] = { title = "The Fallen Courier", description = "What are you standing around for?  Can't you see this boy needs immediate attention?  By the looks of it, the plague is beginning to take over his body.  Within minutes not even a master apothecary like me will be able to save him.\n\nThe animals south of the river all carry the plague in their blood.  Go across the bridge and hunt the plagued beasts there.  Bring me enough plagued blood samples and I'll distill a serum capable of saving this blood elf.  Hurry!", objectives = "" }
WordHunterWoW_QuestEN[9148] = { title = "Delivery to Tranquillien", description = "I... I'm too weak to continue.  I carry a dire warning from Regent Lord Theron, in the form of a letter.  You'll have to deliver it for me.\n\nTake it to Arcanist Vandril in Tranquillien.  You'll find the town further to the south along this road.  Go there and... find Vandril...", objectives = "" }
WordHunterWoW_QuestEN[9149] = { title = "The Plagued Coast", description = "To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies.\n\nI've come here to study the murlocs since, like us, they've retained free will in undeath.  What makes these lowly mongrels so special?  I need to find out, {name}!\n\nTravel northwest and bring me their spines so that I may study the accumulation of plague in their marrow.  Who knows what secrets their little bones hold?", objectives = "" }
WordHunterWoW_QuestEN[9150] = { title = "Salvaging the Past", description = "Can you believe it?  We have an actual functioning arcane sanctum up and running southeast of here: the Sanctum of the Sun.  All manner of important magisters have come to take part in running it.\n\nOf course they've all forgotten about the Sanctum of the Moon.  Not much remains of it and its energies have given rise to bizarre creatures.\n\nI'm not one to let good resources go to waste, however.  Go to the Sanctum of the Moon and see if you can recover the crystallized essences from the creatures there.", objectives = "" }
WordHunterWoW_QuestEN[9151] = { title = "The Sanctum of the Sun", description = "You've proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge.  Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy's doorstep.\n\nThey've rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area.  They plan to launch an offensive into Deatholme, Dar'Khan's stronghold.  You would do well to join them, {name}.  I'm sure they can make use of a seasoned {class} like yourself.", objectives = "" }
WordHunterWoW_QuestEN[9152] = { title = "Tomber's Supplies", description = "How am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of ghouls!\n\nWant to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the Dead Scar is a fork in the road. The hill that my cart had to be left on lies just beyond.", objectives = "" }
WordHunterWoW_QuestEN[9153] = { title = "Under the Shadow", description = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.\n\nOnly through our combined efforts will they be repelled.\n\nEach necropolis is supported by nearby magical circles, and among each circle swarms a host of undead creartures. We have determined that destroying these mindless hordes will destroy the circle's defenses.", objectives = "" }
WordHunterWoW_QuestEN[9154] = { title = "Light's Hope Chapel", description = "The Scourge have returned in greater numbers than we have seen before.  This must be the doing of the Lich King!  The Argent Dawn is recruiting all willing and capable men and women to defend our lands.\n\nIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectives = "" }
WordHunterWoW_QuestEN[9155] = { title = "Down the Dead Scar", description = "If you've made it this far then you probably know about the Dead Scar and how to this day mindless Scourge follow the path of destruction that Arthas created on his way to Silvermoon City.\n\nMake yourself useful and thin down the Scourge's numbers in the Scar.  If you prove to be worth your salt I'll put in a good word for you.", objectives = "" }
WordHunterWoW_QuestEN[9156] = { title = "WANTED: Knucklerot and Luzran", description = "A bounty is hereby declared for the abominations known as Knucklerot and Luzran.  These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats.  Individuals seeking to claim the reward must present the abominations' heads to Deathstalker Rathiel as proof of the deed.", objectives = "" }
WordHunterWoW_QuestEN[9157] = { title = "Forgotten Rituals", description = "Every year we, the denizens of Suncrown Village, would take part in a ritual to keep the different aspects of nature under our control.  Dominion over the element of water was symbolized by the summoning and enslavement of an elemental named Aquantion.  Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us instead!\n\nWe wore medallions shaped like waves during the ritual.  Seek them at the bottom of the lake; we'll need them to free my compatriots' spirits!", objectives = "" }
WordHunterWoW_QuestEN[9158] = { title = "Bearers of the Plague", description = "You show courage coming to the Ghostlands, {name}.  There is much work to be done here and not enough brave souls to do it.\n\nI've a thankless task to offer you, should you have the inclination to aid our cause.  The very wildlife in this land has been tainted by the plague and we must stop it from spreading.  Hunt the ghostclaw lynxes to the east and south of here and return when you've slain enough of them.", objectives = "" }
WordHunterWoW_QuestEN[9159] = { title = "Curbing the Plague", description = "You've proven your worth as an ally, {name}.  I need you to continue your task and track down more plagued wildlife.  This time seek out some of the more dangerous beasts.  Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here.  Return to me when you're done.", objectives = "" }
WordHunterWoW_QuestEN[9160] = { title = "Investigate An'daroth", description = "{class}, we are having difficulty with a group of night elves that have recently taken over a nearby island. They've set up a small camp at the old high elf ley-line nexus, An'daroth, to the northwest. There is a dirt path that leads up to it just past the Dead Scar.\n\nI suggest that you lend us your aid by going there, investigating what they are up to, and slaying as many of the conceited night elves as you can.", objectives = "" }
WordHunterWoW_QuestEN[9161] = { title = "The Traitor's Shadow", description = "Dar'Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands.  Dar'Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf.  Much of his time was spent inside Dawnstar Spire, northeast of here.  He hid there for many nights, scheming against his own. \n\nSearch the tower for more information, {name}.  Perhaps he had a journal or kept notes.  One never knows where useful information might present itself.", objectives = "" }
WordHunterWoW_QuestEN[9162] = { title = "Hints of the Past", description = "As you skim through the pages in the journal you're overcome by an unnerving sense of being watched.\n\nThe contents are unsettling.  Dar'Khan's soul was one filled with hatred and contempt for his own people.  The extent of his machinations and plots are all documented in great detail.\n\nPerhaps there is something here that Vynna will find useful.", objectives = "" }
WordHunterWoW_QuestEN[9163] = { title = "Into Occupied Territory", description = "Now, the more direct course of action that we are going to take, to figure out what these night elves are really up to, is to have you go to their island and steal any information that you can come by.\n\nI want you to head west down the road out of town to Shalandis Isle, just off the coast. Go there and recover any plans they might have on the island or on their ship.", objectives = "" }
WordHunterWoW_QuestEN[9164] = { title = "Captives at Deatholme", description = "Ah, yes. I possess a draught that will break most forms of alchemically induced stupor.\n\nSide effects include confusion, nausea and - in rare cases - temporary blindness. All much preferable to whatever the Scourge plans to do to those prisoners in Deatholme, if you ask me.\n\nBest of luck, brave {class}. You are going to need it.", objectives = "" }
WordHunterWoW_QuestEN[9166] = { title = "Deliver the Plans to An'telas", description = "You must deliver the recovered night elf plans to An'telas for me. It is to the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum of the Sun.\n\nMagister Sylastor is there conducting ongoing studies into the ley-line nexus energy for potential use in our fight against the Scourge. Have him look at these plans to shed some light on what it is that these night elves are up to.", objectives = "" }
WordHunterWoW_QuestEN[9167] = { title = "The Traitor's Destruction", description = "Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours.  The Scourge have maintained their chokehold on the region for far too long.\n\nThe time has come for payback, {name}.  Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours.\n\nHe who sought to steal the power of the Sunwell must die.  Go to Deatholme, the Scourge stronghold south of the Dead Scar.  Bring me Dar'Khan's head and your deeds will go down in history!", objectives = "" }
WordHunterWoW_QuestEN[9169] = { title = "Deactivate An'owyn", description = "Their moon crystals are scrying devices -- they're going to spy on us! I know that An'daroth can't provide enough power for that, but An'owyn, directly to the south, most definitely can!\n\nFrom the plans I now have a basic knowledge of how these moon crystals work; enough to shut them down. They're keyed so that they can be turned off. You must go to An'owyn, retrieve the controlling orb from one of the night elves and then use it on the moon crystal to stop them from enacting their plan!\n\nHurry, {class}!", objectives = "" }
WordHunterWoW_QuestEN[9170] = { title = "Dar'Khan's Lieutenants", description = "The odious traitor, Dar'Khan, has risen to great power among the ranks of the Scourge.  His lieutenants command vast armies of undead against our dwindling numbers.\n\nMasophet the Black, Jurion the Deceiver, Borgoth the Bloodletter, Mirdoran the Fallen.  Learn these names well for in the Ghostlands these Scourge leaders are second only to Dar'Khan himself.  Slay them and their mindless armies will be thrown into disarray.", objectives = "" }
WordHunterWoW_QuestEN[9171] = { title = "Culinary Crunch", description = "This is intolerable!  I have nothing to work with here! Milady asks me to come from Silvermoon City; she deserves cuisine as befits her station.  No?  But I get here and there is no food.  You must go out, {class}, and bring back fresh kills so that I have something to prepare.\n\nDame Auriferous prefers a crunchy texture to her food.  There are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar.  Disgusting, I know, but that's what we have to work with.", objectives = "" }
WordHunterWoW_QuestEN[9172] = { title = "Report to Magister Kaendris", description = "The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge's weaknesses with the aid of the Forsaken.  Magister Kaendris will know what to do with this information.\n\nYou'll find the Sanctum of the Sun southwest of here.  You must hurry, {name}.  Dar'Khan is a cunning enemy and watches our every move!", objectives = "" }
WordHunterWoW_QuestEN[9173] = { title = "Retaking Windrunner Spire", description = "{class}, I want you to reclaim Windrunner Spire!\n\nIt's an honor, really. Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken and former ranger-general of the elves. But now it's been overrun by the mindless Scourge.\n\nTo get there take the road south until it branches. Take the right fork and after crossing the Dead Scar continue southwest. You can't miss it.", objectives = "" }
WordHunterWoW_QuestEN[9174] = { title = "Vanquishing Aquantion", description = "That willful elemental ended many lives that fateful day when he revolted against us.  By calling to the lowly murloc to sabotage our rites he subverted our magic and turned it against us.\n\nShow him our thirst for vengeance has not waned!  Take these medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake.  Aquantion shall immediately answer your summons!\n\nBeware, {race}!  Without our magic controlling him, his wrath will be unrestrained.  Destroy Aquantion so we may rest!", objectives = "" }
WordHunterWoW_QuestEN[9175] = { title = "The Lady's Necklace", description = "The necklace shimmers, a remarkable piece of jewelry that doesn't seem to succumb to the gloom that permeates the Ghostlands. Given the inscription, and where you found it, it must be the lost property of Lady Sylvanas Windrunner herself!\n\nPerhaps it would be best to first take it to High Executor Mavren at Tranquillien? He seems to be the highest ranking Forsaken in the area and is sure to know what to do with it.", objectives = "" }
WordHunterWoW_QuestEN[9176] = { title = "The Twin Ziggurats", description = "According to this journal, Dar'Khan promised the Scourge two powerful elven artifacts: the stone of light and the stone of flame.  These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge.\n\nThe crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat now stand, in the middle of the Dead Scar.  If they're still held there, we need to recover them.  Their power will be greatly useful in our struggle against the enemy.", objectives = "" }
WordHunterWoW_QuestEN[9177] = { title = "Journey to Undercity", description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.", objectives = "" }
WordHunterWoW_QuestEN[9180] = { title = "Journey to Undercity", description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity.  Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.", objectives = "" }
WordHunterWoW_QuestEN[9192] = { title = "Trouble at the Underlight Mines", description = "The Underlight Mines to the southwest have been overrun by a clan of gnolls calling themselves the Blackpaw. I don't need to remind you how important those mines are to us as a strategic asset in our ongoing campaign here in the Ghostlands!\n\nTake the south road out of town and follow the fork to the right. Just past the ziggurat on the right there will be a short dirt path to the west. Follow it.\n\nThe ore must flow!", objectives = "" }
WordHunterWoW_QuestEN[9193] = { title = "Investigate the Amani Catacombs", description = "{class}, our sources tell us that the trolls buried in the Amani Catacombs inside Sungraze Peak have been rising from the dead. I need you to investigate these catacombs and put to the torch any of the unanimated remains you come across so as to prevent any more of these creatures from rising.\n\nThe fastest way there is to head northwest out of the enclave. This will put you near the western entrance to the catacombs.", objectives = "" }
WordHunterWoW_QuestEN[9199] = { title = "Troll Juju", description = "The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise. Some of these mummy trolls, and their living counterparts, carry juju; glowing objects that house an unknown power source.  It's probably what is animating them!\n\nThe catacombs lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies on the north face of the mountain. See to it, {class}!", objectives = "" }
WordHunterWoW_QuestEN[9207] = { title = "Underlight Ore Samples", description = "I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, {class}?\n\nYou can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.", objectives = "" }
WordHunterWoW_QuestEN[9212] = { title = "Escape from the Catacombs", description = "These trolls ambushed me and have been keeping me in this cage.  I think they're planning to sacrifice me!  Help me get out of here!\n\nThe lock on the cage isn't that complex... I just can't get to it from this side.  Please escort me back to the Farstrider Enclave.  I'm sure Captain Helios will reward you, and you'll have my undying gratitude!", objectives = "" }
WordHunterWoW_QuestEN[9214] = { title = "Shadowpine Weaponry", description = "{class}, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge.\n\nHit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.", objectives = "" }
WordHunterWoW_QuestEN[9215] = { title = "Bring Me Kel'gash's Head!", description = "WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa.\n\n\n\nREWARD: Yes, but no advances!", objectives = "" }
WordHunterWoW_QuestEN[9216] = { title = "Rotting Hearts", description = "I hear the Amani trolls eat their enemies' hearts to steal their strength.  They might just be on to something, {name}.  With the proper treatment, the hearts of the unliving can produce potent elixirs.\n\nHunt down the zombies that roam the Dead Scar and bring me their hearts.  I'll show you the kind of enhancement we can perform to your physical prowess against the undead.", objectives = "" }
WordHunterWoW_QuestEN[9218] = { title = "Spinal Dust", description = "The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine.  I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead.\n\nBring me some spinal dust and I'll be glad to provide you with a sample.  You'll find an ample number of skeletons wandering the Dead Scar, west of here.", objectives = "" }
WordHunterWoW_QuestEN[9220] = { title = "War on Deatholme", description = "If you seek to aid our cause there is no better place to start than here and no better time to do it than now.\n\nBy rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme.\n\nGo forth and fight the hordes of undead that inhabit the vile Scourge fortress.", objectives = "" }
WordHunterWoW_QuestEN[9247] = { title = "The Keeper's Call", description = "{name},\n\nIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.\n\n{name}, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.", objectives = "" }
WordHunterWoW_QuestEN[9250] = { title = "Frame of Atiesh", description = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.\n\nFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.", objectives = "" }
WordHunterWoW_QuestEN[9251] = { title = "Atiesh, the Befouled Greatstaff", description = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, {name}. I only do as I must.\n\nKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.\n\nAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.\n\nShould you succeed in recovering the pieces, return them to me.", objectives = "" }
WordHunterWoW_QuestEN[9252] = { title = "Defending Fairbreeze Village", description = "We've experienced a marked increase in Scourge attacks, {name}.  Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City.  Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.", objectives = "" }
WordHunterWoW_QuestEN[9253] = { title = "Runewarden Deryan", description = "This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands.\n\nWe used these ancient stones to protect us against the undead.  Most of them were destroyed or lost after the attack on the Sunwell. \n\nFollow the road south, towards the Ghostlands, and look to the west for a small path.  You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.", objectives = "" }
WordHunterWoW_QuestEN[9254] = { title = "The Wayward Apprentice", description = "Thank you for your help, {name}.  While I get things back in order here, I'd like to ask you for a favor.  One of my former apprentices embarked in a very dangerous line of research.  She journeyed to the East Sanctum, in the middle of the Dead Scar.\n\nI worry for her well-being.  See if you can find her and convince her to return to her senses.", objectives = "" }
WordHunterWoW_QuestEN[9255] = { title = "Research Notes", description = "As discouraging as my research results are, they still contain valuable data. I must have a Magister review my work before it is taken seriously. Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.", objectives = "" }
WordHunterWoW_QuestEN[9256] = { title = "Fairbreeze Village", description = "I have another task for you, {name}.  Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard.  He has requested reinforcements which we cannot yet provide.  Seek him out and grant him whatever aid you can.\n\nFairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south.  Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[9257] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9258] = { title = "The Scorched Grove", description = "A foul taint in the soil precedes the expansion of the Scourge into a new area.  The protective runestones along the border with the Ghostlands have warded the land against this taint in the past.\n\nThe westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading.\n\nMy sister, Larianna Riverwind, watches over the Scorched Grove.  Go find her; she might have some work for you.", objectives = "" }
WordHunterWoW_QuestEN[9260] = { title = "Investigate the Scourge of Stormwind", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9261] = { title = "Investigate the Scourge of Ironforge", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Ironforge from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9262] = { title = "Investigate the Scourge of Darnassus", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Darnassus from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9263] = { title = "Investigate the Scourge of Orgrimmar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Orgrimmar from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9264] = { title = "Investigate the Scourge of Thunder Bluff", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Thunder Bluff from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9265] = { title = "Investigate the Scourge of the Undercity", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[9269] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9270] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9271] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9272] = { title = "Dressing the Part", description = "", objectives = "" }
WordHunterWoW_QuestEN[9274] = { title = "Spirits of the Drowned", description = "The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, {name}.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.\n\nThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.\n\nIf you're up to the task, I want you to go to the lake and put an end to their suffering, {name}.  You will have my gratitude as well as theirs... I'm sure.", objectives = "" }
WordHunterWoW_QuestEN[9275] = { title = "A Little Dash of Seasoning", description = "I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem.\n\nAt my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining!\n\nCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.", objectives = "" }
WordHunterWoW_QuestEN[9276] = { title = "Attack on Zeb'Tela", description = "Our resources are spread pretty thin here, {class}, so your help is going to be invaluable.  The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out.\n\nUntil then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased.\n\nThink you could head east to Zeb'Tela and hurt them a little?", objectives = "" }
WordHunterWoW_QuestEN[9277] = { title = "Assault on Zeb'Nowa", description = "Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal.\n\nWhat do you say, {name}? Ready to deal with some more trolls?", objectives = "" }
WordHunterWoW_QuestEN[9278] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Jaeleil in Azure Watch.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "" }
WordHunterWoW_QuestEN[9279] = { title = "You Survived!", description = "Nevermind my injuries, brother. It's a miracle that any of us are alive!\n\nIt didn't look like you'd pull through; you've been in suspension for weeks.\n\nSomething happened and the Exodar crashed. Many have died.\n\nBut I'm relieved that you are alive, {name}. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.", objectives = "" }
WordHunterWoW_QuestEN[9280] = { title = "Replenishing the Healing Crystals", description = "Our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but they are mostly concentrated in the northwest.", objectives = "" }
WordHunterWoW_QuestEN[9281] = { title = "Clearing the Way", description = "Magister Kaendris sent me down here to clear the area of any hostile wildlife.  Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge.\n\nNow if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life!\n\nIf you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.", objectives = "" }
WordHunterWoW_QuestEN[9282] = { title = "The Farstrider Enclave", description = "Magisters and Farstriders may not see eye to eye all the time, {name}.  When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions.\n\nRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.  ", objectives = "" }
WordHunterWoW_QuestEN[9283] = { title = "Rescue the Survivors!", description = "The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.\n\nYou'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.\n\nThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.\n\nYou must save them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[9292] = { title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", objectives = "" }
WordHunterWoW_QuestEN[9293] = { title = "What Must Be Done...", description = "The nearby lake has been contaminated by one of the ship's power crystals.  Many of the plants and animals of Ammen Vale have been mutated because of this.\n\nI have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis.  They can be found to the west in the Ammen Fields.\n\nWill you help me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[9294] = { title = "Healing the Lake", description = "Thank goodness, I think it'll work!  I have an agent for you to spread at Silverline Lake to the south.  It will neutralize the effects of the irradiated ship's power crystal that fell there.\n\nSwim out and scatter the neutralizing agent near it.  Don't worry, you won't be exposed long enough to become irradiated.", objectives = "" }
WordHunterWoW_QuestEN[9295] = { title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9299] = { title = "Note from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9300] = { title = "Page from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9301] = { title = "Envelope from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9302] = { title = "Missive from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9303] = { title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[9304] = { title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "" }
WordHunterWoW_QuestEN[9305] = { title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", objectives = "" }
WordHunterWoW_QuestEN[9309] = { title = "The Missing Scout", description = "We now have several separate confirmations of unusual activity up on the Shadow Ridge.\n\nThis is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet.\n\n{class}, I need you to head southwest to the other side of Silverline Lake and find Tolaan, and see what has delayed him.", objectives = "" }
WordHunterWoW_QuestEN[9310] = { title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal faintly radiating necrotic energy.", objectives = "" }
WordHunterWoW_QuestEN[9311] = { title = "Blood Elf Spy", description = "I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed.\n\nThen Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.", objectives = "" }
WordHunterWoW_QuestEN[9312] = { title = "The Emitter", description = "{name}, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.", objectives = "" }
WordHunterWoW_QuestEN[9313] = { title = "Travel to Azure Watch", description = "By all that is good, {name}, you must go at once to this Azure Watch and speak with Dyvuun!\n\nThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.\n\nSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.\n\nThank you, we wouldn't have made it without you!", objectives = "" }
WordHunterWoW_QuestEN[9314] = { title = "Word from Azure Watch", description = "{class}! A couple mutated beasts jumped me and my leg is injured.\n\nI was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch.\n\nBe sure to ask her for a place for yourself to stay in.", objectives = "" }
WordHunterWoW_QuestEN[9315] = { title = "Anok'suten", description = "Come closer, I am ... dying.\n\nI was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader.\n\n<The dying blood elf coughs up a good amount of blood.>\n\nYou must find and ... slay Anok'suten.  Get help.  She wanders around ... Suncrown Village.", objectives = "" }
WordHunterWoW_QuestEN[9319] = { title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", objectives = "" }
WordHunterWoW_QuestEN[9322] = { title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", objectives = "" }
WordHunterWoW_QuestEN[9323] = { title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", objectives = "" }
WordHunterWoW_QuestEN[9324] = { title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "" }
WordHunterWoW_QuestEN[9325] = { title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "" }
WordHunterWoW_QuestEN[9326] = { title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "" }
WordHunterWoW_QuestEN[9327] = { title = "The Forsaken", description = "I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren. He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", objectives = "" }
WordHunterWoW_QuestEN[9328] = { title = "Hero of the Sin'dorei", description = "This is the beginning of a new chapter in the history of our race, {name}.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", objectives = "" }
WordHunterWoW_QuestEN[9329] = { title = "The Forsaken", description = "I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren.  He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", objectives = "" }
WordHunterWoW_QuestEN[9330] = { title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "" }
WordHunterWoW_QuestEN[9331] = { title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "" }
WordHunterWoW_QuestEN[9332] = { title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "" }
WordHunterWoW_QuestEN[9339] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "" }
WordHunterWoW_QuestEN[9340] = { title = "The Great Fissure", description = "We're dangerously close to becoming fenced in by Alliance forces.  With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes.\n\nI've given it some thought and have arrived at a solution.  We're to establish a secret path through the Great Fissure.\n\nYes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us.  I want you to go and kill a good number of them.  They shall learn fear.", objectives = "" }
WordHunterWoW_QuestEN[9345] = { title = "Preparing the Salve", description = "Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me!\n\nI managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here.\nNow, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.", objectives = "" }
WordHunterWoW_QuestEN[9349] = { title = "Ravager Egg Roundup", description = "I'm starving!\n\nThere's irony in that, wouldn't you say?  A starving cook?\n\n<Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.>\n\nAccording to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest.  It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!\n\nI could cook up quite a feast if only someone were brave enough to go down there and get me some!", objectives = "" }
WordHunterWoW_QuestEN[9351] = { title = "Voidwalkers Gone Wild", description = "Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here!\n\nTo the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries.\n\nIf you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!", objectives = "" }
WordHunterWoW_QuestEN[9352] = { title = "Darnassian Intrusions", description = "Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings.\n\nThough most reports are unfounded, one recent incident demands further investigation.  The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant.\n\nTravel there and deal with anyone that looks suspicious.  Report back to Ley-Keeper Velania, who watches over the sanctum.", objectives = "" }
WordHunterWoW_QuestEN[9355] = { title = "A Job for an Intelligent Man", description = "Well met, {class}. Now that reinforcements are finally arriving, we can recapture some semblance of a normal life.\n\nOne of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area.\n\nIf you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.", objectives = "" }
WordHunterWoW_QuestEN[9356] = { title = "Smooth as Butter", description = "Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it!\n\nTake a look at the wreckage over there. He calls it a \"rough\" landing.\n\nSure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often!\n\nI think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.", objectives = "" }
WordHunterWoW_QuestEN[9358] = { title = "Ranger Sareyn", description = "Don't take the safety of this village for granted.  We're under siege by the Scourge on the east and the Wretched to the west.\n\nRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar.  Follow the road eastwards out of town and see if you can lend her a hand.", objectives = "" }
WordHunterWoW_QuestEN[9359] = { title = "Farstrider Retreat", description = "Your help in subduing the Wretched has been invaluable.  The Farstriders would surely have use for someone like you in their fight against the Amani trolls.\n\nLook for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.", objectives = "" }
WordHunterWoW_QuestEN[9360] = { title = "Amani Invasion", description = "Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village.\n\nYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.", objectives = "" }
WordHunterWoW_QuestEN[9361] = { title = "Helboar, the Other White Meat", description = "Those eggs are superb, but what do you say we kick it up another notch?\n\nA side of bacon would round out the meal perfectly and I know just where to get it.\n\nThis place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck!\n\n<Legassi rummages around in his pack and produces a flask.>\n\nThis wasn't made for use on pork, but cooking is as much about improvisation as anything else!", objectives = "" }
WordHunterWoW_QuestEN[9362] = { title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", objectives = "" }
WordHunterWoW_QuestEN[9363] = { title = "Warning Fairbreeze Village", description = "Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans.  Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack.  Tell Degolien I will send him reinforcements as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[9364] = { title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", objectives = "" }
WordHunterWoW_QuestEN[9365] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "" }
WordHunterWoW_QuestEN[9366] = { title = "In Need of Felblood", description = "Northeast of here lie the Pools of Aggonar.  Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them.\n\nThat blood, though old and diluted, still possesses tremendous power.  Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood.  Slay them and retrieve as much felblood as you can.  I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[9367] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "" }
WordHunterWoW_QuestEN[9368] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "" }
WordHunterWoW_QuestEN[9369] = { title = "Replenishing the Healing Crystals", description = "We are the draenei.  Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but mostly in the northwest.", objectives = "" }
WordHunterWoW_QuestEN[9370] = { title = "The Cleansing Must Be Stopped", description = "Our scouts captured a draenei paladin at the Pools of Aggonar.  He was to take part in a cleansing ritual to purify the pools.  We must stop the draenei from succeeding or we will lose our supply of felblood!\n\nHe was carrying this signaling gem, looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety.  Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei.\n\nI suggest that you take a friend or two along.", objectives = "" }
WordHunterWoW_QuestEN[9371] = { title = "Botanist Taerix", description = "{name}, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.", objectives = "" }
WordHunterWoW_QuestEN[9372] = { title = "Demonic Contamination", description = "Welcome to the Cenarion Post, {class}. We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places.\n\nThe Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.", objectives = "" }
WordHunterWoW_QuestEN[9373] = { title = "Missing Missive", description = "Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out.\n\nThe only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.", objectives = "" }
WordHunterWoW_QuestEN[9374] = { title = "Arelion's Journal", description = "My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland.  He spent much of his time studying slimes, of all things!\n\nHe went missing in there a few days ago.  They say he's dead and there's nothing I can do about it.\n\nOne thing I can do is try to ensure that his research doesn't die with him.  Go northeast to the pools and look for his journal.  He always carried it inside a brown knapsack.", objectives = "" }
WordHunterWoW_QuestEN[9375] = { title = "The Road to Falcon Watch", description = "<The battered blood elf's face displays relief at your presence.>\n\nPlease, {class}, get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings.\n\nI was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles.\n\nAs I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!", objectives = "" }
WordHunterWoW_QuestEN[9376] = { title = "A Pilgrim's Plight", description = "That wounded pilgrim seems to be shouting something about a pack.\n\nWhen you encountered her, did you see a pack nearby? Hmm...\n\nShe must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers.\n\nIf she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life.\n\nGo to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.", objectives = "" }
WordHunterWoW_QuestEN[9377] = { title = "Thirsting For Power", description = "Falcon Watch serves as a stop for pilgrims on their long journey into Outland. Although we are an early stop on the way, many of the pilgrims reach us exhausted and wracked by their addictions.\n\nIn a world such as this, many find it necessary to relearn mastery of their magical addiction. Food and drink help, {class}, but magical energy is their greatest need. The remains of Outland's voidwalkers provide a potent source of energy, but they grow rare and can only be found in the Warp Fields to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[9381] = { title = "Trueflight Arrows", description = "With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time.\n\nI could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.", objectives = "" }
WordHunterWoW_QuestEN[9383] = { title = "An Ambitious Plan", description = "The blood elves epitomize the irresponsible use of magic, {class}. They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics.\n\nI've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.", objectives = "" }
WordHunterWoW_QuestEN[9385] = { title = "Rampaging Ravagers", description = "So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot.  Little did we know how close we were to the quillfang ravagers.\n\nThey are relentless predators and have made any sort of work on our part impossible.  There's a bit of coin in it for you if you can deal with them for us.  Do you feel up to it?", objectives = "" }
WordHunterWoW_QuestEN[9387] = { title = "Source of the Corruption", description = "Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light.  What corruption caused their great race to devolve into the Broken and Lost Ones?\n\nI've heard a theory that exposure to fel energies is what caused the mutation.  I would like to put that theory to the test.\n\nNorthwest of here lie the Ruins of Sha'naar.  There you will find lowly Broken commanded by Illidari taskmasters.  Bring me demonic essences from the taskmasters so that I can test them on this draenei.", objectives = "" }
WordHunterWoW_QuestEN[9388] = { title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.", objectives = "" }
WordHunterWoW_QuestEN[9389] = { title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", objectives = "" }
WordHunterWoW_QuestEN[9390] = { title = "In Search of Sedai", description = "Hear my plight, {class}.  My brother, Sedai, left long ago to contact the orcs of Mag'har Post.  Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them.\n\nHe's been missing for days and I fear for the worst.\n\nWould you set my mind to rest and look for him?  Sedai must be somewhere nearby to the east.", objectives = "" }
WordHunterWoW_QuestEN[9391] = { title = "Marking the Path", description = "With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims.  Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east.\n\nLight the three beacons and return to me.  Be warned that the beacons will attract any nearby rock flayers when you first light them.", objectives = "" }
WordHunterWoW_QuestEN[9394] = { title = "Where's Wyllithen?", description = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did.  I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about.\n\nWill you find him for me, {class}, and make sure that he's alright?", objectives = "" }
WordHunterWoW_QuestEN[9395] = { title = "Saltheril's Haven", description = "I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party!  Do I look like a party planner?!  Between you and me, that fool and his sycophants are living in denial that we're under attack here!\n\nSome of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas!  {class}, would you please head over to Saltheril's Haven and see if you can shut him up?  It's just down the road to the west.", objectives = "" }
WordHunterWoW_QuestEN[9396] = { title = "Magic of the Arakkoa", description = "Outland holds many secrets, {name}.  It's only a matter of time before we uncover them all.\n\nThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal'esh, south of here.  Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[9397] = { title = "Birds of a Feather", description = "The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri.\n\nI've managed to capture a young male and they appear to be trainable.  The females are much rarer, but if I had one I could attempt to breed them.  She has to be young, though... a hatchling.  An older wild bird wouldn't survive in captivity.\n\nTake this cage and travel south, to the Den of Haal'esh.  Search the nests for eggs that are ready to hatch.  If you bring me back a female hatchling, I'll reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[9398] = { title = "Deadly Predators", description = "The Broken that live in Outland have endured endless violence.  It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land.\n\nUnfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey.  Go there and thin the rock flayer population, so that our kin might have a chance.", objectives = "" }
WordHunterWoW_QuestEN[9399] = { title = "Cruel Taskmasters", description = "You probably think most Broken are evil, don't you?  In reality many just lack guidance.\n\nBefore I met the Omenai, I too was lost.\n\nOur minds suffered terrible pain from the orcs' demonic magic.  We are easily confused and taken advantage of.\n\nDemons allied with Illidan raid Hellfire daily and capture our kind as slaves.  With the Omenai we now have hope.  Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!", objectives = "" }
WordHunterWoW_QuestEN[9400] = { title = "The Assassin", description = "{name}, we recently uncovered a plot to assassinate our envoy to Falcon Watch.  Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush.\n\nOur scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel.  Go there and slay this assassin.  Show the fel orcs we're not to be trifled with!", objectives = "" }
WordHunterWoW_QuestEN[9401] = { title = "A Strange Weapon", description = "You pull the stone axe out of the body to examine it more closely.  There's something unusual about the craftsmanship of the weapon.\n\nIts origin appears orcish, though the materials aren't like anything you've seen before.  Nazgrel might be interested in seeing the weapon.", objectives = "" }
WordHunterWoW_QuestEN[9402] = { title = "Fetch!", description = "So... {name} is it?  Don't be flattered I know your name, one of my students has been fawning over you and won't shut up.\n\nHmm... if you'd like to impress her, why don't you do something for me?  There's an azure phial at the bottom of the pond behind me.  Dive in, retrieve it, and bring it here.", objectives = "" }
WordHunterWoW_QuestEN[9403] = { title = "The Purest Water", description = "Now that you've learned a little lesson, I'll offer you something more substantial.  It concerns your ability to defend yourself in close combat.  Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared.\n\nI can assist you in creating a staff befitting a mage of your learning.  Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls.  Just follow the river southeast from here.", objectives = "" }
WordHunterWoW_QuestEN[9404] = { title = "Recently Living", description = "You may have noticed the walking trees near Elrendar Falls.  As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me.\n\nUnfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.", objectives = "" }
WordHunterWoW_QuestEN[9405] = { title = "The Warchief's Mandate", description = "As you know, the warchief put his power behind this expedition for one reason.  This is the world we came from.  This is where our roots lie.\n\nThis journey means different things to orcs and blood elves.  To them it's a search for the promised land.  To us it's more like returning home.\n\nWhoever made this axe is familiar with the old ways and we must contact them.  This is too important for us to use ordinary tracking methods.  Show the weapon to Far Seer Regulkut; she will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[9406] = { title = "The Mag'har", description = "This news you bring from beyond the Dark Portal...  you want us to believe the son of Durotan ruled over the lands beyond it... free from any demonic taint?  And that now his people have returned to this world?\n\nI hope for your sake that this isn't some manner of joke, {class}.  What this means to my people... cannot be described.  I must send word to Nagrand at once!  Hellscream must hear about this.\n\nTake this letter back to your leader in Thrallmar.  Tell him the Mag'har welcome them!", objectives = "" }
WordHunterWoW_QuestEN[9407] = { title = "Burning Crusade: Through the Dark Portal", description = "For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.\n\nAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!\n\nNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, {name}.\n\nIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...\n", objectives = "" }
WordHunterWoW_QuestEN[9408] = { title = "Forgotten Heroes", description = "While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.\n\nI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.\n\nInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, {class}. He has already met and addressed all of our soldiers. He will surely want to meet you.", objectives = "" }
WordHunterWoW_QuestEN[9409] = { title = "Urgent Delivery!", description = "Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun, our priest.  You'll find him tending to our wounded inside the central chamber of the ship.", objectives = "" }
WordHunterWoW_QuestEN[9410] = { title = "A Spirit Guide", description = "Even our best tracking wolves' senses can fail them, {name}.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence.\n\nGo now, {class}, take this totem with you and use it at the location you found the stone axe.", objectives = "" }
WordHunterWoW_QuestEN[9415] = { title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", objectives = "" }
WordHunterWoW_QuestEN[9416] = { title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", objectives = "" }
WordHunterWoW_QuestEN[9417] = { title = "The Arakkoa Threat", description = "The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. \n\nLately they've taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.\n\nSo what do you say you give us a hand in this one assignment?  You'll find the Den of Haal'esh to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[9418] = { title = "Avruu's Orb", description = "<As you hold the orb closer to you, you hear a voice address you.>\n\nI sense you're not of the arakkoa, so I will attempt to barter for my freedom.  My name is Aeranas. I once ruled over the eastern winds.  The Haal'eshi mage, Avruu, trapped me inside this orb.\n\nFind the altar the arakkoa used to enslave me.  It is hidden to the southeast of the arakkoa's den.  Approach it with the orb and give it to me once I'm free.  In exchange for my liberty I'll reward you with powerful treasure!", objectives = "" }
WordHunterWoW_QuestEN[9420] = { title = "The Finest Down", description = "The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri.  Their feathers would fetch a bundle at the trading posts back in Azeroth.  Just think of all the ale I could buy then!\n\nTell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat.  What do you say?  You'll never find a hat like this one!  Do we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[9423] = { title = "Return to Obadei", description = "With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.", objectives = "" }
WordHunterWoW_QuestEN[9424] = { title = "Makuru's Vengeance", description = "Sedai was like a brother to Makuru.   We owe him our lives and more!  They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones!\n\nMakuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai.  \n\nI've seen the brown orc Mag'har grunts before, up in the hills to the northeast.  They hate us!  They don't deserve our mercy!  Go, avenge Sedai!  Bring me their ancestral beads as proof!", objectives = "" }
WordHunterWoW_QuestEN[9426] = { title = "The Pools of Aggonar", description = "Much has changed since the days when we called this land Draenor.  Parts of the land have been forever changed by the demons' taint.\n\nOne such place is known as the Pools of Aggonar.  It was once the location of our people's sacred springs.  The blood of the demon Aggonar fouled the very essence of the holy waters.  This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools.  Travel east of here and slay the Terrorfiends and slimes that wander the pools.", objectives = "" }
WordHunterWoW_QuestEN[9427] = { title = "Cleansing the Waters", description = "I must ask that you finish what we've set in motion.  Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse.\n\nYou will find the demon's bones at the northern end of the pools.  Beware, I sense that Aggonar's essence has not quite left this world.", objectives = "" }
WordHunterWoW_QuestEN[9430] = { title = "Sha'naar Relics", description = "As I've told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you.\n\nTravel southwest to the Ruins of Sha'naar and salvage any relics you find.  If fate wills it you will find what we need.\n\nThe meaning of my request might not be immediately apparent.  Have faith though, {name}.  Clarity comes to those with patience.", objectives = "" }
WordHunterWoW_QuestEN[9436] = { title = "Bloodscalp Insight", description = "Well met, {class}. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests.\n\nTheir magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.", objectives = "" }
WordHunterWoW_QuestEN[9437] = { title = "Twilight of the Dawn Runner", description = "The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story.\n\nI could use the help of a reliable {race} in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.", objectives = "" }
WordHunterWoW_QuestEN[9442] = { title = "A Debilitating Sickness", description = "It is good that you've offered to aid us, {name}.  Our grunts have fallen sick from drinking contaminated water and I'm missing an ingredient to produce a healing salve.  I'm in need of a rare mushroom called drycap.\n\nOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.\n\nBe extremely careful if you choose to seek it.", objectives = "" }
WordHunterWoW_QuestEN[9447] = { title = "Administering the Salve", description = "I've prepared a simple salve that should restore our grunts' strength with the herbs you brought me.  Take it and administer it to any debilitated grunts you see in the vicinity.  Return to me when you're done.", objectives = "" }
WordHunterWoW_QuestEN[9452] = { title = "Red Snapper - Very Tasty!", description = "I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!\n\nUse this fishing net near schools of red snapper, found in the Crystalbrook river to the east, to catch the fish.\n\nWhat do you say? Remember to return the net when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[9453] = { title = "Find Acteon!", description = "You did a wonderful job, {name}. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?\n\nHe shouldn't be hard to find as he is awaiting this catch.", objectives = "" }
WordHunterWoW_QuestEN[9454] = { title = "The Great Moongraze Hunt", description = "You're starting to make a name for yourself, {name}. How about trying your hand at hunting?\n\nBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.\n\nIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.\n\nYou will find them grazing south of Azure Watch. Watch out for their horns!", objectives = "" }
WordHunterWoW_QuestEN[9455] = { title = "Strange Findings", description = "The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region.\n\nTake the crystal back to Azure Watch. The exarch will surely want to know about this discovery.", objectives = "" }
WordHunterWoW_QuestEN[9456] = { title = "Nightstalker Clean Up, Isle 2...", description = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.\n\nIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", objectives = "" }
WordHunterWoW_QuestEN[9457] = { title = "An Unusual Patron", description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.\n\nOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.", objectives = "" }
WordHunterWoW_QuestEN[9463] = { title = "Medicinal Purpose", description = "I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply.\n\nOur delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her.\n\nYou will find root trappers both south and east of Azure Watch.", objectives = "" }
WordHunterWoW_QuestEN[9466] = { title = "WANTED: Blacktalon the Savage", description = "By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage.\n\nBlacktalon was last sighted inside a cave in the Great Fissure.  Individuals seeking the reward are to present the creature's claws as proof of the deed.", objectives = "" }
WordHunterWoW_QuestEN[9472] = { title = "Arelion's Mistress", description = "With all the important matters at hand Arelion still found time in his schedule to see a mistress!\n\nIt's all becoming perfectly clear.  Viera Sunwhisper, that filthy wench... we'll show her to never cross a magistrix again.\n\nTake this scroll and find Viera.  Find a way to lure her away from town and use the scroll on her.\n\nArelion mentioned she couldn't resist a particular wine harvested by the cenarion druids.  You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.", objectives = "" }
WordHunterWoW_QuestEN[9473] = { title = "An Alternative Alternative", description = "The girl is too far gone for mere ointments to be effective. There may be another way...\n\nThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.\n\nYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!\n\nAnd {name}, be wary of the root threshers of the region as they consume snapdragon for sustenance.", objectives = "" }
WordHunterWoW_QuestEN[9487] = { title = "Arcane Reavers", description = "Arcane reavers are magical creations of brute strength.  They are heavily armored and deliver stunning blows.  You, however, can bypass their defenses and avoid their attacks.  Your spellcraft is not without many advantages, {name}.\n\nTravel to Dawnstar Spire and blast apart the arcane reavers.  From their remains, collect the crystallized fragments of magical energy and return to me.  Dawnstar Spire is found to the east, across the lake.", objectives = "" }
WordHunterWoW_QuestEN[9488] = { title = "A Simple Robe", description = "The arcane fragments you collected will do nicely.\n\nNicely for what, you ask?  For making a splendid robe fit for a {class} like yourself!\n\nAll we need now is some linen cloth and a spindleweb silk gland.  You can find the silk gland from any spindleweb spider, preferably after killing them.", objectives = "" }
WordHunterWoW_QuestEN[9490] = { title = "The Rock Flayer Matriarch", description = "Rock flayers are mean, nasty, violent creatures.  But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage.\n\nMy cousin got eaten by her and it wasn't pretty.  I swore that one day Blacktalon would pay for that.  You bring back proof of that monster's death and I will give you my life's savings.  Deal?\n\nYou'll find her inside a cave in the Great Fissure.  Good luck!", objectives = "" }
WordHunterWoW_QuestEN[9498] = { title = "Falcon Watch", description = "My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, {name}.\n\nIf you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you.  He will see to it that you're given tasks worthy of someone of your caliber.", objectives = "" }
WordHunterWoW_QuestEN[9499] = { title = "Falcon Watch", description = "What are you still doing here, {name}?  Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow blood elves and away from all this... smell.  You'll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn'ren; he will take care of you.\n\nThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.", objectives = "" }
WordHunterWoW_QuestEN[9505] = { title = "The Prophecy of Velen", description = "The Prophet spoke of this day: That on this island, in this new world, our allies would find us.\n\n\"We will be tested. They will ask that we pay for the sins of our fathers...\"\n\nAt the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here.\n\nVenture south. It is there that we found this being. Find its kin and tell them of our people.", objectives = "" }
WordHunterWoW_QuestEN[9506] = { title = "A Small Start", description = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships.\n\nLast night, while most of the ship's crew was asleep below deck, they struck!\n\nStranger still, they took our navigation gear and jumped ship!\n\nThey disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.", objectives = "" }
WordHunterWoW_QuestEN[9512] = { title = "Cookie's Jumbo Gumbo", description = "The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out?\n\nIf I serve the crew chicken for dinner again, I'll be sent to the brig fer sure.\n\nI noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya.\n\nHelp a reformed pirate out?", objectives = "" }
WordHunterWoW_QuestEN[9513] = { title = "Reclaiming the Ruins", description = "While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time.\n\nTo the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands.\n\nYou have shown yourself a capable {class}. Honor my people and cleanse the ruins of their unwelcome inhabitants.", objectives = "" }
WordHunterWoW_QuestEN[9514] = { title = "Rune Covered Tablet", description = "You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.", objectives = "" }
WordHunterWoW_QuestEN[9515] = { title = "Warlord Sriss'tiz", description = "A naga invasion would be disastrous, {name}. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west.\n\nFind Warlord Sriss'tiz and put an end to his reign.", objectives = "" }
WordHunterWoW_QuestEN[9523] = { title = "Precious and Fragile Things Need Special Handling", description = "The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\"\n\nNow what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!", objectives = "" }
WordHunterWoW_QuestEN[9527] = { title = "All That Remains", description = "We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.\n\nI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.\n\nWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.\n\nI care not for vengeance, {name}. I only ask that their remains be returned to me for proper burial.", objectives = "" }
WordHunterWoW_QuestEN[9528] = { title = "A Cry For Help", description = "My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?", objectives = "" }
WordHunterWoW_QuestEN[9530] = { title = "I've Got a Plant", description = "I've wondered about this for some time now, but this proves it to be true.\n\nThere is a traitor among us.\n\nThe plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted.\n\nIf this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.", objectives = "" }
WordHunterWoW_QuestEN[9531] = { title = "Tree's Company", description = "According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, {name}.\n\nRemember the tree and leaves? You're going to wear them! It's a perfect disguise.\n\nGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.", objectives = "" }
WordHunterWoW_QuestEN[9537] = { title = "Show Gnomercy", description = "Spark must be brought to justice!\n\nI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!\n\nIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?\n\nAnd {name}, use force if you have to...\n", objectives = "" }
WordHunterWoW_QuestEN[9538] = { title = "Learning the Language", description = "I think I've cracked it, {name}!\n\n<Aurren points to the totem.>\n\nAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.\n\nI've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.\n\nSpeak to Arugoo when you return an educated {race}!", objectives = "" }
WordHunterWoW_QuestEN[9539] = { title = "Totem of Coo", description = "You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[9540] = { title = "Totem of Tikti", description = "You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.", objectives = "" }
WordHunterWoW_QuestEN[9541] = { title = "Totem of Yor", description = "The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.", objectives = "" }
WordHunterWoW_QuestEN[9542] = { title = "Totem of Vark", description = "You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue.\n\nThe markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.", objectives = "" }
WordHunterWoW_QuestEN[9543] = { title = "Atonement", description = "Our history with the orcs is one of constant conflict, {name}.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.\n\nYet, this retaliation... it's not what Sedai would've wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.", objectives = "" }
WordHunterWoW_QuestEN[9544] = { title = "The Prophecy of Akida", description = "The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine.\n\nAmidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe.\n\nSlay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives. Return to Arugoo of the Stillpine when you have freed them all!\n", objectives = "" }
WordHunterWoW_QuestEN[9545] = { title = "The Seer's Relic", description = "The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.\n\nTake this relic with you to where you found Sedai.  See not with your eyes, {name}, but with your mind.", objectives = "" }
WordHunterWoW_QuestEN[9548] = { title = "Pilfered Equipment", description = "Shh! Keep your voice down and don't call attention to me.\n\nIf the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data.\n\nWhile I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?", objectives = "" }
WordHunterWoW_QuestEN[9549] = { title = "Artifacts of the Blacksilt", description = "My observations and writings about the Blacksilt murlocs are quite illuminating, {name}, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills.\n\nThe problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.", objectives = "" }
WordHunterWoW_QuestEN[9550] = { title = "A Map to Where?", description = "The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. \n\nIf the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.", objectives = "" }
WordHunterWoW_QuestEN[9557] = { title = "Deciphering the Book", description = "Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl.\n\nRemembering Anchorite Paetheus's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.", objectives = "" }
WordHunterWoW_QuestEN[9558] = { title = "The Longbeards", description = "We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them.\n\nThey were brothers; Gremni Longbeard was the oldest.\n\nI'm a little worried about them.  Those crazy dwarves packed more ale than food or ammunition!  Maybe you can go check up on them?\n\nThe arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure.  They set up camp northwest of there, south of Dustquill Ravine.", objectives = "" }
WordHunterWoW_QuestEN[9559] = { title = "Stillpine Hold", description = "Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge.\n\nGo now, High Chief Stillpine awaits your arrival.", objectives = "" }
WordHunterWoW_QuestEN[9560] = { title = "Beasts of the Apocalypse!", description = "My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent?\n\nIf you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power!\n\nFind them to the east, beyond the road.", objectives = "" }
WordHunterWoW_QuestEN[9561] = { title = "Nolkai's Words", description = "The translation is ready now, {name}.\n\n<Anchorite Paetheus points out a block of text at the end of his translation.>\n\n'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'", objectives = "" }
WordHunterWoW_QuestEN[9562] = { title = "Murlocs... Why Here? Why Now?", description = "These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised.\n\nWhile our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs!\n\nAnd if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes... ", objectives = "" }
WordHunterWoW_QuestEN[9563] = { title = "Gaining Mirren's Trust", description = "So you want to gain our trust?  I don't trust many people these days.\n\nWe lost one of our own not long ago to the arakkoa.  It's got me a bit on edge.\n\nTell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter... yes, that sounds rather good about now... I'll have a deal to offer you then.\n\nBernie at Nethergarde Keep keeps the bitter in stock.", objectives = "" }
WordHunterWoW_QuestEN[9564] = { title = "Gurf's Dignity", description = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.", objectives = "" }
WordHunterWoW_QuestEN[9565] = { title = "Search Stillpine Hold", description = "As High Chief, my immediate concern is the root of the corruption in Stillpine Hold.\n\nWhy did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold?\n\nPerhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.", objectives = "" }
WordHunterWoW_QuestEN[9566] = { title = "Blood Crystals", description = "On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave.\n\nThis may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.\n", objectives = "" }
WordHunterWoW_QuestEN[9567] = { title = "Know Thine Enemy", description = "It's good to see another new face here in Blood Watch, {class}. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home.\n\nThe Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash.\n\nWe must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.", objectives = "" }
WordHunterWoW_QuestEN[9569] = { title = "Containing the Threat", description = "Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands.\n\nToo long have the draenei fled in the wake of the Legion and its minions, {name}. Wherever they have found us, they have shown no mercy.\n\nWe must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!", objectives = "" }
WordHunterWoW_QuestEN[9570] = { title = "The Kurken is Lurkin'", description = "After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.\n\nIn my visions, I have seen one defeat the Kurken. The one must be you, {name}. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.\n", objectives = "" }
WordHunterWoW_QuestEN[9571] = { title = "The Kurken's Hide", description = "Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice.\n", objectives = "" }
WordHunterWoW_QuestEN[9573] = { title = "Chieftain Oomooroo", description = "I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike!\n\nFind Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.", objectives = "" }
WordHunterWoW_QuestEN[9574] = { title = "Victims of Corruption", description = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife.\n\nBefore I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.", objectives = "" }
WordHunterWoW_QuestEN[9576] = { title = "Cruelfin's Necklace", description = "Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness.\n\nYou're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.", objectives = "" }
WordHunterWoW_QuestEN[9578] = { title = "Searching for Galaen", description = "Do you think often of your family, {name}? There were a number of families aboard the Exodar, but I've heard of very few being reunited.\n\nI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves!\n\nI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.", objectives = "" }
WordHunterWoW_QuestEN[9579] = { title = "Galaen's Fate", description = "You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables.\n\nThe blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet.\n\nAlthough her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.", objectives = "" }
WordHunterWoW_QuestEN[9580] = { title = "The Bear Necessities", description = "As I'm sure you've seen in your time on Bloodmyst Isle, very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use.\n\nWith so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?", objectives = "" }
WordHunterWoW_QuestEN[9581] = { title = "Learning from the Crystals", description = "Welcome to Blood Watch, {class}. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar.\n\nThe problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island.\n\nThe first sample I need must come from the ravager infested ship debris south of the town and across the bridge.", objectives = "" }
WordHunterWoW_QuestEN[9582] = { title = "Strength of One", description = "When the ship crashed, our menagerie was scattered on the northeast beaches of this isle.  I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager.  The creature is little armored but resistant to most magic.  It must be killed by a simple blade.\n\nTake this key and release the creature from both its prison and its pain.  We cannot afford to have it escape and cause even more damage to the ecology than we already have.", objectives = "" }
WordHunterWoW_QuestEN[9584] = { title = "The Second Sample", description = "Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar.\n\nThe next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.", objectives = "" }
WordHunterWoW_QuestEN[9585] = { title = "The Final Sample", description = "There's just one sample remaining before I can send this set of crystals to the Exodar, {name}. The final sample must come from the satyr stronghold of Axxarien to the northwest.\n\nI'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.", objectives = "" }
WordHunterWoW_QuestEN[9594] = { title = "Signs of the Legion", description = "The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it.\n\nSuch armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei.\n\nTake action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia. ", objectives = "" }
WordHunterWoW_QuestEN[9595] = { title = "Control", description = "You have chosen the path of the {class}, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds.\n\nTo fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith. Defeat it.\n\nWhen you have finished, seek out Bati at the Vault of Lights in the Exodar.", objectives = "" }
WordHunterWoW_QuestEN[9602] = { title = "Deliver Them From Evil...", description = "You must get this information to your people, {name}. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue.\n\nTake the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.", objectives = "" }
WordHunterWoW_QuestEN[9603] = { title = "Beds, Bandages, and Beyond", description = "Welcome to Azure Watch, {class}. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing.\n\nWe've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.", objectives = "" }
WordHunterWoW_QuestEN[9604] = { title = "On the Wings of a Hippogryph", description = "For a small fee, you can rent one of my hippogryphs to fly you to the Exodar.\n\nTaking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.", objectives = "" }
WordHunterWoW_QuestEN[9605] = { title = "Hippogryph Master Stephanos", description = "Here's the box, {name}. That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive.\n\nWhen you're ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.", objectives = "" }
WordHunterWoW_QuestEN[9606] = { title = "Return to Caregiver Chellan", description = "If I remember correctly, Azure Watch's hippogryph master is Zaldaan.  If you've spoken to him before, then you can take one of my hippogryphs to him.\n\nThat's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there.\n\nSince you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to Azure Watch with the caregiver's supplies.", objectives = "" }
WordHunterWoW_QuestEN[9612] = { title = "A Hearty Thanks!", description = "You saved my life, {name}! Thank you so much! That beast would have torn me to shreds if it weren't for you.\n\nIf you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!", objectives = "" }
WordHunterWoW_QuestEN[9616] = { title = "Bandits!", description = "This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency.\n\nThey've put a hit out on draenei! You must inform the exarch.", objectives = "" }
WordHunterWoW_QuestEN[9620] = { title = "The Missing Survey Team", description = "As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back.\n\nI worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, {name}, and lend them any assistance they require to return with their survey data.", objectives = "" }
WordHunterWoW_QuestEN[9621] = { title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[9622] = { title = "Warn Your People", description = "The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine.\n\nBut I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen.\n\nReturn to your leaders and tell them of what you have seen here.\n\nAnd Promised One, should you ever require the aid of Stillpine, you have merely to ask.", objectives = "" }
WordHunterWoW_QuestEN[9623] = { title = "Coming of Age", description = "You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a {race} like you. \n\nReport to Torallius the Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.", objectives = "" }
WordHunterWoW_QuestEN[9624] = { title = "A Favorite Treat", description = "I've made a wonderful discovery, {class}. On the uncorrupted part of the island grows a remarkable fruit called the sand pear. They're found near the bottoms of the trees.\n\nI've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!", objectives = "" }
WordHunterWoW_QuestEN[9625] = { title = "Elekks Are Serious Business", description = "Is he crazy? Entrusting something like this to some no-named {race} youngling!\n\nJust remember this kid: You'll never make it as a Hand of Argus! You don't have the guts!\n\nI guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it forks, just keep on going north.", objectives = "" }
WordHunterWoW_QuestEN[9626] = { title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", objectives = "" }
WordHunterWoW_QuestEN[9627] = { title = "Allegiance to the Horde", description = "Your people suffered a great betrayal by the Alliance. You succeeded in fighting off the Darnassian attacks and the spies from Ironforge. Now you defeated a powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in question.\n\nIt is clear now that we need each other. Return to Lor'themar. Tell him I have heard your message and accept. \n\n<Saurfang crushes the letter inside his palm.> \n\nWelcome to the Horde, elf.", objectives = "" }
WordHunterWoW_QuestEN[9628] = { title = "Salvaging the Data", description = "It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga.\n\nYou know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.", objectives = "" }
WordHunterWoW_QuestEN[9629] = { title = "Catch and Release", description = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization.\n\nI have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.", objectives = "" }
WordHunterWoW_QuestEN[9632] = { title = "Newfound Allies", description = "Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, {class}, but our enemies are many and our resources few.\n\nOur weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.", objectives = "" }
WordHunterWoW_QuestEN[9634] = { title = "Alien Predators", description = "One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager.\n\nSome of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands.\n\nYou'll find these ravagers to the west of Kessel's Crossing, near the coast.", objectives = "" }
WordHunterWoW_QuestEN[9635] = { title = "The Zapthrottle Mote Extractor!", description = "The swamp gas is truly amazing, and can be very useful, mon!  But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor.\n\nNow, I could just give you the schematics, but I'll need something in return first.  How about some spare parts?  Last time I checked, there were plenty lying around near the broken steam pump at the Dead Mire, far to the northeast.\n\nI heard that the withered giants spread the pieces all over that dried-out lake bed.", objectives = "" }
WordHunterWoW_QuestEN[9636] = { title = "The Zapthrottle Mote Extractor!", description = "Have you seen the swamp gas?  Isn't it just shiny?\n\nIt takes a Zapthrottle Mote Extractor to suck 'em dry though.  I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here.\n\nLast time I checked, there were plenty of parts lying around near the steam pump at the Dead Mire to the northeast.  I think the withered giants broke the pump out there.\n\nShall we help each other out?", objectives = "" }
WordHunterWoW_QuestEN[9641] = { title = "Irradiated Crystal Shards", description = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle, corrupting the water and the landscape.\n\nWe've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.", objectives = "" }
WordHunterWoW_QuestEN[9643] = { title = "Constrictor Vines", description = "A good woodsman makes use of every available resource, {class}. Even the most bizarre creatures possess attributes we can use to our advantage.\n\nWith Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.", objectives = "" }
WordHunterWoW_QuestEN[9646] = { title = "WANTED: Deathclaw", description = "By order of Harbinger Mikolaas: A bounty to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise.\n\nDeathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.", objectives = "" }
WordHunterWoW_QuestEN[9647] = { title = "Culling the Flutterers", description = "When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination.\n\nIt has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.", objectives = "" }
WordHunterWoW_QuestEN[9648] = { title = "Maatparm Mushroom Menagerie", description = "Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers!\n\nWhat would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus. They are each unique to various regions in Bloodmyst. Bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[9649] = { title = "Ysera's Tears", description = "Good to see you again, {name}! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?\n\nTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.\n", objectives = "" }
WordHunterWoW_QuestEN[9663] = { title = "The Kessel Run", description = "You're just in time, {name}. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.\n\nWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.\n\nTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.", objectives = "" }
WordHunterWoW_QuestEN[9666] = { title = "Declaration of Power", description = "Have you seen the serpent men? The ones that call themselves naga?\n\n<Kessel spits.>\n\nThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?\n\nI need you to deliver a message to their leadership, {name}. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.\n\nLet them know fear whenever they should see our standard!", objectives = "" }
WordHunterWoW_QuestEN[9667] = { title = "Saving Princess Stillpine", description = "Help me, {name}! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!\n\nHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!\n\nMy father will richly reward you if you can save me!", objectives = "" }
WordHunterWoW_QuestEN[9668] = { title = "Report to Exarch Admetius", description = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, {class}.\n\nReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.\n\nAnd remember this, {name}: Honorable people do not always perform honorably. Sometimes they cannot.\n\nYou will find Blood Watch just up this road, to the north.", objectives = "" }
WordHunterWoW_QuestEN[9669] = { title = "The Missing Expedition", description = "About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive.\n\nI managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh.", objectives = "" }
WordHunterWoW_QuestEN[9670] = { title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!\n", objectives = "" }
WordHunterWoW_QuestEN[9671] = { title = "Urgent Delivery", description = "", objectives = "" }
WordHunterWoW_QuestEN[9672] = { title = "The Bloodcurse Legacy", description = "Dear friend,\n\nMy hand trembles as I ink this letter. I pray that it reaches you in time.\n\nLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base?\n\nRegards,\n\nAdmiral Odesyus\n", objectives = "" }
WordHunterWoW_QuestEN[9674] = { title = "The Bloodcursed Naga", description = "They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga.\n\nObedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now.\n\nThe first order of business is to remove the bloodcursed naga from the reef.", objectives = "" }
WordHunterWoW_QuestEN[9682] = { title = "The Hopeless Ones...", description = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse.\n\nIt is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me.\n\nTheir souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.", objectives = "" }
WordHunterWoW_QuestEN[9683] = { title = "Ending the Bloodcurse", description = "To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.\n\nSlay Atoph and return to me!", objectives = "" }
WordHunterWoW_QuestEN[9687] = { title = "Restoring Sanctity", description = "Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege.\n\nTo the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones.", objectives = "" }
WordHunterWoW_QuestEN[9688] = { title = "Into the Dream", description = "The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream.\n\nRecovering the bones of the fallen has settled them somewhat but you must take further action.\n\nDestroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!", objectives = "" }
WordHunterWoW_QuestEN[9689] = { title = "Razormaw", description = "Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death.\n\nTake the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.", objectives = "" }
WordHunterWoW_QuestEN[9693] = { title = "What Argus Means to Me", description = "What does Argus mean to you, {name}? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar.\n\nEredar... this word once held meaning.\n\n<Admetius smacks his lips as if to taste the word.>\n\nDisgusting.\n\nLet us not waste anymore time. Find Vindicator Boros to begin your training.", objectives = "" }
WordHunterWoW_QuestEN[9694] = { title = "Blood Watch", description = "Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.", objectives = "" }
WordHunterWoW_QuestEN[9695] = { title = "The Sun King's Command", description = "This document looks to be important. Unfortunately, it is written in Thalassian, a language that you cannot understand.\n\nPerhaps Vindicator Boros will know what to do with the letter.", objectives = "" }
WordHunterWoW_QuestEN[9696] = { title = "Translations...", description = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.", objectives = "" }
WordHunterWoW_QuestEN[9697] = { title = "Watcher Leesa'oh", description = "There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh.  And trust me, once you get out into the field, you'll find the work to be challenging.\n\nSeek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south.  Follow the path west and you will eventually find her.  She can be a bit -- studious -- but don't let that get to you.\n\nOh, and watch out for her cat.", objectives = "" }
WordHunterWoW_QuestEN[9698] = { title = "Audience with the Prophet", description = "I need you to deliver the translated documents to Velen personally, {name}. I don't trust that deranged messenger.\n\nExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.\n\nMake haste!\n", objectives = "" }
WordHunterWoW_QuestEN[9699] = { title = "Truth or Fiction", description = "I thank you for the timely delivery, {name}. You are turning out to be one of the Hand's better agents.\n\nIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.\n\nWould you be interested in some reconnaissance work?\n\nIf so, take these orders back to Vindicator Boros. He will give you your next mission.", objectives = "" }
WordHunterWoW_QuestEN[9700] = { title = "I Shoot Magic Into the Darkness", description = "Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.\n\nBe warned, {name}; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.\n", objectives = "" }
WordHunterWoW_QuestEN[9701] = { title = "Observing the Sporelings", description = "We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them.  One way to do that is what I'm doing; passive observation while making a note of their interactions.\n\nI need you to head over to the Spawning Glen to the west.  Investigate the whole area and then return to tell me what you saw.", objectives = "" }
WordHunterWoW_QuestEN[9702] = { title = "A Question of Gluttony", description = "I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason.  This just will not do!\n\nI mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out!\n\nHere's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.", objectives = "" }
WordHunterWoW_QuestEN[9703] = { title = "The Cryo-Core", description = "We have others pursuing leads on the sun portals, {name}. I need you to focus on the task at hand.\n\nBoros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.\n\nThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.\n", objectives = "" }
WordHunterWoW_QuestEN[9704] = { title = "Slain by the Wretched", description = "It's hard work being an outrunner between Sunstrider Isle and Falconwing Square.  Tight deadlines, long hours and worst of all... the Wretched!\n\nThe road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals.  Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages.\n\nI see you're eager to prove yourself.  Venture into Dawning Lane and see if you can find any traces of our outrunner.", objectives = "" }
WordHunterWoW_QuestEN[9705] = { title = "Package Recovery", description = "You take the package and confirm that indeed it comes from Magistrix Erona.  Alarion would probably want you to bring it to her.", objectives = "" }
WordHunterWoW_QuestEN[9706] = { title = "Galaen's Journal - The Fate of Vindicator Saruan", description = "Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.", objectives = "" }
WordHunterWoW_QuestEN[9708] = { title = "Familiar Fungi", description = "Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh!\n\nTo the north is a place known as the Hewn Bog.  Odd name for the place if you ask me, but I've never been there.  I'll need samples of those mushrooms to confirm my hypothesis.\n\nJust be careful, {class}.  I'd heard that ogres have moved in to the area, so you'll have to get the samples from them.  Could that be why the bog lords are no longer going there for their food?", objectives = "" }
WordHunterWoW_QuestEN[9709] = { title = "Stealing Back the Mushrooms", description = "{class}, I've got an idea.   I want you to head north again, this time into the heart of ogre territory!\n\nNorthwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge.\n\nThe ogres must be storing the harvested mushrooms there.  I bet you'll find them all over the place, and probably on the ogres themselves, too!\n\nBring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.", objectives = "" }
WordHunterWoW_QuestEN[9711] = { title = "Matis the Cruel", description = "Matis will be brought to justice, {name}; and I want you to be the one to find him and bring him back to the Triumvirate.\n\nScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.", objectives = "" }
WordHunterWoW_QuestEN[9716] = { title = "Disturbance at Umbrafen Lake", description = "We came to Outland expecting to find small pockets of life.  What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem.\n\nOur initial assessment of the area was deceiving, however.  The water levels at the lakes and marshes have consistently been going down since we started taking measurements.\n\nThe impact this could have on the local animal and plant life is disastrous.  Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.", objectives = "" }
WordHunterWoW_QuestEN[9718] = { title = "As the Crow Flies", description = "We must determine how widespread the naga's activity truly is and react accordingly.\n\nExploring each body of water in Zangarmarsh could be a lengthy undertaking.  If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh.\n\nHold this amulet above the balcony near me when you're ready to begin.  I will guide your way back to safety after we're done.", objectives = "" }
WordHunterWoW_QuestEN[9720] = { title = "Balance Must Be Preserved", description = "I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.\n\nThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.\n\nThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, {name}.  Restore the balance that the naga have upset.", objectives = "" }
WordHunterWoW_QuestEN[9724] = { title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", objectives = "" }
WordHunterWoW_QuestEN[9726] = { title = "Now That We're Friends...", description = "The naga of the Bloodscale Enclave to the northeast have begun to kill our people.  We cannot allow this to continue, {class}!\n\nWe suggest that you teach them a lesson as proof of our friendship.", objectives = "" }
WordHunterWoW_QuestEN[9728] = { title = "A Warm Welcome", description = "While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area.\n\nEver since we set foot in Zangarmarsh, the naga have launched lethal attacks against us without warning.  We've done our best to keep them at bay, but our resources are limited.\n\nI want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed.  Bring me their claws as proof of your victories.", objectives = "" }
WordHunterWoW_QuestEN[9729] = { title = "Fhwoor Smash!", description = "Little naga make Fhwoor angry!  Sporelings good friend to Fhwoor, so Fhwoor get naga ark.\n\nWe go into nearby naga village. You help?", objectives = "" }
WordHunterWoW_QuestEN[9730] = { title = "Leader of the Darkcrest", description = "A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, leader of the Darkcrest naga.  Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh.\n\nThe Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot.", objectives = "" }
WordHunterWoW_QuestEN[9731] = { title = "Drain Schematics", description = "The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake.\n\nIf the schematics are correct, there is a giant drain in the center of Serpent Lake.  Confirm this and bring the news to Cenarion Refuge.", objectives = "" }
WordHunterWoW_QuestEN[9732] = { title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.  ", objectives = "" }
WordHunterWoW_QuestEN[9739] = { title = "The Sporelings' Plight", description = "You there!  You must help us!\n\nThe fungal giants are devouring all of our spore sacs!  You must do something, or we'll lose our young!\n\nThe spore sacs start out large and become smaller as the air inside them is depleted.  Look for the small, mature spore sacs and save as many of them as you can!", objectives = "" }
WordHunterWoW_QuestEN[9740] = { title = "The Sun Gate", description = "Thanks to you and the work you did, my scouts were able to find the sun gate. The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty.\n\nThe strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!", objectives = "" }
WordHunterWoW_QuestEN[9741] = { title = "Critters of the Void", description = "Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it...\n\n<Loryi points at Jorli.>\n\nWhatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters. \n\nWe must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.", objectives = "" }
WordHunterWoW_QuestEN[9743] = { title = "Natural Enemies", description = "Us sporelings and the bog lords have never gotten along well.  In the past, we've managed to keep them at bay with spears and stones.  Lately they seem to have become more aggressive... or more desperate.  They do not fear us or our weapons.\n\nYou are much scarier and better armed than us.  If you were to fight the boglords for us, we'd be forever in your debt!  Bring me their tendrils so I know how many you've killed.", objectives = "" }
WordHunterWoW_QuestEN[9746] = { title = "Limits of Physical Exhaustion", description = "Victory is close at hand, {name}. With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers.\n\nTo the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9747] = { title = "The Umbrafen Tribe", description = "The naga are terrible, yes.  But even more terrible are the traitor tribes of Broken and Lost Ones that helped them!\n\nThe worst of all are the Lost Ones of the Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel to escaped slaves and would slit my throat if I left the refuge even for a day.\n\nTravel to Umbrafen Village south of here and kill them and their leader, Kataru.  Until then I will fear for my life every single day.", objectives = "" }
WordHunterWoW_QuestEN[9748] = { title = "Don't Drink the Water", description = "Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information.\n\n<Aesom points to a flask and nods.>\n\nYou are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9749] = { title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!\n", objectives = "" }
WordHunterWoW_QuestEN[9751] = { title = "The Bloodcurse Legacy", description = "Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of Blood Watch?\n", objectives = "" }
WordHunterWoW_QuestEN[9752] = { title = "Escape from Umbrafen", description = "You must help me get out of here!\n\nI was gathering herbs nearby when a handful of these little savages abducted me.  I tried to fight them off, but there were too many of them.\n\nHelp me return to the Cenarion Refuge and away from these cruel wretches and their vile magic!", objectives = "" }
WordHunterWoW_QuestEN[9753] = { title = "What We Know...", description = "We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar.\n\nLight be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage.\n\nWith this knowledge, Admetius has devised a plan. Seek him out.", objectives = "" }
WordHunterWoW_QuestEN[9756] = { title = "What We Don't Know...", description = "Our attempts at interrogation have failed miserably, {name}. Torture is - of course - out of the question. What we need is a {race} on the inside.\n\nI can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent.\n\nUnder this guise, I want you to get whatever information you can out of the prisoner.\n\nAnd {name}, do not leave Blood Watch while disguised as the spell will fail.", objectives = "" }
WordHunterWoW_QuestEN[9758] = { title = "Return to Arcanist Vandril", description = "Now my friend, if you would be so kind as to return to Arcanist Vandril, I know that he is very anxious to send you out on your first mission here in the Ghostlands.\n\nWe're counting on you, {name}.  Don't let us down.", objectives = "" }
WordHunterWoW_QuestEN[9759] = { title = "Ending Their World", description = "Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.\n\nI won't think less of you if you just walk away, {name}.\n\nBut maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?", objectives = "" }
WordHunterWoW_QuestEN[9760] = { title = "Vindicator's Rest", description = "I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, {name}; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment.\n\nTake the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[9761] = { title = "Clearing the Way", description = "Only the most battle hardened, noble and positively fearless will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide...\n\n<Corin sighs.>\n\nMy job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.", objectives = "" }
WordHunterWoW_QuestEN[9762] = { title = "The Unwritten Prophecy", description = "", objectives = "" }
WordHunterWoW_QuestEN[9769] = { title = "There's No Explanation for Fashion", description = "<Magasha chuckles softly to herself.>\n\nI bet if they knew they were wearing bug parts, the fashion trend would end very quickly.\n\nWe first started killing the bugs 'round here 'cause they were getting in the way of our construction. Some enterprising merchant stops here, spends the night, and next thing you know he's buyin' up all the bug wings we have!\n\nSays he makes clothes out of 'em. I be stickin' to my armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.", objectives = "" }
WordHunterWoW_QuestEN[9770] = { title = "Menacing Marshfangs", description = "Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay.\n\nThe whole place is crawling with the pests! It's just not right. Shouldn't something be eating these despicable things?\n\nWe've all been taking turns playing exterminator. You showed up at just the right time, {name}. Congratulations! Now get out there and mop up some marshfangs!", objectives = "" }
WordHunterWoW_QuestEN[9771] = { title = "Searching for Scout Jyoba", description = "Now that you're familiar with the terrain, I'd like to ask your help with something else. The Dead Mire, we've taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn't stay for very long, either.\n\nScout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn't returned. It's not like him to be gone that long without sending some kind of report. Will you search for him, {name}?", objectives = "" }
WordHunterWoW_QuestEN[9772] = { title = "Jyoba's Report", description = "Flecks of withered fungus dot the body of Scout Jyoba. Whatever killed him must've been made of the same dying fungus as the giant wilting mushrooms of the Dead Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his report.\n\nWithout the text of the report, it's nearly impossible to tell what the scout discovered. If the report can be found, it should be returned to Zurai.", objectives = "" }
WordHunterWoW_QuestEN[9773] = { title = "No More Mushrooms!", description = "Mushroom soup, mushroom stew, mushroom sauce!\n\nMushroom, mushroom, mushroom! It's all there is to eat around here. If you say you're hungry, the cook hands you an axe and tells you to go chop down your dinner!\n\nWell, I'm tired of mushrooms. I've seen fish in the lakes around here. Sure, they look like a nasty piece of work, but they've got to be better than mushrooms!\n\nHow much will it cost me to hire you to bring me my first decent meal in weeks?", objectives = "" }
WordHunterWoW_QuestEN[9774] = { title = "Thick Hydra Scales", description = "Reavij was wise to bring leather armor. This swamp will render my mail useless before long.\n\nI've been replacing the scales bit by bit as I'm able. The hydra in the marsh have thick, protective scales that stand up well to the dampness of their home.\n\nFinding suitable ones is a tedious process, though. All too often, the best scales are torn or worn too thin for use in armor. Bring me any good ones that you might get from the hydra in the larger lakes.", objectives = "" }
WordHunterWoW_QuestEN[9775] = { title = "Report to Shadow Hunter Denjai", description = "Shadow Hunter Denjai will no doubt expect to receive a report about my progress in establishing our outpost. I've prepared a short summary of what we've accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to take the report to Denjai's base of Zabra'jin to the west.\n\nIf you're headed that way, would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating at first, but once you get used to him, he's not so bad.", objectives = "" }
WordHunterWoW_QuestEN[9776] = { title = "The Orebor Harborage", description = "As you know, many of Telredor's inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready.\n\nWe owe them whatever help we can provide, {name}. A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.", objectives = "" }
WordHunterWoW_QuestEN[9777] = { title = "Fulgor Spores", description = "There is little in this swamp that will burn, {race}, so we must resort to other means for lighting Telredor. Many of the creatures and plants in the marsh emit a soft glow.\n\nIt's difficult and cruel to confine the glowing creatures, so we've turned to a species of mushroom for our light source.\n\nWe pick and cultivate the fulgor mushroom here, but our needs require us to gather new crops occasionally. The small green mushrooms often grow at the base of larger ones near Telredor.", objectives = "" }
WordHunterWoW_QuestEN[9778] = { title = "Warden Hamoot", description = "Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot.  He's in charge of the expedition's security.\n\nHe would never forgive me if I didn't send a seasoned adventurer like you his way.", objectives = "" }
WordHunterWoW_QuestEN[9779] = { title = "Intercepting the Message", description = "It is good to see you again, {name}. I have a quandary that you might be able to solve.\n\nOur agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document.\n\nUnfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.", objectives = "" }
WordHunterWoW_QuestEN[9780] = { title = "Umbrafen Eel Filets", description = "It's good to see another fresh face here. When Haalrun and I first came to Telredor, we were the only outsiders, but that seems like a lifetime ago.\n\nStill, we try to welcome newcomers and ensure that there's always enough food and supplies. We can never fully repay the kindness of the Telredor anchorites, but we can follow their example and extend it to others.\n\nIf you would like to help, the nearby lakes are populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.", objectives = "" }
WordHunterWoW_QuestEN[9781] = { title = "Too Many Mouths to Feed", description = "On my last hunting trip, I caught sight of a new outpost being built by a group of trolls. No doubt they've begun hunting these lands, too.\n\nIf they establish a permanent presence out here, the competition for food will be fierce. We cannot take direct action against them without provocation, but we can remove some of the natural competition for food.\n\nFor each mire hydra you kill, that's three fewer mouths to feed!", objectives = "" }
WordHunterWoW_QuestEN[9782] = { title = "The Dead Mire", description = "I have lived among the anchorites of Telredor for some time, {name}, and in that time I've come to know the marsh quite well. Recently, I've started to notice a disturbing change in the land to the northeast.\n\nVirtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.", objectives = "" }
WordHunterWoW_QuestEN[9783] = { title = "An Unnatural Drought", description = "The soil sample you brought me is nearly devoid of moisture, {name}. If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly.\n\nI've seen what happens when the region's fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path.\n\nThese creatures have no idea what's happening to them. They're beyond our ability to save, so the best we can do is to end their suffering.", objectives = "" }
WordHunterWoW_QuestEN[9785] = { title = "Blessings of the Ancients", description = "You've earned the trust of the Cenarion Expedition, {name}.  It is time you spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their blessing.\n\nCarrying the mark of an ancient will fill you with great power.  These boons will become more powerful as your renown among us increases.\n\nGo, {name}, and ask the ancients for their blessing. ", objectives = "" }
WordHunterWoW_QuestEN[9786] = { title = "The Boha'mu Ruins", description = "Before my people were decimated by the orcs, Telredor served as a retreat for draenei anchorites and spiritualists. A small order of anchorites and vindicators maintained a number of shrines in this region.\n\nDuring the war, we lost contact with the anchorites assigned to the shrines, particularly the Boha'mu temple to the southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.", objectives = "" }
WordHunterWoW_QuestEN[9787] = { title = "Idols of the Feralfen", description = "From what you've told me about your observations at the Boha'mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs.\n\nReturn to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, {name}, as it may hurt our chances of making contact with them.", objectives = "" }
WordHunterWoW_QuestEN[9788] = { title = "A Damp, Dark Place", description = "Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village.  Little did I know that the cave was being fought over by marsh beasts and spore men!\n\nI had to leave in a hurry and left behind a box containing my only worldly possessions.\n\nAfter managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after.  If you're willing to bring them back to me I'll give you one of my very own personal items.  What do you say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[9789] = { title = "Clefthoof Mastery", description = "You want to earn a place in this safari?  You'll have to prove yourself.\n\nI don't care what you've hunted before, you haven't hunted until you hunt what we hunt here.  Start with the clefthoof if you're man enough.\n\nI know that I've seen them in the immediate area around the safari and also close by to the south.", objectives = "" }
WordHunterWoW_QuestEN[9790] = { title = "Diaphanous Wings", description = "Living in such a remote location has taught us to make use of everything available. Of course, you have to learn to stop thinking about where some of these materials come from first.\n\nI've found that the wings of the umbraglow stingers are very helpful for waterproofing. They're strong, thin, and flexible.\n\n<Haalrun chuckles.>\n\nI see the look on your face. Like I said, it takes time to get used to the idea. If you're going to be out and about, would you mind bringing me some of the wings?", objectives = "" }
WordHunterWoW_QuestEN[9791] = { title = "Menacing Marshfangs", description = "During the orcs' war against my people, gatherers rarely left Telredor for fear of being attacked or captured. Now, we venture out more often, but the marsh is no less perilous.\n\nIt seems that the nether rays have grown bolder in recent months. I don't know if it has something to do with more competition for their normal prey, but they've been attacking our foraging parties on a regular basis. If we can thin their ranks in the area around Telredor, perhaps they would learn to leave us alone.", objectives = "" }
WordHunterWoW_QuestEN[9792] = { title = "A Message to Telaar", description = "You've been honorable in our dealings, {name}, at a time when trust is hard to win among my people.\n\nA large group of my brethren have made their home in the old draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south into Nagrand, then continue southeast until you find yourself in the cliffs east of Oshu'gun.\n\nAnyone who has aided us, as you have, would be welcome among the people of Telaar.\n\nSeek out Warden Moi'bff Jill and tell him you have earned my trust.", objectives = "" }
WordHunterWoW_QuestEN[9793] = { title = "The Fate of Tuurem", description = "Prophet Velen's search for allies has emboldened those draenei remaining in Outland to begin a search of their own. The Legion's war on my people drove us from our cities and temples, but they have not destroyed the traces of our civilization.\n\nTuurem, my former home in the Terokkar Forest, was one of the first cities overrun by the orcs. It's been too long since I've received news of its status. Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you can find out.", objectives = "" }
WordHunterWoW_QuestEN[9794] = { title = "No Time for Curiosity", description = "{name}, I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full.\n\nI have an associate named Kialon at Sylvanaar in the Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, although I suspect he won't like what I have to say.\n\nIf you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon's eyes alone.", objectives = "" }
WordHunterWoW_QuestEN[9795] = { title = "The Ogre Threat", description = "As if the naga and their allies weren't enough, the ogres are extending their reach in the marsh. They've already conquered most of the area to the northwest and there isn't much of a buffer left.\n\nFor each one we kill, several more take their place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.", objectives = "" }
WordHunterWoW_QuestEN[9796] = { title = "News from Zangarmarsh", description = "Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of her messengers travel through here.\n\nShe asked me to send word once Swamprat Post was completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up and running, but there is still much to be done.\n\nTo get to Stonebreaker Hold, follow the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.", objectives = "" }
WordHunterWoW_QuestEN[9797] = { title = "Reinforcements for Garadar", description = "<Still catching his breath, the messenger gestures for you to sit.>\n\nThey may not survive, {race}! Get to Garadar as quickly as your legs will carry you.\n\n<In response to your blank stare, the messenger elaborates.>\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nFind our commander, Captain Kroghan, there and offer him what assistance you can. Garadar must not fall!", objectives = "" }
WordHunterWoW_QuestEN[9798] = { title = "Blood Elf Plans", description = "These plans seem important.  You should take them to Vindicator Aldar at the crash site.", objectives = "" }
WordHunterWoW_QuestEN[9799] = { title = "Botanical Legwork", description = "The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake.\n\nGo to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.", objectives = "" }
WordHunterWoW_QuestEN[9800] = { title = "A Rare Bean", description = "You are ill-equipped to face the restless elements of Nagrand. Before you can help the Earthen Ring, you must help yourself.\n\nTo the west you will find dung heaps left behind by the wildlife of Nagrand. You must search the dung for the digested remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will aid you in your battle against the restless forces of nature.\n\nReturn to me when you have collected no less than two fists worth of caracoli... Ogre sized fists.", objectives = "" }
WordHunterWoW_QuestEN[9801] = { title = "Gathering the Reagents", description = "I have a feeling that these Lost Ones may not respond well to a draenei, but would welcome an arakkoa. I can create a potion that will allow you to take on the form of an arakkoa for a short time. It requires a couple of reagents which cannot be stored and must be used within hours of being gathered.\n\nYou will need to bring me a handful of sporebat eyes and some fen strider tentacles. Both species dwell in the wilderness surrounding Telredor.", objectives = "" }
WordHunterWoW_QuestEN[9802] = { title = "Plants of Zangarmarsh", description = "The lakes of Zangarmarsh are slowly being drained of their water.  We don't quite know why, but we do know that many plants species are in danger of becoming extinct.\n\nAs the expedition's cataloguer, it is my job to track and identify these plants so we can better understand what's happening to them.\n\nIf you'd like to help, bring me unidentified plant parts.  They can be picked right from the ground if you're an herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.", objectives = "" }
WordHunterWoW_QuestEN[9803] = { title = "Messenger to the Feralfen", description = "The time has come for us to embrace the Feralfen and teach them that the Light has not forsaken them. Take the potion I've prepared and carry it with you to the Boha'mu Ruins.\n\nOnce you arrive at the ruins, drink the potion to assume the form of one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are ready to welcome his people as our long lost brothers.", objectives = "" }
WordHunterWoW_QuestEN[9804] = { title = "Agitated Spirits of Skysong", description = "The disturbance in the ebb and flow of the waters of Nagrand has greatly agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction throughout the waterways of the area.\n\nWatoosun of the Water has come to us in a vision and granted us permission to remedy the problem - so long as the source of the disturbance is also dealt with...\n\nWe will get to the source, but first you must deal with the problems immediate to the Throne. Destroy the agitated lake spirits and return to me.", objectives = "" }
WordHunterWoW_QuestEN[9805] = { title = "Blessing of Incineratus", description = "The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are seeking to spread their filth to other parts of our world.\n\nI have sought the wisdom of the furies and gained their blessing. To stop the source, we must unleash the elements upon them!\n\nI give you living fire, plucked from the fiery essence of Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the living fire upon their huts! Let them see the fury of the elements!", objectives = "" }
WordHunterWoW_QuestEN[9806] = { title = "Fertile Spores", description = "Spore bats and marsh walkers accumulate fertile spores on their appendages from wandering around the tallstalk mushrooms in the marsh.\n\nAs you can see, we're a short people so our options for gathering these spores are limited.  Seek out the spore bats and marsh walkers and gather the fertile spores.  All of Sporeggar will be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[9808] = { title = "Glowcap Mushrooms", description = "I've seen your kind use shiny round pieces of metal to trade for things that you need.  We're not so different from you.  We use shiny round mushrooms as our currency.\n\nGlowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them.  I'll teach you how to do it, if you promise to bring us some for our reserves.  What do you say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[9810] = { title = "The Spirit Polluted", description = "Watoosun was able to shed the stink of corruption; but in doing so, created a twisted spirit essence. A spirit essence composed of the vilest corruption found amongst the elements!\n\nYou will find this polluted spirit of the swamp southwest of here, hidden in the depths of Lake Sunspring.\n\nFind and destroy the polluted essence of Watoosun and any corrupt offspring that it may have created.", objectives = "" }
WordHunterWoW_QuestEN[9811] = { title = "Friend of the Sin'dorei", description = "This is the beginning of a new chapter in blood elf history, {name}.  You've helped cement the bond between my race and yours, {race}.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", objectives = "" }
WordHunterWoW_QuestEN[9812] = { title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[9813] = { title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", objectives = "" }
WordHunterWoW_QuestEN[9814] = { title = "Burstcap Mushrooms, Mon!", description = "You like mushrooms, mon? There be a powerful one here in Zangarmarsh, growin' real close to Zabra'jin.\n\nYou gotta be careful, though, mon. They be callin' it the burstcap for a reason. If you be gettin' too close without takin' the proper precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores.\n\nI been usin' them for readin' the omens, but they be almost gone now.", objectives = "" }
WordHunterWoW_QuestEN[9815] = { title = "Muck Diving", description = "The most affected elements of water can be found in the Halaani Basin, southwest of here, beneath the abandoned city of Halaa. While some distressed elements can be destroyed without any impact upon the environment, spawns of muck must be physically removed from the world once destroyed.\n\nYou see, muck spawns leave behind globules of tainted debris that if left untouched will spread and further contaminate the environment.\n\nDestroy these muck spawns and bring back their muck-ridden cores.", objectives = "" }
WordHunterWoW_QuestEN[9816] = { title = "Have You Ever Seen One of These?", description = "This marsh be missin' one thing, mon! There be no murlocs here.\n\nDon't worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to give the gift o' murlocs to the Lost Ones!\n\nTake this cage with you to Daggerfen Village an' release 'em in the northeastern cluster of huts. Now you know I can't be riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young murlocs. Just set it on the flat rock you be findin' up there and open the door!", objectives = "" }
WordHunterWoW_QuestEN[9817] = { title = "Leader of the Bloodscale", description = "A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader of the Bloodscale naga.  The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh.\n\nThe Bloodscale are to be considered extremely dangerous and their leader is to be approached with extreme caution.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.", objectives = "" }
WordHunterWoW_QuestEN[9818] = { title = "The Underneath", description = "Something rails the underneath. It beats the ground as if to punish.\n\n*Thud*\n\n<Untrag beats his chest with his fist.>\n\nIt makes this sound a hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us now.\n\nGordawg speaks to me. Gordawg knows that something forces the elements out. Something from the underneath.\n\nGo now and speak to Gordawg. No, listen to Gordawg, do not speak. Hear Gordawg...", objectives = "" }
WordHunterWoW_QuestEN[9819] = { title = "The Tortured Earth", description = "Bring up the usurper. You will find him. Follow earthen path. First you put to rest tortured earth spirits. Must sleep once more.\n\n<Gordawg smashes his fist into the ground and brings up very foul smelling soil.>\n\nMust sleep!\n\n<Gordawg points southeast.>\n\nFind spirits near mountains. Near hills. Near rocks. Near earth.\n\nPut to sleep.\n\nTelaari Basin... Southeast.\n", objectives = "" }
WordHunterWoW_QuestEN[9820] = { title = "WANTED: Boss Grog'ak", description = "Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh mushroom-cutting operation.\n\nThis brute and his axe-wielding cronies are responsible for chopping down the mushrooms to the north of town. Unless he is stopped, he and his band will cut a path to the walls of Zabra'jin.\n\nHe who presents the head of Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.", objectives = "" }
WordHunterWoW_QuestEN[9821] = { title = "Eating Damnation", description = "<Gordawg picks up a rock and begins to chew on it.>\n\nGordawg tastes. Gordawg knows where this earth has been.\n\n<Gordawg raises one of his massive legs and stomps the ground.>\n\nLook. See Nagrand.\n\n<Gordawg directs you to the imprint of his foot. Within the imprint you see what appears to be a perfect geological map of Nagrand, marked with the locations of where you can find the elementals Gordawg wants you to destroy.>\n\nBREAK THEM! Bring Gordawg the pieces to eat.\n\nTake the map.", objectives = "" }
WordHunterWoW_QuestEN[9822] = { title = "Impending Attack", description = "The position of the ogres' mushroom-cutting operation can't be an accident. I can't escape the suspicion that they're preparing for an attack on Zabra'jin.\n\nI must know for certain, {name}. The ogres have another outpost to the northwest, the Ango'rosh Grounds. If they're staging for an attack, there will be evidence of their plans there. Go there, {name} and search the camp for signs of their intentions. Return to me with anything that might be suspicious.", objectives = "" }
WordHunterWoW_QuestEN[9823] = { title = "Us or Them", description = "In order to end the Ango'rosh threat, we must kill their leader, Overlord Gorefist. We'll do better than that, though. We'll make an example of the overlord and his followers.\n\nGo to the Ango'rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra'jin. You'll see a bridge made from a fallen mushroom beyond the Ango'rosh Camp.\n\nShow no mercy, {name}. They certainly wouldn't spare any of us.", objectives = "" }
WordHunterWoW_QuestEN[9827] = { title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", objectives = "" }
WordHunterWoW_QuestEN[9828] = { title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", objectives = "" }
WordHunterWoW_QuestEN[9830] = { title = "Stinger Venom", description = "When I speak to draenei, I often get the sense that they consider themselves removed from their environment. Many seem to pity my brethren, the Broken, who they say have lost something.\n\nWe Broken may have lost our inclination toward the Light, but our experiences have brought us closer to the land.\n\nMy people see opportunities where few draenei do. Take, for example, the venom of the marshlight bleeders that live to the south and west. It has a wide variety of uses from hunting to healing.", objectives = "" }
WordHunterWoW_QuestEN[9833] = { title = "Lines of Communication", description = "One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of communication between the draenei and the Kurenai home city of Telaar in Nagrand. In order for messengers to pass swiftly between Telaar and Telredor, the roads must be secured.\n\nOn our way here, we were attacked repeatedly by marshfang slicers. We were able to fight them off, but they would pose a formidable threat to a solitary messenger. Reducing their numbers will help ensure the safety of our messengers.", objectives = "" }
WordHunterWoW_QuestEN[9834] = { title = "Natural Armor", description = "Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp!\n\nMaktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor.\n\nThe dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If {name} can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.", objectives = "" }
WordHunterWoW_QuestEN[9835] = { title = "Ango'rosh Encroachment", description = "The small band of Broken you see here is a mission from a larger settlement in Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our draenei brothers.\n\nMy group has come here to strengthen Kurenai ties to the draenei of Telredor.\n\nIf the Ango'rosh ogres have their way, this temple will not stand much longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to our refuge. If you would call yourself our friend, aid us in fighting this enemy.", objectives = "" }
WordHunterWoW_QuestEN[9839] = { title = "Overlord Gorefist", description = "The centerpiece of any ogre tribe is its leader. Without leadership, the Ango'rosh's organization will disappear and they'll resort to infighting to determine who will lead next.\n\nAlthough we've seen the ogres out and about in this area, their true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's located in a cave on a small island connected to the marsh by a fallen mushroom.\n\nGo there and defeat Overlord Gorefist. That should provide us with a well-deserved respite.", objectives = "" }
WordHunterWoW_QuestEN[9841] = { title = "Stinging the Stingers", description = "It's impossible to work with all this infernal buzzing! Do you hear it?\n\nI can't get it out of my head! I know exactly what's making the noise, too. It's those damnable marshlight bleeders! The noise always comes from the south and west of the village.\n\nThey're too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don't care how you do it, {name}, just quiet them!", objectives = "" }
WordHunterWoW_QuestEN[9842] = { title = "The Sharpest Blades", description = "The damp atmosphere of the marsh has taken a toll on my metal tools. It's made woodworking a lot more difficult than it ought to be, so I've given up on metal blades.\n\nIt turns out that the marshfang slicers living to the south and west of town grow blades that are sharper than any steel I've ever owned. They're also resistant to rust and wear. It's just a little tricky to attach them to a handle, but I think I've got it figured out. I'd appreciate any blades you could bring me.", objectives = "" }
WordHunterWoW_QuestEN[9845] = { title = "Angling to Beat the Competition", description = "It's a relief to be in someplace with water after trekking through the wasteland of Hellfire Peninsula. I was worried there might not be any respectable fishing holes in Outland.\n\nNow I'm glad I lugged my fishing supplies along. For the most part, the fishing's been good, except for those no good fenclaw thrashers in Serpent Lake.\n\nNot only do they scare the fish away, but they're bold enough to snap the bait right off my hook. I spend more time re-baiting the hook than I do catching anything!", objectives = "" }
WordHunterWoW_QuestEN[9846] = { title = "Spirits of the Feralfen", description = "The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored.\n\nFind the Feralfen mystics, hunters and druids, {name}, and capture their totems. Everything I need to know should be apparent from the carvings.", objectives = "" }
WordHunterWoW_QuestEN[9847] = { title = "A Spirit Ally?", description = "We must find out how much power this Feralfen snake spirit possesses and whether it can be bent to our will. Imagine what I could do with the powers of an Outland spirit at my command!\n\nTake this totem with you and make your way to the foot of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should do the rest. The spirit should not be able to tell who has used the totem until it has manifested.", objectives = "" }
